    },
  },
  neutral: {
    name: 'Neutral',
    description: 'Clean balanced graphite',
    swatch: '#737373',
    ramps: {
      0: '#ffffff',
      50: '#fafafa',
      100: '#f5f5f5',
      200: '#e5e5e5',
      300: '#d4d4d4',
