    },
  },
  oled: {
    name: 'OLED Black',
    description: 'Pure #000000 contrast for deep OLED displays',
    swatch: '#000000',
    ramps: {
      0: '#ffffff',
      50: '#fafafa',
      100: '#f4f4f5',
      200: '#e4e4e7',
      300: '#d4d4d8',
      400: '#a1a1aa',
      500: '#52525b',
      600: '#3f3f46',
      700: '#27272a',
      800: '#141416',
      900: '#08080a',
      950: '#000000',
    },
  },
};

/**
 * Calculates WCAG 2.1 relative luminance and contrast ratio.
 */
export function getContrastRatio(hex1: string, hex2: string): number {
  function getLuminance(hex: string): number {
    let clean = hex.trim().replace(/^#/, '');
    if (clean.length === 3) clean = clean.split('').map((c) => c + c).join('');
    if (clean.length !== 6) return 0.5;
    const r = parseInt(clean.substring(0, 2), 16) / 255;
    const g = parseInt(clean.substring(2, 4), 16) / 255;
    const b = parseInt(clean.substring(4, 6), 16) / 255;
    const a = [r, g, b].map((v) => (v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)));
    return 0.2126 * (a[0] ?? 0) + 0.7152 * (a[1] ?? 0) + 0.0722 * (a[2] ?? 0);
  }
  const l1 = getLuminance(hex1);
  const l2 = getLuminance(hex2);
  const max = Math.max(l1, l2);
  const min = Math.min(l1, l2);
  return Number(((max + 0.05) / (min + 0.05)).toFixed(2));
}

export function getWcagRating(ratio: number): {
  level: 'AAA' | 'AA' | 'Fail';
  pass: boolean;
  label: string;
} {
  if (ratio >= 7.0) return { level: 'AAA', pass: true, label: `AAA Pass (${ratio}:1)` };
  if (ratio >= 4.5) return { level: 'AA', pass: true, label: `AA Pass (${ratio}:1)` };
  if (ratio >= 3.0) return { level: 'AA', pass: true, label: `AA Large (${ratio}:1)` };
  return { level: 'Fail', pass: false, label: `Low (${ratio}:1)` };
}

export interface BrandRampStep {
  key: number;
  value: string;
  hex: string;
}

/** 11-step lightness ladder tuned so 500 sits at ~50% L */
const RAMP_L = [97, 94, 87, 76, 62, 50, 44, 38, 32, 26, 15];
const RAMP_KEYS = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950];

/**
 * Converts a hex string (#RGB, #RRGGBB) to HSL values { h, s, l }.
 */
export function hexToHsl(hex: string): { h: number; s: number; l: number } {
  let cleaned = hex.trim().replace(/^#/, '');
  if (cleaned.length === 3) {
    cleaned = cleaned
      .split('')
      .map((c) => c + c)
      .join('');
  }
  if (cleaned.length !== 6) {
    return { h: 239, s: 84, l: 50 }; // fallback to indigo
  }

  const r = parseInt(cleaned.substring(0, 2), 16) / 255;
  const g = parseInt(cleaned.substring(2, 4), 16) / 255;
  const b = parseInt(cleaned.substring(4, 6), 16) / 255;

  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  let h = 0;
  let s = 0;
  const l = (max + min) / 2;

  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    switch (max) {
      case r:
        h = (g - b) / d + (g < b ? 6 : 0);
        break;
      case g:
        h = (b - r) / d + 2;
        break;
      case b:
        h = (r - g) / d + 4;
        break;
    }
    h = h / 6;
  }

  return {
    h: Math.round(h * 360),
    s: Math.round(s * 100),
    l: Math.round(l * 100),
  };
}

/**
 * Converts HSL values (h: 0-360, s: 0-100, l: 0-100) to hex string (#RRGGBB).
 */
export function hslToHex(h: number, s: number, l: number): string {
  const normS = s / 100;
  const normL = l / 100;

  const c = (1 - Math.abs(2 * normL - 1)) * normS;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = normL - c / 2;
  let r = 0;
  let g = 0;
  let b = 0;

  if (h >= 0 && h < 60) {
    r = c;
    g = x;
    b = 0;
  } else if (h >= 60 && h < 120) {
    r = x;
    g = c;
    b = 0;
  } else if (h >= 120 && h < 180) {
    r = 0;
    g = c;
    b = x;
  } else if (h >= 180 && h < 240) {
    r = 0;
    g = x;
    b = c;
  } else if (h >= 240 && h < 300) {
    r = x;
    g = 0;
    b = c;
  } else if (h >= 300 && h < 360) {
    r = c;
    g = 0;
    b = x;
  }

  const toHex = (n: number) => {
    const val = Math.round((n + m) * 255);
    return Math.max(0, Math.min(255, val)).toString(16).padStart(2, '0');
  };

  return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Builds the 11-step brand color ramp from hue and saturation.
 */
export function buildBrandRamp(hue: number, saturation: number): BrandRampStep[] {
  return RAMP_KEYS.map((key, index) => {
    const lightness = RAMP_L[index]!;
    // Nudge saturation down slightly at the dark end to maintain text contrast
    const sat = index >= 8 ? Math.max(saturation - 10, 8) : saturation;
    return {
      key,
      value: `hsl(${hue} ${sat}% ${lightness}%)`,
      hex: hslToHex(hue, sat, lightness),
    };
  });
}

/**
 * Generates an object of CSS variables for a custom theme configuration.
 */
export function generateThemeVariables(config: CustomThemeConfig): Record<string, string> {
  let hue = config.hue ?? 239;
  let saturation = config.saturation ?? 84;

  if (config.primaryColor && !config.hue) {
    const hsl = hexToHsl(config.primaryColor);
    hue = hsl.h;
    saturation = hsl.s;
  }

  const ramp = buildBrandRamp(hue, saturation);
  const vars: Record<string, string> = {};

  ramp.forEach((step) => {
    vars[`--pui-brand-${step.key}`] = step.value;
  });

  vars['--pui-primary'] = 'var(--pui-brand-500)';
  vars['--pui-primary-hover'] = 'var(--pui-brand-600)';
  vars['--pui-primary-active'] = 'var(--pui-brand-700)';
  vars['--pui-primary-subtle'] = 'color-mix(in oklab, var(--pui-brand-500) 14%, transparent)';
  vars['--pui-primary-border'] = 'color-mix(in oklab, var(--pui-brand-500) 38%, transparent)';
  vars['--pui-primary-fg'] = 'color-mix(in oklab, var(--pui-brand-400) 78%, var(--pui-fg))';
  vars['--pui-focus-ring'] = 'var(--pui-brand-500)';

  if (config.radius !== undefined) {
    const radNum = typeof config.radius === 'number' ? config.radius : parseFloat(config.radius);
    const validRad = isNaN(radNum) ? 8 : Math.max(0, radNum);
    vars['--pui-radius-sm'] = `${Math.round(validRad * 0.5)}px`;
    vars['--pui-radius-md'] = `${Math.round(validRad)}px`;
    vars['--pui-radius-lg'] = `${Math.round(validRad * 1.5)}px`;
    vars['--pui-radius-xl'] = `${Math.round(validRad * 2)}px`;
  }

  if (config.fontFamily) {
    vars['--pui-font-sans'] = config.fontFamily;
  }

  if (config.neutralBase && NEUTRAL_PALETTES[config.neutralBase]) {
    const pal = NEUTRAL_PALETTES[config.neutralBase].ramps;
    Object.entries(pal).forEach(([key, val]) => {
      vars[`--pui-neutral-${key}`] = val;
    });
    if (config.neutralBase === 'oled') {
      vars['--pui-bg'] = '#000000';
      vars['--pui-surface'] = '#09090b';
      vars['--pui-border'] = '#27272a';
    }
  }

  return vars;
}

/**
 * Generates copy-paste ready CSS string for :root or a custom selector.
 */
export function generateThemeCss(config: CustomThemeConfig, selector = ':root'): string {
  const vars = generateThemeVariables(config);
  const lines: string[] = [`${selector} {`, '  /* Brand ramp */'];

  RAMP_KEYS.forEach((key) => {
    const varName = `--pui-brand-${key}`;
    if (vars[varName]) {
      lines.push(`  ${varName.padEnd(20)}: ${vars[varName]};`);
    }
  });

  lines.push('');
  lines.push('  /* Semantic bindings */');
  lines.push('  --pui-primary:        var(--pui-brand-500);');
  lines.push('  --pui-primary-hover:  var(--pui-brand-600);');
  lines.push('  --pui-primary-active: var(--pui-brand-700);');
  lines.push('  --pui-primary-subtle: color-mix(in oklab, var(--pui-brand-500) 14%, transparent);');
  lines.push('  --pui-primary-border: color-mix(in oklab, var(--pui-brand-500) 38%, transparent);');
  lines.push('  --pui-primary-fg:     color-mix(in oklab, var(--pui-brand-400) 78%, var(--pui-fg));');
  lines.push('  --pui-focus-ring:     var(--pui-brand-500);');

  if (vars['--pui-radius-md']) {
    lines.push('');
    lines.push('  /* Corner radius */');
    lines.push(`  --pui-radius-sm:      ${vars['--pui-radius-sm']};`);
    lines.push(`  --pui-radius-md:      ${vars['--pui-radius-md']};`);
    lines.push(`  --pui-radius-lg:      ${vars['--pui-radius-lg']};`);
    lines.push(`  --pui-radius-xl:      ${vars['--pui-radius-xl']};`);
  }

  if (vars['--pui-font-sans']) {
    lines.push('');
    lines.push('  /* Typography */');
    lines.push(`  --pui-font-sans:      ${vars['--pui-font-sans']};`);
  }

  if (config.neutralBase && NEUTRAL_PALETTES[config.neutralBase]) {
    lines.push('');
    lines.push(`  /* Neutral palette (${NEUTRAL_PALETTES[config.neutralBase].name}) */`);
    const pal = NEUTRAL_PALETTES[config.neutralBase].ramps;
    Object.entries(pal).forEach(([key, val]) => {
      lines.push(`  --pui-neutral-${key}: ${val};`);
    });
    if (config.neutralBase === 'oled') {
      lines.push('  --pui-bg:             #000000;');
      lines.push('  --pui-surface:        #09090b;');
      lines.push('  --pui-border:         #27272a;');
    }
  }

  lines.push('}');
  return lines.join('\n');
}

const STYLE_TAG_ID = 'pui-custom-theme-vars';

/**
 * Injects or updates custom CSS variables in the document head.
 */
export function applyThemeStyle(css: string): void {
  if (typeof document === 'undefined') return;
  let tag = document.getElementById(STYLE_TAG_ID) as HTMLStyleElement | null;
  if (!tag) {
    tag = document.createElement('style');
    tag.id = STYLE_TAG_ID;
    document.head.appendChild(tag);
  }
  tag.textContent = css;
}

/**
 * Removes custom theme CSS variables from the document head.
 */
export function removeThemeStyle(): void {
  if (typeof document === 'undefined') return;
  const tag = document.getElementById(STYLE_TAG_ID);
  if (tag && tag.parentNode) {
    tag.parentNode.removeChild(tag);
  }
}

import * as React from 'react';
import { cn } from '../utils/cn';

/** Compose multiple refs into a single callback ref. */
export function composeRefs<T>(...refs: Array<React.Ref<T> | undefined>) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === 'function') ref(node);
      else if (ref) (ref as React.MutableRefObject<T | null>).current = node;
    }
  };
}

const REACT_MAJOR = parseInt(React.version || '18', 10);

function getElementRef(element: React.ReactElement): React.Ref<unknown> | undefined {
  // React 19 exposes `ref` as a prop; React 18 keeps it on the element object.
  if (REACT_MAJOR >= 19) return (element.props as { ref?: React.Ref<unknown> }).ref;
  return (element as unknown as { ref?: React.Ref<unknown> }).ref;
}

type AnyProps = Record<string, unknown>;

function mergeProps(slotProps: AnyProps, childProps: AnyProps): AnyProps {
  const merged: AnyProps = { ...slotProps, ...childProps };
  for (const key of Object.keys(slotProps)) {
    const a = slotProps[key];
    const b = childProps[key];
    if (/^on[A-Z]/.test(key)) {
      if (typeof a === 'function' && typeof b === 'function') {
        merged[key] = (...args: unknown[]) => {
          (b as (...a: unknown[]) => void)(...args);
          (a as (...a: unknown[]) => void)(...args);
        };
      } else if (typeof a === 'function') {
        merged[key] = a;
      }
    } else if (key === 'className') {
      merged[key] = cn(a as string, b as string);
    } else if (key === 'style') {
      merged[key] = { ...(a as object), ...(b as object) };
    }
  }
  return merged;
}

export interface SlotProps extends React.HTMLAttributes<HTMLElement> {
  children?: React.ReactNode;
}

/**
 * Slot enables `asChild` composition: merges props, styles, event handlers,
 * and forwarded refs directly onto its immediate child element.
 */
export const Slot = React.forwardRef<HTMLElement, SlotProps>(function Slot(
  { children, ...slotProps },
  forwardedRef
) {
  if (!React.isValidElement(children)) return null;
  const child = children as React.ReactElement<AnyProps>;
  const childRef = getElementRef(child);
  return React.cloneElement(child, {
    ...mergeProps(slotProps as AnyProps, child.props),
    ref: forwardedRef ? composeRefs(forwardedRef, childRef as React.Ref<HTMLElement>) : childRef,
  });
});

import { useEffect, type RefObject } from 'react';

export type ClickOutsideTarget = RefObject<HTMLElement | null> | HTMLElement | null | undefined;

/**
 * Invokes `callback` when a pointerdown or touch event occurs outside all target elements.
 */
export function useClickOutside(
  elements: ClickOutsideTarget | ClickOutsideTarget[],
  callback: (event: MouseEvent | TouchEvent) => void,
  active = true
) {
  useEffect(() => {
    if (!active || typeof document === 'undefined') return;

    const elementList = Array.isArray(elements) ? elements : [elements];

    const listener = (event: MouseEvent | TouchEvent) => {
      const target = event.target as Node | null;
      if (!target) return;

      const isInside = elementList.some((el) => {
        const dom = el && 'current' in el ? el.current : el;
        return dom ? dom.contains(target) : false;
      });

      if (!isInside) {
        callback(event);
      }
    };

    document.addEventListener('pointerdown', listener);
    return () => {
      document.removeEventListener('pointerdown', listener);
    };
  }, [elements, callback, active]);
}

import { useCallback, useState } from 'react';

export interface UseClipboardOptions {
  /** Duration in milliseconds before resetting `copied` state. @default 2000 */
  timeout?: number;
}

export interface UseClipboardReturn {
  copied: boolean;
  copy: (text: string) => Promise<boolean>;
  reset: () => void;
}

/**
 * React hook to copy arbitrary text to the user's clipboard.
 * Manages transient `copied` state with configurable auto-reset.
 *
 * @param options - Hook configuration options
 */
export function useClipboard(options: UseClipboardOptions = {}): UseClipboardReturn {
  const { timeout = 2000 } = options;
  const [copied, setCopied] = useState(false);

  const copy = useCallback(
    async (text: string): Promise<boolean> => {
      if (typeof window === 'undefined' || !navigator?.clipboard?.writeText) {
        console.warn('[hesh-ui] Clipboard API is unavailable in this environment');
        return false;
      }

      try {
        await navigator.clipboard.writeText(text);
        setCopied(true);

        setTimeout(() => {
          setCopied(false);
        }, timeout);

        return true;
      } catch (error) {
        console.warn('[hesh-ui] Failed to copy to clipboard:', error);
        setCopied(false);
        return false;
      }
    },
    [timeout]
  );

  const reset = useCallback(() => {
    setCopied(false);
  }, []);

  return { copied, copy, reset };
}

import { useCallback, useRef, useState } from 'react';

/**
 * Supports both controlled (`value` + `onChange`) and uncontrolled
 * (`defaultValue`) usage with a single code path.
 *
 * Returned setter is stable across renders, so it is safe in deps arrays.
 */
export function useControllableState<T>(options: {
  value?: T;
  defaultValue: T;
  onChange?: (value: T) => void;
}): [T, (next: T | ((prev: T) => T)) => void] {
  const { value, defaultValue, onChange } = options;
  const isControlled = value !== undefined;

  const [uncontrolled, setUncontrolled] = useState<T>(defaultValue);
  const current = isControlled ? (value as T) : uncontrolled;

  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  const setValue = useCallback(
    (next: T | ((prev: T) => T)) => {
      const resolver = (prev: T): T =>
        typeof next === 'function' ? (next as (p: T) => T)(prev) : next;

      if (!isControlled) setUncontrolled(resolver);
      onChangeRef.current?.(resolver(isControlled ? (value as T) : uncontrolled));
    },
    [isControlled, value, uncontrolled]
  );

  return [current, setValue];
}

import { useEffect, useState } from 'react';

/**
 * React hook that returns a debounced version of any value.
 *
 * @param value - The fast-changing value (e.g. search input text)
 * @param delay - Debounce duration in milliseconds (default: 300ms)
 */
export function useDebounce<T>(value: T, delay = 300): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return debouncedValue;
}

import { useEffect, type RefObject } from 'react';

/** The dismiss target: a live node, or a ref that resolves to one. */
export type DismissTarget = HTMLElement | null | RefObject<HTMLElement>;

export interface UseDismissOptions {
  escape?: boolean;
  outside?: boolean;
  /**
   * Extra nodes that count as "inside" — e.g. a menu rendered through a portal,
   * which is not a DOM descendant of its trigger.
   */
  ignore?: RefObject<HTMLElement>[];
}

/**
 * Runs `handler` on pointerdown outside `ref` and on Escape.
 * Used by menus, popovers, comboboxes and tooltips.
 *
 * Uses `pointerdown` (not `click`) so the menu closes before a click lands on
 * whatever is underneath — avoids the classic "click passed through" bug.
 */
export function useDismiss(
  ref: DismissTarget,
  active: boolean,
  handler: () => void,
  options: UseDismissOptions = {}
) {
  const { escape = true, outside = true, ignore = [] } = options;

  const self =
    ref && typeof ref === 'object' && 'current' in ref ? ref.current : (ref as HTMLElement | null);

  useEffect(() => {
    if (!active) return;
    const handlerRef = { current: handler };
    handlerRef.current = handler;

    const onPointerDown = (event: PointerEvent) => {
      if (!outside) return;
      const target = event.target as Node | null;
      if (!target) return;
      if (self?.contains(target)) return;
      if (ignore.some((item) => item.current?.contains(target))) return;
      handlerRef.current();
    };

    const onKeyDown = (event: KeyboardEvent) => {
      if (escape && event.key === 'Escape') {
        event.stopPropagation();
        handlerRef.current();
      }
    };

    document.addEventListener('pointerdown', onPointerDown, true);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('pointerdown', onPointerDown, true);
      document.removeEventListener('keydown', onKeyDown);
    };
    // `ignore` is a fresh array literal each render, so key on its contents.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [self, active, handler, escape, outside, ...ignore]);
}

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type MutableRefObject,
  type RefObject,
} from 'react';

export type Placement = 'top' | 'bottom' | 'left' | 'right';
export type Align = 'start' | 'center' | 'end';

export interface FloatingCoords {
  x: number;
  y: number;
  placement: Placement;
  anchorWidth?: number;
}

const GAP = 6;
const VIEWPORT_PADDING = 8;

export interface UseFloatingOptions {
  placement?: Placement;
  align?: Align;
  offset?: number;
  matchWidth?: boolean;
}

export interface UseFloatingReturn<T extends HTMLElement> {
  /**
   * Attach to the floating element. This is a *callback* ref, not a ref object:
   * the node is mirrored into state so positioning re-runs the moment it
   * appears. `<Portal>` mounts one commit after its parent, so a plain
   * `useRef` would still be empty when the layout effect first runs.
   */
  setFloating: (node: T | null) => void;
  /** Imperative escape hatch; kept in sync with `setFloating`. */
  floatingRef: MutableRefObject<T | null>;
  coords: FloatingCoords;
  placement: Placement;
  /** False until the element has been measured — keep it hidden until then. */
  ready: boolean;
  update: () => void;
  anchorWidth: number;
}

/**
 * Dependency-free fixed-positioning for floating layers.
 * Flips when there is no room and shifts to stay inside the viewport.
 *
 * Position: `fixed` + portal means no ancestor can clip or transform it.
 */
export function useFloating<T extends HTMLElement>(
  anchorRef: RefObject<HTMLElement>,
  active: boolean,
  options: UseFloatingOptions = {}
): UseFloatingReturn<T> {
  const { placement: preferred = 'bottom', align = 'start', offset = GAP, matchWidth = false } = options;

  const floatingRef = useRef<T | null>(null) as MutableRefObject<T | null>;
  const [floatingNode, setFloatingNode] = useState<T | null>(null);
  const [coords, setCoords] = useState<FloatingCoords>({ x: 0, y: 0, placement: preferred });
  const [ready, setReady] = useState(false);
  const [measuredAnchorWidth, setMeasuredAnchorWidth] = useState(0);

  const setFloating = useCallback((node: T | null) => {
    floatingRef.current = node;
    setFloatingNode(node);
  }, []);

  const update = useCallback(() => {
    const anchor = anchorRef.current;
    const floating = floatingNode;
    if (!anchor || !floating) return;

    const a = anchor.getBoundingClientRect();
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const anchorW = Math.round(a.width);
    setMeasuredAnchorWidth(anchorW);

    if (matchWidth) {
      const maxW = Math.max(160, vw - VIEWPORT_PADDING * 2);
      const targetW = Math.min(anchorW, maxW);
      floating.style.width = `${targetW}px`;
      floating.style.maxWidth = `${maxW}px`;
    }

    // Keep floating popup from overflowing viewport height on mobile
    floating.style.maxHeight = `min(calc(100vh - ${VIEWPORT_PADDING * 2}px), 24rem)`;

    const f = floating.getBoundingClientRect();

    let placement: Placement = preferred;
    const fits = (p: Placement) => {
      switch (p) {
        case 'bottom': return a.bottom + offset + f.height <= vh - VIEWPORT_PADDING;
        case 'top':    return a.top - offset - f.height >= VIEWPORT_PADDING;
        case 'right':  return a.right + offset + f.width <= vw - VIEWPORT_PADDING;
        case 'left':   return a.left - offset - f.width >= VIEWPORT_PADDING;
      }
    };
    if (!fits(placement)) {
      const opposite: Record<Placement, Placement> = {
        bottom: 'top', top: 'bottom', right: 'left', left: 'right',
      };
      if (fits(opposite[placement])) placement = opposite[placement];
    }

    let x = 0;
    let y = 0;

    if (placement === 'bottom' || placement === 'top') {
      y = placement === 'bottom' ? a.bottom + offset : a.top - offset - f.height;
      if (align === 'start') x = a.left;
      else if (align === 'end') x = a.right - f.width;
      else x = a.left + a.width / 2 - f.width / 2;
      x = clamp(x, VIEWPORT_PADDING, vw - f.width - VIEWPORT_PADDING);
      y = clamp(y, VIEWPORT_PADDING, vh - f.height - VIEWPORT_PADDING);
    } else {
      x = placement === 'right' ? a.right + offset : a.left - offset - f.width;
      if (align === 'start') y = a.top;
      else if (align === 'end') y = a.bottom - f.height;
      else y = a.top + a.height / 2 - f.height / 2;
      y = clamp(y, VIEWPORT_PADDING, vh - f.height - VIEWPORT_PADDING);
      x = clamp(x, VIEWPORT_PADDING, vw - f.width - VIEWPORT_PADDING);
    }

    setCoords((prev) =>
      prev.x === x && prev.y === y && prev.placement === placement && prev.anchorWidth === anchorW
        ? prev
        : { x, y, placement, anchorWidth: anchorW }
    );
    setReady(true);
  }, [anchorRef, floatingNode, preferred, align, offset, matchWidth]);

  useLayoutEffect(() => {
    if (!active) {
      setReady(false);
      return;
    }
    update();
  }, [active, update]);

  useEffect(() => {
    if (!active) return;
    const onScrollOrResize = () => update();
    window.addEventListener('scroll', onScrollOrResize, true);
    window.addEventListener('resize', onScrollOrResize);
    const observer = new ResizeObserver(update);
    if (floatingNode) observer.observe(floatingNode);
    if (anchorRef.current) observer.observe(anchorRef.current);
    return () => {
      window.removeEventListener('scroll', onScrollOrResize, true);
      window.removeEventListener('resize', onScrollOrResize);
      observer.disconnect();
    };
  }, [active, update, floatingNode, anchorRef]);

  return {
    setFloating,
    floatingRef,
    coords,
    placement: coords.placement,
    ready,
    update,
    anchorWidth: measuredAnchorWidth,
  };
}

function clamp(value: number, min: number, max: number) {
  if (max < min) return min;
  return Math.min(Math.max(value, min), max);
}

import { useEffect, type RefObject } from 'react';

const FOCUSABLE = [
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled]):not([type="hidden"])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
].join(',');

function getFocusable(container: HTMLElement): HTMLElement[] {
  return Array.from(container.querySelectorAll<HTMLElement>(FOCUSABLE)).filter(
    (el) => el.offsetWidth > 0 || el.offsetHeight > 0 || el === document.activeElement
  );
}

/**
 * Traps Tab focus inside `container` while `active`.
 * Restores focus to the previously focused element on teardown, which is what
 * makes a dialog feel correct when it closes.
 *
 * Takes the node rather than a ref on purpose. `<Portal>` renders `null` on its
 * first commit, so a ref handed to this hook is still empty when the effect
 * runs and the trap would silently never engage. Consumers should pass a node
 * held in state (`ref={setNode}`), which re-runs the effect once the panel
 * actually exists.
 *
 * A `RefObject` is still accepted for panels that mount synchronously.
 */
export interface FocusTrapOptions {
  /** Focus this element on open instead of the first focusable child. */
  initialFocus?: RefObject<HTMLElement> | null;
}

export function useFocusTrap(
  container: HTMLElement | null | RefObject<HTMLElement>,
  active: boolean,
  options: FocusTrapOptions = {}
) {
  const node =
    container && typeof container === 'object' && 'current' in container
      ? container.current
      : (container as HTMLElement | null);

  const { initialFocus } = options;

  useEffect(() => {
    if (!active || !node) return;

    const previouslyFocused = document.activeElement as HTMLElement | null;

    // Move focus in after paint so entry animations don't fight it.
    const raf = requestAnimationFrame(() => {
      const [first] = getFocusable(node);
      const target =
        initialFocus?.current ??
        node.querySelector<HTMLElement>('[data-autofocus]') ??
        first;
      target?.focus();
    });

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Tab') return;
      const items = getFocusable(node);
      if (items.length === 0) {
        event.preventDefault();
        return;
      }
      const first = items[0]!;
      const last = items[items.length - 1]!;
      const activeEl = document.activeElement;

      if (event.shiftKey && (activeEl === first || !node.contains(activeEl))) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && activeEl === last) {
        event.preventDefault();
        first.focus();
      }
    };

    document.addEventListener('keydown', onKeyDown, true);
    return () => {
      cancelAnimationFrame(raf);
      document.removeEventListener('keydown', onKeyDown, true);
      previouslyFocused?.focus?.();
    };
  }, [node, active, initialFocus]);
}

import { useCallback, useEffect, useState } from 'react';

/**
 * SSR-safe, reactive localStorage hook with cross-tab sync and JSON serialization.
 *
 * @param key - The localStorage storage key
 * @param initialValue - Fallback value if no stored value exists
 */
export function useLocalStorage<T>(
  key: string,
  initialValue: T
): [T, (value: T | ((val: T) => T)) => void, () => void] {
  // Read stored value or fall back to initialValue
  const readValue = useCallback((): T => {
    if (typeof window === 'undefined') {
      return initialValue;
    }

    try {
      const item = window.localStorage.getItem(key);
      return item ? (JSON.parse(item) as T) : initialValue;
    } catch (error) {
      console.warn(`[hesh-ui] Error reading localStorage key "${key}":`, error);
      return initialValue;
    }
  }, [key, initialValue]);

  const [storedValue, setStoredValue] = useState<T>(readValue);

  // Set value function
  const setValue = useCallback(
    (value: T | ((val: T) => T)) => {
      if (typeof window === 'undefined') {
        console.warn(`[hesh-ui] Tried setting localStorage key "${key}" during SSR`);
        return;
      }

      try {
        const newValue = value instanceof Function ? value(storedValue) : value;
        window.localStorage.setItem(key, JSON.stringify(newValue));
        setStoredValue(newValue);

        // Dispatch a custom storage event so other components in the same tab update
        window.dispatchEvent(
          new StorageEvent('storage', {
            key,
            newValue: JSON.stringify(newValue),
          })
        );
      } catch (error) {
        console.warn(`[hesh-ui] Error writing localStorage key "${key}":`, error);
      }
    },
    [key, storedValue]
  );

  // Remove value function
  const removeValue = useCallback(() => {
    if (typeof window === 'undefined') return;

    try {
      window.localStorage.removeItem(key);
      setStoredValue(initialValue);
      window.dispatchEvent(
        new StorageEvent('storage', {
          key,
          newValue: null,
        })
      );
    } catch (error) {
      console.warn(`[hesh-ui] Error removing localStorage key "${key}":`, error);
    }
  }, [key, initialValue]);

  // Sync across tabs & windows via 'storage' event
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === key) {
        setStoredValue(readValue());
      }
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, [key, readValue]);

  return [storedValue, setValue, removeValue];
}

import { useEffect, useState } from 'react';

/**
 * React hook that tracks whether a CSS media query matches.
 * Fully SSR-safe: returns false or serverFallback during server render.
 *
 * @param query - The media query string (e.g., '(max-width: 768px)' or '(prefers-color-scheme: dark)')
 * @param serverFallback - Initial value during SSR or before hydration (default: false)
 */
export function useMediaQuery(query: string, serverFallback = false): boolean {
  const [matches, setMatches] = useState<boolean>(() => {
    if (typeof window !== 'undefined' && 'matchMedia' in window) {
      return window.matchMedia(query).matches;
    }
    return serverFallback;
  });

  useEffect(() => {
    if (typeof window === 'undefined' || !('matchMedia' in window)) {
      return;
    }

    const mediaQueryList = window.matchMedia(query);
    const updateMatch = (event: MediaQueryListEvent | MediaQueryList) => {
      setMatches(event.matches);
    };

    setMatches(mediaQueryList.matches);

    if (typeof mediaQueryList.addEventListener === 'function') {
      mediaQueryList.addEventListener('change', updateMatch);
      return () => mediaQueryList.removeEventListener('change', updateMatch);
    } else {
      // Fallback for older Safari
      mediaQueryList.addListener(updateMatch);
      return () => mediaQueryList.removeListener(updateMatch);
    }
  }, [query]);

  return matches;
}

import { useCallback, useRef, useState, type KeyboardEvent } from 'react';

export interface UseRovingFocusOptions {
  orientation?: 'vertical' | 'horizontal' | 'both';
  loop?: boolean;
  onSelect?: (index: number) => void;
}

/**
 * Roving focus hook for lists, menus, toolbars, and selects.
 * Handles arrow key navigation, Home/End, Enter/Space, and 500ms typeahead search.
 */
export function useRovingFocus(
  itemsLength: number,
  options: UseRovingFocusOptions = {}
) {
  const { orientation = 'vertical', loop = true, onSelect } = options;
  const [activeIndex, setActiveIndex] = useState<number>(-1);
  const typeaheadBuffer = useRef('');
  const typeaheadTimer = useRef<number | undefined>(undefined);

  const move = useCallback(
    (step: number) => {
      setActiveIndex((current) => {
        if (itemsLength === 0) return -1;
        if (current === -1) return step > 0 ? 0 : itemsLength - 1;
        let next = current + step;
        if (loop) {
          next = (next + itemsLength) % itemsLength;
        } else {
          next = Math.max(0, Math.min(itemsLength - 1, next));
        }
        return next;
      });
    },
    [itemsLength, loop]
  );

  const handleKeyDown = useCallback(
    (e: KeyboardEvent, itemLabels?: string[]) => {
      const isVertical = orientation === 'vertical' || orientation === 'both';
      const isHorizontal = orientation === 'horizontal' || orientation === 'both';

      if ((isVertical && e.key === 'ArrowDown') || (isHorizontal && e.key === 'ArrowRight')) {
        e.preventDefault();
        move(1);
        return;
      }
      if ((isVertical && e.key === 'ArrowUp') || (isHorizontal && e.key === 'ArrowLeft')) {
        e.preventDefault();
        move(-1);
        return;
      }
      if (e.key === 'Home') {
        e.preventDefault();
        setActiveIndex(0);
        return;
      }
      if (e.key === 'End') {
        e.preventDefault();
        setActiveIndex(itemsLength - 1);
        return;
      }
      if ((e.key === 'Enter' || e.key === ' ') && activeIndex >= 0) {
        e.preventDefault();
        onSelect?.(activeIndex);
        return;
      }

      // Typeahead single-character search
      if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey && itemLabels) {
        if (typeaheadTimer.current) window.clearTimeout(typeaheadTimer.current);
        typeaheadBuffer.current += e.key.toLowerCase();
        typeaheadTimer.current = window.setTimeout(() => {
          typeaheadBuffer.current = '';
        }, 500);

        const search = typeaheadBuffer.current;
        const start = (activeIndex + 1) % itemsLength;
        for (let i = 0; i < itemsLength; i++) {
          const idx = (start + i) % itemsLength;
          const label = itemLabels[idx]?.toLowerCase() || '';
          if (label.startsWith(search)) {
            setActiveIndex(idx);
            break;
          }
        }
      }
    },
    [orientation, move, itemsLength, activeIndex, onSelect]
  );

  return {
    activeIndex,
    setActiveIndex,
    handleKeyDown,
    move,
  };
}

import { useEffect } from 'react';

let lockCount = 0;
let originalOverflow = '';
let originalPaddingRight = '';

/**
 * Prevents background scroll while an overlay is open.
 * Supports stacked overlays (nested dialogs, drawers) and compensates for
 * scrollbar width to prevent layout shifts.
 */
export function useScrollLock(active: boolean) {
  useEffect(() => {
    if (!active || typeof document === 'undefined') return;

    if (lockCount === 0) {
      originalOverflow = document.body.style.overflow;
      originalPaddingRight = document.body.style.paddingRight;

      const scrollbarWidth = window.innerWidth - document.documentElement.clientWidth;
      if (scrollbarWidth > 0) {
        document.body.style.paddingRight = `${scrollbarWidth}px`;
      }
      document.body.style.overflow = 'hidden';
    }

    lockCount += 1;

    return () => {
      lockCount = Math.max(0, lockCount - 1);
      if (lockCount === 0) {
        document.body.style.overflow = originalOverflow;
        document.body.style.paddingRight = originalPaddingRight;
      }
    };
  }, [active]);
}

