  {
    variant = 'primary',
    size = 'md',
    shape = 'rounded',
    glow = false,
    loading = false,
    loadingText,
    leftIcon,
    rightIcon,
    fullWidth = false,
    iconOnly = false,
    disabled,
    className,
    children,
    type = 'button',
    asChild = false,
    ...props
  },
  ref
) {
  const isInert = disabled || loading;
  const Comp = asChild ? Slot : 'button';

  const buttonClass = cn(
    'pui-btn',
    `pui-btn--${variant}`,
    `pui-btn--${size}`,
    shape && shape !== 'rounded' && `pui-btn--${shape}`,
