        ref={ref}
        aria-busy={loading || undefined}
        aria-disabled={isInert || undefined}
        className={buttonClass}
        {...props}
      >
        {children}
      </Comp>
    );
  }

  return (
    <button
      ref={ref}
      type={type}
      disabled={disabled || undefined}
      aria-busy={loading || undefined}
      aria-disabled={isInert || undefined}
      className={buttonClass}
      {...props}
    >
      {loading ? (
        <span className="pui-btn__spinner" />
      ) : (
        leftIcon && <span className="pui-btn__icon">{leftIcon}</span>
