import {
  useState,
  useEffect,
  useRef,
  useCallback,
  forwardRef,
  type ReactNode,
  type HTMLAttributes,
} from 'react';
import { cn } from '../utils/cn';

export interface CarouselProps extends HTMLAttributes<HTMLDivElement> {
  /** Slides or content elements to display */
  children?: ReactNode;
  /** Number of slides visible simultaneously. @default 1 */
  itemsPerView?: number;
  /** Gap between slides in pixels when itemsPerView > 1. @default 16 */
  gap?: number;
  /** Automatically transition to next slide */
  autoPlay?: boolean;
  /** Autoplay interval in milliseconds (default: 4000) */
  interval?: number;
  /** Whether navigation wraps around at ends (default: true for single slide, false for multi-item) */
  loop?: boolean;
  /** Show previous/next arrow buttons (default: true) */
  showArrows?: boolean;
  /** Show pagination dot indicators (default: true) */
  showDots?: boolean;
  /** Indicator pagination style: modern expanding bars, refined dots, or numeric badge. @default 'bars' */
  indicatorVariant?: 'bars' | 'dots' | 'numbers';
  /** Arrow button visual variant: floating frosted glass, solid, or outline. @default 'floating' */
  arrowVariant?: 'floating' | 'solid' | 'outline';
  /** Position of pagination indicators: inside slide viewport or outside below track. @default 'inside' */
  dotsPosition?: 'inside' | 'outside';
  /** Callback fired when active slide index changes */
  onSlideChange?: (index: number) => void;
  /** Accessible label describing the carousel */
  'aria-label'?: string;
}

export const Carousel = forwardRef<HTMLDivElement, CarouselProps>(function Carousel(
  {
    children,
    itemsPerView = 1,
    gap = 16,
    autoPlay = false,
    interval = 4000,
    loop,
    showArrows = true,
    showDots = true,
    indicatorVariant = 'bars',
    arrowVariant = 'floating',
    dotsPosition = 'inside',
    onSlideChange,
    className,
    'aria-label': ariaLabel = 'Image and content carousel',
    ...props
  },
  ref
) {
  const slides = Array.isArray(children) ? children.filter(Boolean) : children ? [children] : [];
  const slideCount = slides.length;
  const clampedItemsPerView = Math.max(1, Math.min(itemsPerView, slideCount || 1));
  const maxIndex = Math.max(0, slideCount - clampedItemsPerView);
  const effectiveLoop = loop !== undefined ? loop : clampedItemsPerView <= 1;

  const [current, setCurrent] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);

  const isMultiItem = clampedItemsPerView > 1;
  const totalStops = isMultiItem ? maxIndex + 1 : slideCount;

  useEffect(() => {
    if (current > maxIndex) {
      setCurrent(maxIndex);
    }
  }, [maxIndex, current]);

  const goTo = useCallback(
    (index: number) => {
      let target = index;
      if (target < 0) {
        target = effectiveLoop ? maxIndex : 0;
      } else if (target > maxIndex) {
        target = effectiveLoop ? 0 : maxIndex;
      }
      setCurrent(target);
      onSlideChange?.(target);
    },
    [effectiveLoop, maxIndex, onSlideChange]
  );

  const prev = useCallback(() => goTo(current - 1), [goTo, current]);
  const next = useCallback(() => goTo(current + 1), [goTo, current]);

  useEffect(() => {
    if (!autoPlay || isPaused || slideCount <= clampedItemsPerView) return;
    const timer = window.setInterval(next, interval);
    return () => window.clearInterval(timer);
  }, [autoPlay, isPaused, slideCount, clampedItemsPerView, interval, next]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowLeft') {
      e.preventDefault();
      prev();
    } else if (e.key === 'ArrowRight') {
      e.preventDefault();
      next();
    }
  };

  const handleTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.touches[0]?.clientX ?? null;
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.touches[0]?.clientX ?? null;
  };

  const handleTouchEnd = () => {
    if (touchStartX.current === null || touchEndX.current === null) return;
    const diff = touchStartX.current - touchEndX.current;
    const threshold = 40;
    if (diff > threshold) {
      next();
    } else if (diff < -threshold) {
      prev();
    }
    touchStartX.current = null;
    touchEndX.current = null;
  };

  if (slideCount === 0) return null;

  const trackTransform = isMultiItem
    ? `translateX(calc(-${current} * ((100% + ${gap}px) / ${clampedItemsPerView})))`
    : `translateX(-${current * 100}%)`;

  const trackStyle: React.CSSProperties = {
    transform: trackTransform,
    ...(isMultiItem ? { gap: `${gap}px` } : {}),
  };

  const slideStyle: React.CSSProperties | undefined = isMultiItem
    ? {
        flex: `0 0 calc((100% - ${(clampedItemsPerView - 1) * gap}px) / ${clampedItemsPerView})`,
        minWidth: `calc((100% - ${(clampedItemsPerView - 1) * gap}px) / ${clampedItemsPerView})`,
        width: `calc((100% - ${(clampedItemsPerView - 1) * gap}px) / ${clampedItemsPerView})`,
        boxSizing: 'border-box',
      }
    : undefined;

  return (
    <div
      ref={ref}
      className={cn(
        'pui-carousel',
        dotsPosition === 'outside' && 'pui-carousel--dots-outside',
        clampedItemsPerView > 1 && 'pui-carousel--multi-item',
        className
      )}
      role="region"
      aria-roledescription="carousel"
      aria-label={ariaLabel}
      onKeyDown={handleKeyDown}
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
      onFocus={() => setIsPaused(true)}
      onBlur={() => setIsPaused(false)}
      tabIndex={0}
      {...props}
    >
      <div
        className="pui-carousel__viewport"
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
      >
        <div
          className="pui-carousel__track"
          style={trackStyle}
        >
          {slides.map((slide, idx) => {
            const isVisible = isMultiItem
              ? idx >= current && idx < current + clampedItemsPerView
              : idx === current;
            return (
              <div
                key={idx}
                className={cn('pui-carousel__slide', isVisible && 'pui-carousel__slide--active')}
                style={slideStyle}
                role="group"
                aria-roledescription="slide"
                aria-label={`Slide ${idx + 1} of ${slideCount}`}
                aria-hidden={!isVisible}
              >
                {slide}
              </div>
            );
          })}
        </div>
      </div>

      {showArrows && slideCount > clampedItemsPerView && (
        <>
          <button
            type="button"
            className={cn(
              'pui-carousel__arrow pui-carousel__arrow--prev',
              `pui-carousel__arrow--${arrowVariant}`
            )}
            aria-label="Previous slide"
            onClick={prev}
            disabled={!effectiveLoop && current === 0}
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
              <path d="M15 19l-7-7 7-7" />
            </svg>
          </button>
          <button
            type="button"
            className={cn(
              'pui-carousel__arrow pui-carousel__arrow--next',
              `pui-carousel__arrow--${arrowVariant}`
            )}
            aria-label="Next slide"
            onClick={next}
            disabled={!effectiveLoop && current >= maxIndex}
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
              <path d="M9 5l7 7-7 7" />
            </svg>
          </button>
        </>
      )}

      {showDots && totalStops > 1 && (
        indicatorVariant === 'numbers' ? (
          <div className="pui-carousel__counter" aria-live="polite">
            <span className="pui-carousel__counter-current">{String(current + 1).padStart(2, '0')}</span>
            <span className="pui-carousel__counter-divider">/</span>
            <span className="pui-carousel__counter-total">{String(totalStops).padStart(2, '0')}</span>
          </div>
        ) : (
          <div
            className={cn(
              'pui-carousel__dots',
              indicatorVariant === 'bars' ? 'pui-carousel__dots--bars' : 'pui-carousel__dots--dots'
            )}
            role="tablist"
            aria-label="Slides"
          >
            {Array.from({ length: totalStops }).map((_, idx) => (
              <button
                key={idx}
                type="button"
                role="tab"
                aria-selected={idx === current}
                aria-label={`Go to slide position ${idx + 1}`}
                className={cn(
                  'pui-carousel__dot',
                  indicatorVariant === 'bars' && 'pui-carousel__dot--bar',
                  idx === current && 'pui-carousel__dot--active'
                )}
                onClick={() => goTo(idx)}
              />
            ))}
          </div>
        )
      )}
    </div>
  );
});

import { useId, useMemo, useState, type ReactNode } from 'react';
import { cn } from '../utils/cn';

/**
 * Dependency-free SVG charts.
 *
 * Why not recharts / visx: those are 90–400 kB and ship their own theming.
 * These read colour straight from the token layer, so charts re-theme with
 * everything else and cost almost nothing. They cover the shapes that make up
 * the overwhelming majority of product dashboards.
 *
 * Every chart is declarative SVG with a text alternative — screen readers get
 * the summary via `role="img"` + `aria-label`, and the interactive tooltip is
 * a mouse affordance only, never the sole way to read a value.
 */

export interface SeriesPoint {
  label: string;
  value: number;
}

const PADDING = { top: 24, right: 18, bottom: 34, left: 52 };

function useGradientId(prefix: string) {
  const id = useId().replace(/[:]/g, '');
  return `${prefix}-${id}`;
}

function scaleY(value: number, min: number, max: number, innerH: number, top: number) {
  const span = max - min || 1;
  return top + innerH - ((value - min) / span) * innerH;
}

function niceBounds(values: number[], padRatio = 0.08) {
  if (!values.length) return { min: 0, max: 100 };
  const min = Math.min(...values);
  const max = Math.max(...values);
  const pad = (max - min || Math.abs(max) || 1) * padRatio;
  return { min: min - pad, max: max + pad };
}

/** Computes smooth cubic Bézier spline for points */
function computeSmoothPath(pts: { x: number; y: number }[]): string {
  if (pts.length <= 1) return pts.map((p) => `${p.x},${p.y}`).join(' ');
  let d = `M ${pts[0]!.x.toFixed(1)},${pts[0]!.y.toFixed(1)}`;
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[i === 0 ? 0 : i - 1]!;
    const p1 = pts[i]!;
    const p2 = pts[i + 1]!;
    const p3 = pts[i + 2] ?? p2;

    const cp1x = p1.x + (p2.x - p0.x) / 6;
    const cp1y = p1.y + (p2.y - p0.y) / 6;
    const cp2x = p2.x - (p3.x - p1.x) / 6;
    const cp2y = p2.y - (p3.y - p1.y) / 6;

    d += ` C ${cp1x.toFixed(1)},${cp1y.toFixed(1)} ${cp2x.toFixed(1)},${cp2y.toFixed(1)} ${p2.x.toFixed(1)},${p2.y.toFixed(1)}`;
  }
  return d;
}

/* ------------------------------------------------------------------ Area */

export interface AreaChartProps {
  data: SeriesPoint[];
  height?: number;
  color?: string;
  /** Formats tooltip and axis values. */
  format?: (value: number) => string;
  showGrid?: boolean;
  /** Smooth Bézier spline interpolation instead of straight lines @default true */
  smooth?: boolean;
  className?: string;
  label?: string;
}

export function AreaChart({
  data,
  height = 260,
  color = 'var(--pui-chart-1)',
  format = (v) => v.toLocaleString(),
  showGrid = true,
  smooth = true,
  className,
  label,
}: AreaChartProps) {
  const [hover, setHover] = useState<number | null>(null);
  const gradientId = useGradientId('area');
  const width = 720;

  if (!data || data.length === 0) {
    return (
      <div className={cn('pui-chart pui-chart--empty', className)} style={{ minHeight: height, display: 'grid', placeItems: 'center' }}>
        <span style={{ fontSize: '0.875rem', color: 'var(--pui-fg-subtle)' }}>No data available</span>
      </div>
    );
  }

  const { min, max } = useMemo(() => niceBounds(data.map((d) => d.value)), [data]);
  const padLeft = showGrid ? PADDING.left : PADDING.right;
  const innerW = width - padLeft - PADDING.right;
  const innerH = height - PADDING.top - PADDING.bottom;

  const x = (i: number) => padLeft + (i / Math.max(1, data.length - 1)) * innerW;
  const y = (v: number) => scaleY(v, min, max, innerH, PADDING.top);

  const pts = data.map((d, i) => ({ x: x(i), y: y(d.value) }));
  const bottomY = PADDING.top + innerH;

  const linePath = smooth
    ? computeSmoothPath(pts)
    : `M ${pts.map((p) => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' L ')}`;

  const areaPath = smooth
    ? `${linePath} L ${pts[pts.length - 1]!.x.toFixed(1)},${bottomY.toFixed(1)} L ${pts[0]!.x.toFixed(1)},${bottomY.toFixed(1)} Z`
    : `M ${padLeft},${bottomY} ${pts.map((p) => `L ${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ')} L ${padLeft + innerW},${bottomY} Z`;

  const ticks = [0, 0.25, 0.5, 0.75, 1].map((r) => ({
    ratio: r,
    value: min + (max - min) * (1 - r),
  }));

  const summary = label ?? `${data.length} data points ranging from ${format(Math.min(...data.map((d) => d.value)))} to ${format(Math.max(...data.map((d) => d.value)))}`;

  return (
    <div className={cn('pui-chart', className)}>
      <svg
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-label={summary}
        onMouseLeave={() => setHover(null)}
      >
        <defs>
          <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={color} stopOpacity="0.42" />
            <stop offset="65%" stopColor={color} stopOpacity="0.10" />
            <stop offset="100%" stopColor={color} stopOpacity="0.00" />
          </linearGradient>
        </defs>

        {showGrid &&
          ticks.map((tick) => {
            const gy = PADDING.top + innerH * tick.ratio;
            return (
              <g key={tick.ratio}>
                <line
                  className="pui-chart__grid"
                  x1={padLeft}
                  x2={width - PADDING.right}
                  y1={gy}
                  y2={gy}
                  strokeDasharray={tick.ratio === 1 ? undefined : '3 4'}
                  opacity={0.65}
                />
                <text className="pui-chart__axis-label" x={padLeft - 10} y={gy + 4} textAnchor="end">
                  {format(Math.round(tick.value))}
                </text>
              </g>
            );
          })}

        <path d={areaPath} fill={`url(#${gradientId})`} />
        <path d={linePath} fill="none" stroke={color} strokeWidth="2.75" strokeLinecap="round" strokeLinejoin="round" />

        {data.map((d, i) => (
          <g key={d.label}>
            <rect
              x={x(i) - innerW / data.length / 2}
              y={PADDING.top}
              width={innerW / data.length}
              height={innerH}
              fill="transparent"
              onMouseEnter={() => setHover(i)}
            />
            <circle
              cx={x(i)}
              cy={y(d.value)}
              r={hover === i ? 6 : 3.5}
              fill="var(--pui-surface, #fff)"
              stroke={color}
              strokeWidth={hover === i ? 3 : 2}
              style={{ transition: 'all 120ms ease' }}
            />
            {hover === i && (
              <circle
                cx={x(i)}
                cy={y(d.value)}
                r={10}
                fill="none"
                stroke={color}
                strokeWidth={1.5}
                opacity={0.4}
              />
            )}
            <text className="pui-chart__axis-label" x={x(i)} y={height - 10} textAnchor="middle">
              {d.label}
            </text>
          </g>
        ))}

        {hover !== null && (
          <line
            x1={x(hover)}
            x2={x(hover)}
            y1={PADDING.top}
            y2={PADDING.top + innerH}
            stroke={color}
            strokeWidth="1.25"
            strokeDasharray="4 4"
            opacity="0.6"
          />
        )}
      </svg>

      {hover !== null && (
        <div
          className="pui-chart__tip"
          style={{ left: `${(x(hover) / width) * 100}%`, top: `${(y(data[hover]!.value) / height) * 100}%` }}
        >
          <div className="pui-chart__tip-title">{data[hover]!.label}</div>
          <div className="pui-chart__tip-value">{format(data[hover]!.value)}</div>
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ Bars */

export interface BarChartProps {
  data: SeriesPoint[];
  height?: number;
  color?: string;
  format?: (value: number) => string;
  /** Whether to show subtle background track pillars @default true */
  showTracks?: boolean;
  showGrid?: boolean;
  className?: string;
  label?: string;
}

export function BarChart({
  data,
  height = 260,
  color = 'var(--pui-chart-2)',
  format = (v) => v.toLocaleString(),
  showTracks = true,
  showGrid = true,
  className,
  label,
}: BarChartProps) {
  const [hover, setHover] = useState<number | null>(null);
  const gradientId = useGradientId('bar');
  const width = 720;

  if (!data || data.length === 0) {
    return (
      <div className={cn('pui-chart pui-chart--empty', className)} style={{ minHeight: height, display: 'grid', placeItems: 'center' }}>
        <span style={{ fontSize: '0.875rem', color: 'var(--pui-fg-subtle)' }}>No data available</span>
      </div>
    );
  }

  const { min, max } = useMemo(() => niceBounds([0, ...data.map((d) => d.value)], 0.05), [data]);
  const innerW = width - PADDING.left - PADDING.right;
  const innerH = height - PADDING.top - PADDING.bottom;

  const slot = innerW / data.length;
  const barW = Math.min(slot * 0.58, 44);
  const y0 = scaleY(Math.min(0, min), min, max, innerH, PADDING.top);

  const ticks = [0, 0.25, 0.5, 0.75, 1].map((r) => ({
    ratio: r,
    value: min + (max - min) * (1 - r),
  }));

  return (
    <div className={cn('pui-chart', className)}>
      <svg
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-label={label ?? `Bar chart of ${data.length} categories`}
        onMouseLeave={() => setHover(null)}
      >
        <defs>
          <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={color} stopOpacity="1" />
            <stop offset="100%" stopColor={color} stopOpacity="0.72" />
          </linearGradient>
        </defs>

        {showGrid &&
          ticks.map((tick) => {
            const gy = PADDING.top + innerH * tick.ratio;
            return (
              <g key={tick.ratio}>
                <line
                  className="pui-chart__grid"
                  x1={PADDING.left}
                  x2={width - PADDING.right}
                  y1={gy}
                  y2={gy}
                  strokeDasharray={tick.ratio === 1 ? undefined : '3 4'}
                  opacity={0.65}
                />
                <text className="pui-chart__axis-label" x={PADDING.left - 10} y={gy + 4} textAnchor="end">
                  {format(Math.round(tick.value))}
                </text>
              </g>
            );
          })}

        {data.map((d, i) => {
          const cx = PADDING.left + slot * i + slot / 2;
          const top = scaleY(d.value, min, max, innerH, PADDING.top);
          const h = Math.max(3, Math.abs(y0 - top));
          const isHovered = hover === i;
          const isAnyHovered = hover !== null;

          return (
            <g key={d.label} onMouseEnter={() => setHover(i)}>
              {/* Background Pillar Track */}
              {showTracks && (
                <rect
                  x={cx - barW / 2}
                  y={PADDING.top}
                  width={barW}
                  height={innerH}
                  rx={Math.min(6, barW / 2)}
                  fill="var(--pui-fg-muted)"
                  opacity={0.07}
                />
              )}

              {/* Data Bar */}
              <rect
                x={cx - barW / 2}
                y={Math.min(top, y0)}
                width={barW}
                height={h}
                rx={Math.min(6, barW / 2)}
                fill={`url(#${gradientId})`}
                opacity={!isAnyHovered || isHovered ? 1 : 0.42}
                style={{
                  transition: 'opacity 140ms ease, transform 140ms ease',
                  filter: isHovered ? `drop-shadow(0 4px 10px ${color}55)` : undefined,
                }}
              />

              {/* Top Accent Cap on Hover */}
              {isHovered && (
                <rect
                  x={cx - barW / 2}
                  y={Math.min(top, y0)}
                  width={barW}
                  height={3}
                  rx={1.5}
                  fill="#fff"
                  opacity={0.9}
                />
              )}

              <text
                className="pui-chart__axis-label"
                x={cx}
                y={height - 10}
                textAnchor="middle"
                style={{ fontWeight: isHovered ? 600 : 400 }}
              >
                {d.label}
              </text>

              <rect
                x={PADDING.left + slot * i}
                y={PADDING.top}
                width={slot}
                height={innerH}
                fill="transparent"
              />
            </g>
          );
        })}
      </svg>

      {hover !== null && (
        <div
          className="pui-chart__tip"
          style={{
            left: `${((PADDING.left + slot * hover + slot / 2) / width) * 100}%`,
            top: `${(scaleY(data[hover]!.value, min, max, innerH, PADDING.top) / height) * 100}%`,
          }}
        >
          <div className="pui-chart__tip-title">{data[hover]!.label}</div>
          <div className="pui-chart__tip-value">{format(data[hover]!.value)}</div>
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ Donut */

export interface DonutSlice {
  label: string;
  value: number;
  color?: string;
}

export interface DonutChartProps {
  data: DonutSlice[];
  size?: number;
  thickness?: number;
  centerLabel?: ReactNode;
  centerValue?: ReactNode;
  format?: (value: number) => string;
  className?: string;
  label?: string;
}

export function DonutChart({
  data,
  size = 220,
  thickness = 26,
  centerLabel,
  centerValue,
  format = (v) => v.toLocaleString(),
  className,
  label,
}: DonutChartProps) {
  const [hover, setHover] = useState<number | null>(null);

  if (!data || data.length === 0) {
    return (
      <div className={cn('pui-donut pui-donut--empty', className)} style={{ width: size, height: size, display: 'grid', placeItems: 'center' }}>
        <span style={{ fontSize: '0.75rem', color: 'var(--pui-fg-subtle)' }}>No data</span>
      </div>
    );
  }

  const total = data.reduce((sum, slice) => sum + slice.value, 0) || 1;
  const radius = (size - thickness) / 2;
  const circumference = 2 * Math.PI * radius;

  let offset = 0;
  const segments = data.map((slice, index) => {
    const fraction = slice.value / total;
    const length = fraction * circumference;
    const segment = {
      ...slice,
      index,
      length,
      offset,
      color: slice.color ?? `var(--pui-chart-${(index % 8) + 1})`,
    };
    offset += length;
    return segment;
  });

  return (
    <div className={cn('pui-donut', className)} role="img" aria-label={label ?? `Donut chart: ${data.map((d) => `${d.label} ${Math.round((d.value / total) * 100)}%`).join(', ')}`}>
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
        <g transform={`rotate(-90 ${size / 2} ${size / 2})`}>
          <circle cx={size / 2} cy={size / 2} r={radius} fill="none" stroke="var(--pui-bg-muted, rgba(128,128,128,0.12))" strokeWidth={thickness} />
          {segments.map((segment) => {
            const isHovered = hover === segment.index;
            return (
              <circle
                key={segment.label}
                className="pui-donut__seg"
                cx={size / 2}
                cy={size / 2}
                r={radius}
                fill="none"
                stroke={segment.color}
                strokeWidth={isHovered ? thickness + 4 : thickness}
                strokeDasharray={`${Math.max(1, segment.length - 2)} ${circumference - Math.max(1, segment.length - 2)}`}
                strokeDashoffset={-segment.offset}
                strokeLinecap="round"
                onMouseEnter={() => setHover(segment.index)}
                onMouseLeave={() => setHover(null)}
                style={{
                  transition: 'stroke-width 160ms cubic-bezier(0.16, 1, 0.3, 1), opacity 160ms ease',
                  opacity: hover === null || isHovered ? 1 : 0.6,
                }}
              />
            );
          })}
        </g>
      </svg>
      <div className="pui-donut__center">
        <span className="pui-donut__value">
          {hover !== null ? format(data[hover]!.value) : centerValue}
        </span>
        <span className="pui-donut__label">
          {hover !== null ? data[hover]!.label : centerLabel}
        </span>
      </div>
    </div>
  );
}

export function ChartLegend({ items }: { items: DonutSlice[] }) {
  return (
    <div className="pui-chart__legend">
      {items.map((item, index) => (
        <span key={item.label} className="pui-chart__legend-item">
          <span className="pui-chart__swatch" style={{ background: item.color ?? `var(--pui-chart-${(index % 8) + 1})` }} />
          {item.label}
        </span>
      ))}
    </div>
  );
}

/* ------------------------------------------------------------------ Sparkline */

export interface SparklineProps {
  data: number[];
  width?: number;
  height?: number;
  color?: string;
  /** Fill the area beneath the line. */
  filled?: boolean;
  className?: string;
}

export function Sparkline({
  data,
  width = 120,
  height = 36,
  color = 'var(--pui-primary)',
  filled = true,
  className,
}: SparklineProps) {
  if (!data || data.length === 0) {
    return <span className={cn('pui-sparkline--empty', className)} style={{ display: 'inline-block', width, height }} />;
  }

  const gradientId = useGradientId('spark');
  const min = Math.min(...data);
  const max = Math.max(...data);
  const span = max - min || 1;

  const points = data.map((value, index) => {
    const px = (index / Math.max(1, data.length - 1)) * width;
    const py = height - ((value - min) / span) * (height - 4) - 2;
    return `${px.toFixed(1)},${py.toFixed(1)}`;
  });

  return (
    <svg
      className={className}
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      fill="none"
      aria-hidden="true"
      focusable="false"
    >
      {filled && (
        <>
          <defs>
            <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={color} stopOpacity="0.28" />
              <stop offset="100%" stopColor={color} stopOpacity="0" />
            </linearGradient>
          </defs>
          <polygon points={`0,${height} ${points.join(' ')} ${width},${height}`} fill={`url(#${gradientId})`} />
        </>
      )}
      <polyline points={points.join(' ')} stroke={color} strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

import {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useId,
  type ButtonHTMLAttributes,
  type InputHTMLAttributes,
  type ReactNode,
} from 'react';
import { cn } from '../utils/cn';
import { useControllableState } from '../hooks/useControllableState';
import { CheckIcon, MinusIcon } from './icons';

/* ------------------------------------------------------------------ Checkbox */

export interface CheckboxProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'size' | 'children'> {
  label?: ReactNode;
  description?: ReactNode;
  indeterminate?: boolean;
  size?: 'sm' | 'md' | 'lg';
}

export const Checkbox = forwardRef<HTMLInputElement, CheckboxProps>(function Checkbox(
  { label, description, indeterminate = false, size = 'md', disabled, className, id: providedId, ...props },
  forwardedRef
) {
  const generated = useId();
  const id = providedId ?? generated;
  const descriptionId = description ? `${id}-description` : undefined;

  // `indeterminate` is a DOM property with no HTML attribute, so it has to be
  // assigned imperatively whenever the node or the flag changes.
  const setRef = useCallback(
    (node: HTMLInputElement | null) => {
      if (node) node.indeterminate = indeterminate;
      if (typeof forwardedRef === 'function') forwardedRef(node);
      else if (forwardedRef) forwardedRef.current = node;
    },
    [forwardedRef, indeterminate]
  );

  return (
    <label
      htmlFor={id}
      className={cn(
        'pui-choice',
        `pui-choice--${size}`,
        disabled && 'pui-choice--disabled',
        className
      )}
    >
      <input
        ref={setRef}
        id={id}
        type="checkbox"
        disabled={disabled}
        aria-describedby={descriptionId}
        // Mixed state must be announced, not just drawn.
        aria-checked={indeterminate ? 'mixed' : undefined}
        {...props}
      />
      <span className="pui-choice__box pui-choice__box--checkbox">
        {indeterminate ? <MinusIcon /> : <CheckIcon />}
      </span>
      {(label || description) && (
        <span className="pui-choice__text">
          {label}
          {description && (
            <span id={descriptionId} className="pui-choice__desc">
              {description}
            </span>
          )}
        </span>
      )}
    </label>
  );
});

/* ------------------------------------------------------------------ Radio */

export interface RadioGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  name?: string;
  children: ReactNode;
  className?: string;
  'aria-label'?: string;
}

/** Owning group — one tab stop for the whole set, arrow keys to move. */
export function RadioGroup({
  value,
  defaultValue,
  onValueChange,
  name,
  children,
  className,
  ...props
}: RadioGroupProps) {
  const [selected, setSelected] = useControllableState<string>({
    value,
    defaultValue: defaultValue ?? '',
    onChange: onValueChange,
  });
  const autoName = useId();
  const groupName = name ?? autoName;

  return (
    <div
      role="radiogroup"
      className={cn('pui-field', className)}
      data-value={selected}
      {...props}
    >
      <RadioGroupContext.Provider value={{ name: groupName, selected, setSelected }}>
        {children}
      </RadioGroupContext.Provider>
    </div>
  );
}

interface RadioGroupContextValue {
  name: string;
  selected: string;
  setSelected: (value: string) => void;
}

const RadioGroupContext = createContext<RadioGroupContextValue | null>(null);

export interface RadioProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'name' | 'value' | 'size'> {
  value: string;
  label?: ReactNode;
  description?: ReactNode;
  size?: 'sm' | 'md' | 'lg';
}

export const Radio = forwardRef<HTMLInputElement, RadioProps>(function Radio(
  {
    value,
    label,
    description,
    size = 'md',
    disabled,
    checked: providedChecked,
    onChange,
    className,
    id: providedId,
    ...props
  },
  ref
) {
  const context = useContext(RadioGroupContext);
  const generated = useId();
  const id = providedId ?? generated;
  const descriptionId = description ? `${id}-description` : undefined;

  const checked = context ? context.selected === value : Boolean(providedChecked);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (context) {
      context.setSelected(value);
    }
    onChange?.(e);
  };

  return (
    <label
      htmlFor={id}
      className={cn(
        'pui-choice',
        `pui-choice--${size}`,
        disabled && 'pui-choice--disabled',
        className
