    >
      <input
        ref={ref}
        id={id}
        type="radio"
        value={value}
        checked={checked}
        disabled={disabled}
        aria-describedby={descriptionId}
        onChange={handleChange}
        {...props}
      />
      <span className="pui-choice__box pui-choice__box--radio">
        <span
          style={{
            width: '0.4375rem',
            height: '0.4375rem',
            borderRadius: '9999px',
            background: 'currentColor',
            color: 'var(--pui-on-primary)',
          }}
        />
      </span>
      {(label || description) && (
        <span className="pui-choice__text">
          {label}
          {description && (
            <span id={descriptionId} className="pui-choice__desc">
              {description}
            </span>
          )}
        </span>
      )}
    </label>
  );
});

/* ------------------------------------------------------------------ Switch */

export interface SwitchProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'onChange' | 'value' | 'type'> {
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  label?: ReactNode;
  description?: ReactNode;
  size?: 'sm' | 'md' | 'lg';
}

/**
 * `role="switch"` on a `<button>` rather than a hidden checkbox: full styling
 * control with correct semantics, and Space/Enter both toggle natively.
 */
export const Switch = forwardRef<HTMLButtonElement, SwitchProps>(function Switch(
  {
    checked,
    defaultChecked = false,
    onCheckedChange,
    label,
    description,
    size = 'md',
    disabled,
    className,
    id: providedId,
    ...props
  },
  ref
) {
  const [isChecked, setChecked] = useControllableState<boolean>({
    value: checked,
    defaultValue: defaultChecked,
    onChange: onCheckedChange,
  });

  const generated = useId();
  const id = providedId ?? generated;
  const descriptionId = description ? `${id}-description` : undefined;

  const control = (
    <button
      ref={ref}
      id={id}
      type="button"
      role="switch"
      aria-checked={isChecked}
      aria-describedby={descriptionId}
      aria-label={typeof label === 'string' ? label : undefined}
      disabled={disabled}
      data-state={isChecked ? 'checked' : 'unchecked'}
      data-size={size}
      className={cn('pui-switch', className)}
      onClick={() => setChecked(!isChecked)}
      {...props}
    >
      <span className="pui-switch__thumb" />
    </button>
  );

  if (!label && !description) return control;

  return (
    <span className={cn('pui-choice', `pui-choice--${size}`, disabled && 'pui-choice--disabled')}>
      {control}
      {(label || description) && (
        <span className="pui-choice__text">
          {/* eslint-disable-next-line jsx-a11y/label-has-associated-control */}
          <label
            htmlFor={id}
            onClick={(event) => {
              event.preventDefault();
              if (!disabled) setChecked(!isChecked);
            }}
            style={{ cursor: disabled ? 'not-allowed' : 'pointer' }}
          >
            {label}
          </label>
          {description && (
            <span id={descriptionId} className="pui-choice__desc">
              {description}
            </span>
          )}
        </span>
      )}
    </span>
  );
});

/* ------------------------------------------------------------------ ChoiceCard */

export interface ChoiceCardProps extends React.HTMLAttributes<HTMLDivElement> {
  checked?: boolean;
  disabled?: boolean;
  children: ReactNode;
}

/**
 * Selectable card container for Checkbox and Radio items with active ring highlight.
 */
export const ChoiceCard = forwardRef<HTMLDivElement, ChoiceCardProps>(function ChoiceCard(
  { checked, disabled, className, children, ...props },
  ref
) {
  return (
    <div
      ref={ref}
      data-checked={checked || undefined}
      className={cn('pui-choice-card', disabled && 'pui-choice-card--disabled', className)}
      {...props}
    >
      {children}
    </div>
  );
});

'use client';

import { forwardRef, useState, type HTMLAttributes, type ReactNode } from 'react';
import { cn } from '../utils/cn';
import { CopyButton } from './CopyButton';

export interface CodeSnippetProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  /** Raw code string. */
  code: string;
  /** Language identifier (e.g. 'tsx', 'bash', 'css'). */
  language?: string;
  /** Optional title shown in the header bar. */
  title?: ReactNode;
  /** Whether to show line numbers. @default false */
  showLineNumbers?: boolean;
  /** Whether to show the copy button in header. @default true */
  copyable?: boolean;
}

/**
 * CodeSnippet displays preformatted code blocks with language indicator, optional line numbers,
 * and built-in clipboard copying.
 */
const CodeSnippetRoot = forwardRef<HTMLDivElement, CodeSnippetProps>(function CodeSnippet(
  {
    code,
    language = 'bash',
    title,
    showLineNumbers = false,
    copyable = true,
    className,
    ...props
  },
  ref
) {
  const lines = code.trim().split('\n');

  return (
    <div ref={ref} className={cn('pui-code-snippet', className)} {...props}>
      <div className="pui-code-snippet__header">
        <div className="pui-code-snippet__meta">
          {title && <span className="pui-code-snippet__title">{title}</span>}
          {language && <span className="pui-code-snippet__lang">{language}</span>}
        </div>
        {copyable && <CopyButton value={code} size="sm" variant="ghost" label="Copy" />}
      </div>

      <pre className="pui-code-snippet__pre">
        <code>
          {showLineNumbers ? (
            <span className="pui-code-snippet__lines">
              {lines.map((line, i) => (
                <span key={i} className="pui-code-snippet__line">
                  <span className="pui-code-snippet__line-num">{i + 1}</span>
                  <span className="pui-code-snippet__line-text">{line}</span>
                </span>
              ))}
            </span>
          ) : (
            code
          )}
        </code>
      </pre>
    </div>
  );
});

export interface CodeTab {
  label: string;
  code: string;
  language?: string;
  icon?: ReactNode;
}

export interface CodeGroupProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  tabs: CodeTab[];
  defaultValue?: string;
  value?: string;
  onValueChange?: (tab: string) => void;
  showLineNumbers?: boolean;
  copyable?: boolean;
}

export const CodeGroup = forwardRef<HTMLDivElement, CodeGroupProps>(function CodeGroup(
  {
    tabs,
    defaultValue,
    value: controlledValue,
    onValueChange,
    showLineNumbers = false,
    copyable = true,
    className,
    ...props
  },
  ref
) {
  const [internalValue, setInternalValue] = useState(
    defaultValue || (tabs[0] ? tabs[0].label : '')
  );
  const activeLabel = controlledValue ?? internalValue;
  const activeTab = tabs.find((t) => t.label === activeLabel) || tabs[0];

  const handleTabChange = (label: string) => {
    setInternalValue(label);
    onValueChange?.(label);
  };

  const lines = activeTab?.code.trim().split('\n') || [];

  return (
    <div ref={ref} className={cn('pui-code-snippet pui-code-group', className)} {...props}>
      <div className="pui-code-snippet__header">
        <div className="pui-code-snippet__tabs" role="tablist">
          {tabs.map((tab) => {
            const isActive = tab.label === activeTab?.label;
            return (
              <button
                key={tab.label}
                type="button"
                role="tab"
                aria-selected={isActive}
                data-active={isActive ? 'true' : 'false'}
                className="pui-code-snippet__tab"
                onClick={() => handleTabChange(tab.label)}
              >
                {tab.icon && <span style={{ marginRight: '0.375rem' }}>{tab.icon}</span>}
                {tab.label}
              </button>
            );
          })}
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          {activeTab?.language && (
            <span className="pui-code-snippet__lang">{activeTab.language}</span>
          )}
          {copyable && activeTab?.code && (
            <CopyButton value={activeTab.code} size="sm" variant="ghost" label="Copy" />
          )}
        </div>
      </div>

      <pre className="pui-code-snippet__pre">
        <code>
          {showLineNumbers ? (
            <span className="pui-code-snippet__lines">
              {lines.map((line, i) => (
                <span key={i} className="pui-code-snippet__line">
                  <span className="pui-code-snippet__line-num">{i + 1}</span>
                  <span className="pui-code-snippet__line-text">{line}</span>
                </span>
              ))}
            </span>
          ) : (
            activeTab?.code
          )}
        </code>
      </pre>
    </div>
  );
});

export const CodeSnippet = Object.assign(CodeSnippetRoot, {
  Group: CodeGroup,
});

import {
  createContext,
  forwardRef,
  useContext,
  useId,
  type ButtonHTMLAttributes,
  type HTMLAttributes,
  type ReactNode,
} from 'react';
import { cn } from '../utils/cn';
import { useControllableState } from '../hooks/useControllableState';

interface CollapsibleContextValue {
  open: boolean;
  toggle: () => void;
  disabled?: boolean;
  contentId: string;
}

const CollapsibleContext = createContext<CollapsibleContextValue | null>(null);

export interface CollapsibleProps extends HTMLAttributes<HTMLDivElement> {
  /** Controlled open state. */
  open?: boolean;
  /** Default open state when uncontrolled. */
  defaultOpen?: boolean;
  /** Callback fired when open state changes. */
  onOpenChange?: (open: boolean) => void;
  /** Whether the collapsible is disabled. */
  disabled?: boolean;
  children: ReactNode;
}

/**
 * Collapsible provides an interactive disclosure container that can expand or collapse.
 */
export const Collapsible = forwardRef<HTMLDivElement, CollapsibleProps>(function Collapsible(
  {
    open: controlledOpen,
    defaultOpen = false,
    onOpenChange,
    disabled = false,
    className,
    children,
    ...props
  },
  ref
) {
  const [open, setOpen] = useControllableState<boolean>({
    value: controlledOpen,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  });

  const contentId = useId();

  const toggle = () => {
    if (disabled) return;
    setOpen(!open);
  };

  return (
    <CollapsibleContext.Provider value={{ open, toggle, disabled, contentId }}>
      <div
        ref={ref}
        data-state={open ? 'open' : 'closed'}
        className={cn('pui-collapsible', open && 'pui-collapsible--open', className)}
        {...props}
      >
        {children}
      </div>
    </CollapsibleContext.Provider>
  );
});

Collapsible.displayName = 'Collapsible';

export interface CollapsibleTriggerProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  children?: ReactNode;
}

export const CollapsibleTrigger = forwardRef<HTMLButtonElement, CollapsibleTriggerProps>(
  function CollapsibleTrigger({ className, children, onClick, ...props }, ref) {
    const ctx = useContext(CollapsibleContext);
    if (!ctx) throw new Error('CollapsibleTrigger must be used within a Collapsible');

    return (
      <button
        ref={ref}
        type="button"
        aria-expanded={ctx.open}
        aria-controls={ctx.contentId}
        disabled={ctx.disabled || props.disabled}
        data-state={ctx.open ? 'open' : 'closed'}
        onClick={(e) => {
          ctx.toggle();
          onClick?.(e);
        }}
        className={cn('pui-collapsible__trigger', className)}
        {...props}
      >
        {children}
      </button>
    );
  }
);

CollapsibleTrigger.displayName = 'CollapsibleTrigger';

export interface CollapsibleContentProps extends HTMLAttributes<HTMLDivElement> {
  children?: ReactNode;
}

export const CollapsibleContent = forwardRef<HTMLDivElement, CollapsibleContentProps>(
  function CollapsibleContent({ className, children, ...props }, ref) {
    const ctx = useContext(CollapsibleContext);
    if (!ctx) throw new Error('CollapsibleContent must be used within a Collapsible');

    if (!ctx.open) return null;

    return (
      <div
        ref={ref}
        id={ctx.contentId}
        data-state={ctx.open ? 'open' : 'closed'}
        className={cn('pui-collapsible__content', className)}
        {...props}
      >
        {children}
      </div>
    );
  }
);

CollapsibleContent.displayName = 'CollapsibleContent';

import {
  forwardRef,
  useState,
  useRef,
  type InputHTMLAttributes,
  type ChangeEvent,
} from 'react';
import { cn } from '../utils/cn';
import { useControllableState } from '../hooks/useControllableState';

export interface ColorPickerProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'value' | 'defaultValue' | 'onChange' | 'size'> {
  /** Current controlled color value (hex, e.g. '#6366f1'). */
  value?: string;
  /** Default uncontrolled color. */
  defaultValue?: string;
  /** Callback fired when color changes. */
  onChange?: (color: string) => void;
  /** Palette of quick-select preset colors. */
  presets?: string[];
  /** Size variant. @default 'md' */
  size?: 'sm' | 'md' | 'lg';
  /** Whether the color picker is disabled. */
  disabled?: boolean;
}

const DEFAULT_PRESETS = [
  '#0f172a', '#475569', '#ef4444', '#f97316',
  '#eab308', '#22c55e', '#06b6d4', '#3b82f6',
  '#6366f1', '#a855f7', '#ec4899', '#ffffff',
];

/**
 * ColorPicker with interactive color swatch, preset palette, hex input, and native color dialog integration.
 */
export const ColorPicker = forwardRef<HTMLDivElement, ColorPickerProps>(function ColorPicker(
  {
    value: controlledValue,
    defaultValue = '#6366f1',
    onChange,
    presets = DEFAULT_PRESETS,
    size = 'md',
    disabled = false,
    className,
    ...props
  },
  ref
) {
  const [color, setColor] = useControllableState<string>({
    value: controlledValue,
    defaultValue,
    onChange,
  });

  const nativeInputRef = useRef<HTMLInputElement | null>(null);

  const handleHexChange = (e: ChangeEvent<HTMLInputElement>) => {
    let val = e.target.value.trim();
    if (!val.startsWith('#')) val = `#${val}`;
    setColor(val);
  };

  const handleNativeChange = (e: ChangeEvent<HTMLInputElement>) => {
    setColor(e.target.value);
  };

  const openNativePicker = () => {
    if (disabled) return;
    nativeInputRef.current?.click();
  };

  return (
    <div
      ref={ref}
      className={cn(
        'pui-color-picker',
        `pui-color-picker--${size}`,
        disabled && 'pui-color-picker--disabled',
        className
      )}
    >
      {/* Hidden native color input for browser color wheel */}
      <input
        ref={nativeInputRef}
        type="color"
        value={color.length === 7 ? color : '#6366f1'}
        onChange={handleNativeChange}
        disabled={disabled}
        className="pui-color-picker__native"
        tabIndex={-1}
        aria-hidden="true"
      />

      <div className="pui-color-picker__input-row">
        {/* Clickable Swatch */}
        <button
          type="button"
          onClick={openNativePicker}
          disabled={disabled}
          className="pui-color-picker__swatch"
          style={{ backgroundColor: color }}
          title="Click to open color picker"
          aria-label={`Current color: ${color}`}
        />

        {/* Text hex input */}
        <input
          type="text"
          value={color}
          onChange={handleHexChange}
          disabled={disabled}
          maxLength={7}
          spellCheck={false}
          className="pui-color-picker__hex-input"
          {...props}
        />
      </div>

      {/* Preset Swatches Palette */}
      {presets && presets.length > 0 && (
        <div className="pui-color-picker__presets" role="radiogroup" aria-label="Preset colors">
          {presets.map((preset) => (
            <button
              key={preset}
              type="button"
              role="radio"
              aria-checked={color.toLowerCase() === preset.toLowerCase()}
              disabled={disabled}
              className={cn(
                'pui-color-picker__preset-btn',
                color.toLowerCase() === preset.toLowerCase() && 'pui-color-picker__preset-btn--selected'
              )}
              style={{ backgroundColor: preset }}
              onClick={() => setColor(preset)}
              title={preset}
              aria-label={preset}
            />
          ))}
        </div>
      )}
    </div>
  );
});

ColorPicker.displayName = 'ColorPicker';

'use client';

import { useCallback, useId, useMemo, useRef, useState, type ReactNode } from 'react';
import { cn } from '../utils/cn';
import { Portal } from './Portal';
import { useFloating } from '../hooks/useFloating';
import { useDismiss } from '../hooks/useDismiss';
import { FieldShell } from './Field';
import { CheckIcon, ChevronDownIcon, PlusIcon, SearchIcon, XIcon } from './icons';
import { Spinner } from './Feedback';

export interface ComboboxOption {
  value: string;
  label: string;
  /** Extra text matched by the filter but shown as a secondary line. */
  keywords?: string[];
  disabled?: boolean;
  icon?: ReactNode;
  /** Category or group name. */
  group?: string;
  /** Secondary description text shown below label. */
  description?: string;
}

export interface ComboboxProps {
  options: readonly ComboboxOption[];
  /** Single selection value (controlled). */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;

  /** Multi-select mode with removable tags. */
  multiple?: boolean;
  values?: string[];
  defaultValues?: string[];
  onValuesChange?: (values: string[]) => void;

  /** Size variant. */
  size?: 'sm' | 'md' | 'lg';

  /** Custom option renderer. */
  renderOption?: (
    option: ComboboxOption,
    state: { selected: boolean; active: boolean }
  ) => ReactNode;

  label?: ReactNode;
  hint?: ReactNode;
  error?: ReactNode;
  placeholder?: string;
  emptyMessage?: string;
  disabled?: boolean;
  loading?: boolean;
  /** Let the user type to narrow the list. */
  searchable?: boolean;
  /** Clear the selection with an inline X. */
  clearable?: boolean;
  className?: string;
  id?: string;
  /** Callback fired as the user types, for asynchronous or server-side searching. */
  onSearchChange?: (query: string) => void;
  /** Whether to filter options client-side. Set to false when doing server-side search. @default true */
  filterOptions?: boolean;
  /** Allow users to create custom options by typing. */
  creatable?: boolean;
  /** Callback fired when a new custom option is created. */
  onCreateOption?: (query: string) => void;
  /** Custom renderer for the create option item. */
  createMessage?: (query: string) => ReactNode;
}

/**
 * Accessible combobox (WAI-ARIA 1.2 editable combobox with listbox popup).
 *
 * - The input keeps DOM focus; the highlighted option is tracked with
 *   `aria-activedescendant`, so screen readers announce it without moving focus.
 * - Supports grouped option categories, multi-select with removable tags,
 *   custom item rendering, and size variants (`sm`, `md`, `lg`).
 * - Home/End, PageUp/PageDown and arrow keys behave like a native select.
 */
export function Combobox({
  options,
  value,
  defaultValue = '',
  onValueChange,
  multiple = false,
  values,
  defaultValues = [],
  onValuesChange,
  size = 'md',
  renderOption,
  label,
  hint,
  error,
  placeholder = 'Select…',
  emptyMessage = 'No results found',
  disabled = false,
  loading = false,
  searchable = true,
  clearable = false,
  className,
  id: providedId,
}: ComboboxProps) {
  const generatedId = useId();
  const id = providedId ?? generatedId;
  const listboxId = `${id}-listbox`;

  const [selected, setSelected] = useControlled(value, defaultValue, onValueChange);
  const [internalValues, setInternalValues] = useState<string[]>(defaultValues);
  const selectedValues = values !== undefined ? values : internalValues;

  const [query, setQuery] = useState('');
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const [dirty, setDirty] = useState(false);

  const inputRef = useRef<HTMLInputElement>(null);
  const wrapRef = useRef<HTMLDivElement>(null);

  const filtered = useMemo(() => {
    const term = query.trim().toLowerCase();
    if (!term) return options;
    return options.filter((option) => {
      const haystack = [option.label, option.description, ...(option.keywords ?? [])]
        .filter(Boolean)
        .join(' ')
        .toLowerCase();
      return haystack.includes(term);
    });
  }, [options, query]);

  // Grouped structure preserving flat index for keyboard accessibility
  const groupedItems = useMemo(() => {
    const hasGroups = filtered.some((o) => o.group);
    if (!hasGroups) {
      return filtered.map((option, index) => ({ type: 'option' as const, option, index }));
    }
    const groups: { name: string; items: { option: ComboboxOption; index: number }[] }[] = [];
    const map = new Map<string, { option: ComboboxOption; index: number }[]>();

    filtered.forEach((option, index) => {
      const grp = option.group || 'Other';
      if (!map.has(grp)) {
        map.set(grp, []);
        groups.push({ name: grp, items: map.get(grp)! });
      }
      map.get(grp)!.push({ option, index });
    });

    const result: (
      | { type: 'header'; name: string }
      | { type: 'option'; option: ComboboxOption; index: number }
    )[] = [];

    groups.forEach((g) => {
      result.push({ type: 'header', name: g.name });
      g.items.forEach((item) => {
        result.push({ type: 'option', option: item.option, index: item.index });
      });
    });

    return result;
  }, [filtered]);

  const { setFloating, floatingRef, coords, ready } = useFloating<HTMLDivElement>(wrapRef, open, {
    placement: 'bottom',
    align: 'start',
    offset: 4,
    matchWidth: true,
  });

  const close = useCallback(() => {
    setOpen(false);
    setActiveIndex(-1);
    setQuery('');
    setDirty(false);
  }, []);

  useDismiss(wrapRef, open, close, { escape: true, outside: true, ignore: [floatingRef] });

  const commit = useCallback(
    (optionValue: string) => {
      if (multiple) {
        const next = selectedValues.includes(optionValue)
          ? selectedValues.filter((v) => v !== optionValue)
          : [...selectedValues, optionValue];
        if (values === undefined) setInternalValues(next);
        onValuesChange?.(next);
        setQuery('');
        setDirty(false);
        inputRef.current?.focus();
      } else {
        setSelected(optionValue);
        close();
        inputRef.current?.focus();
      }
    },
    [multiple, selectedValues, values, onValuesChange, setSelected, close]
  );

  const removeValue = (valToRemove: string) => {
    const next = selectedValues.filter((v) => v !== valToRemove);
    if (values === undefined) setInternalValues(next);
    onValuesChange?.(next);
  };

  const onKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (disabled) return;

    switch (event.key) {
      case 'Backspace':
        if (multiple && query === '' && selectedValues.length > 0) {
          removeValue(selectedValues[selectedValues.length - 1]!);
        }
        return;
      case 'ArrowDown':
        event.preventDefault();
        if (!open) {
          setOpen(true);
          setActiveIndex(filtered.findIndex((option) => !option.disabled));
          return;
        }
        setActiveIndex((prev) => nextEnabled(filtered, prev, 1));
        return;
      case 'ArrowUp':
        event.preventDefault();
        setActiveIndex((prev) => nextEnabled(filtered, prev, -1));
        return;
      case 'Home':
        if (!open) return;
        event.preventDefault();
        setActiveIndex(filtered.findIndex((option) => !option.disabled));
        return;
      case 'End':
        if (!open) return;
        event.preventDefault();
        setActiveIndex(findLastEnabled(filtered));
        return;
      case 'Enter':
        if (open && activeIndex >= 0) {
          event.preventDefault();
          const option = filtered[activeIndex];
          if (option && !option.disabled) commit(option.value);
        }
        return;
      case 'Escape':
        if (open) {
          event.preventDefault();
          close();
        }
        return;
      case 'Tab':
        if (open) close();
        return;
      default:
        if (!searchable && event.key.length === 1) event.preventDefault();
    }
  };

  const selectedOption = options.find((option) => option.value === selected);
  const displayValue = multiple
    ? query
    : open && dirty
      ? query
      : (selectedOption?.label ?? '');

  const hasSelection = multiple ? selectedValues.length > 0 : Boolean(selectedOption);

  const iconSize = size === 'sm' ? '0.875rem' : size === 'lg' ? '1.125rem' : '1rem';

  return (
    <FieldShell
      id={id}
      label={label}
      hint={hint}
      error={error}
      className={cn('pui-combobox', className)}
    >
      {(describedBy) => (
        <div ref={wrapRef} style={{ position: 'relative' }}>
          <div
            className={cn(
              'pui-input-wrap',
              'pui-input-wrap--start',
              'pui-input-wrap--end',
              size !== 'md' && `pui-input-wrap--${size}`
            )}
            onClick={() => {
              if (!disabled) {
                inputRef.current?.focus();
                setOpen(true);
              }
            }}
          >
            <span className="pui-affix pui-affix--start">
              {loading ? <Spinner size={size === 'lg' ? 'md' : 'sm'} /> : <SearchIcon size={iconSize} />}
            </span>

            {multiple && selectedValues.length > 0 && (
              <div className="pui-combobox__tags">
                {selectedValues.map((val) => {
                  const opt = options.find((o) => o.value === val);
                  return (
                    <span key={val} className="pui-combobox__tag">
                      {opt?.icon}
                      <span>{opt?.label ?? val}</span>
                      {!disabled && (
                        <button
                          type="button"
                          aria-label={`Remove ${opt?.label ?? val}`}
                          onClick={(e) => {
                            e.stopPropagation();
                            removeValue(val);
                          }}
                        >
                          <XIcon size="0.75rem" />
                        </button>
                      )}
                    </span>
                  );
                })}
              </div>
            )}

            <input
              ref={inputRef}
              id={id}
              className={cn(
                'pui-control',
                size !== 'md' && `pui-control--${size}`,
                multiple && 'pui-combobox__input-inline'
              )}
              role="combobox"
              aria-expanded={open}
              aria-controls={listboxId}
              aria-autocomplete={searchable ? 'list' : 'none'}
              aria-activedescendant={
                open && activeIndex >= 0 ? `${id}-opt-${activeIndex}` : undefined
              }
              aria-invalid={error ? true : undefined}
              aria-describedby={describedBy}
              autoComplete="off"
              disabled={disabled}
              placeholder={multiple && selectedValues.length > 0 ? '' : placeholder}
              value={displayValue}
              readOnly={!searchable}
              onChange={(event) => {
                setQuery(event.target.value);
                setDirty(true);
                setOpen(true);
                setActiveIndex(filtered.findIndex((option) => !option.disabled));
              }}
              onFocus={() => !disabled && setOpen(true)}
              onKeyDown={onKeyDown}
              style={{ cursor: searchable || disabled ? undefined : 'pointer' }}
            />

            <span className="pui-affix pui-affix--end" style={{ gap: '0.25rem', pointerEvents: 'auto' }}>
              {clearable && hasSelection && !disabled && (
                <button
                  type="button"
                  aria-label="Clear selection"
                  onClick={(e) => {
                    e.stopPropagation();
                    if (multiple) {
                      if (values === undefined) setInternalValues([]);
                      onValuesChange?.([]);
                    } else {
                      setSelected('');
                    }
                    setQuery('');
                    inputRef.current?.focus();
                  }}
                  style={{ display: 'inline-flex', color: 'inherit', background: 'none', border: 'none', cursor: 'pointer' }}
                >
                  <XIcon size={size === 'sm' ? '0.75rem' : size === 'lg' ? '1rem' : '0.875rem'} />
                </button>
              )}
              <span aria-hidden="true" style={{ color: 'var(--pui-fg-subtle)' }}>
                <ChevronDownIcon size={iconSize} />
              </span>
            </span>
          </div>

          {open && (
            <Portal>
              <div
                ref={setFloating}
                id={listboxId}
                role="listbox"
                aria-label={typeof label === 'string' ? label : 'Options'}
                aria-multiselectable={multiple ? 'true' : undefined}
                className="pui-combobox__listbox"
                style={{
                  position: 'fixed',
                  top: coords.y,
                  left: coords.x,
                  visibility: ready ? 'visible' : 'hidden',
                  zIndex: 'var(--pui-z-popover, 1300)',
                }}
              >
                {filtered.length === 0 ? (
                  <div className="pui-combobox__empty">{emptyMessage}</div>
                ) : (
                  groupedItems.map((item) => {
                    if (item.type === 'header') {
                      return (
                        <div key={`group-${item.name}`} className="pui-combobox__group-header">
                          {item.name}
                        </div>
                      );
                    }

                    const { option, index } = item;
                    const isOptSelected = multiple
                      ? selectedValues.includes(option.value)
                      : option.value === selected;
                    const isOptActive = index === activeIndex;

                    return (
                      <div
                        key={option.value}
                        id={`${id}-opt-${index}`}
                        role="option"
                        aria-selected={isOptSelected}
                        aria-disabled={option.disabled || undefined}
                        data-active={isOptActive ? 'true' : undefined}
                        data-selected={isOptSelected ? 'true' : undefined}
                        className="pui-combobox__option"
                        onMouseEnter={() => !option.disabled && setActiveIndex(index)}
                        onMouseDown={(event) => {
                          // Keep focus on the input; mousedown would otherwise blur it.
                          event.preventDefault();
                          if (!option.disabled) commit(option.value);
                        }}
                        onClick={(event) => {
                          event.preventDefault();
                          if (!option.disabled) commit(option.value);
                        }}
                      >
                        {renderOption ? (
                          renderOption(option, { selected: isOptSelected, active: isOptActive })
                        ) : (
                          <>
                            {option.icon}
                            <div className="pui-combobox__option-content">
                              <span className="pui-combobox__option-label">{option.label}</span>
                              {option.description && (
                                <span className="pui-combobox__option-desc">{option.description}</span>
                              )}
                            </div>
                            {isOptSelected && (
                              <span className="pui-combobox__option__check">
                                <CheckIcon />
                              </span>
                            )}
                          </>
                        )}
                      </div>
                    );
                  })
                )}
              </div>
            </Portal>
          )}
        </div>
      )}
    </FieldShell>
  );
}

function useControlled(
  value: string | undefined,
  defaultValue: string,
  onValueChange?: (value: string) => void
) {
  const [internal, setInternal] = useState(defaultValue);
  const isControlled = value !== undefined;
  const current = isControlled ? value : internal;

  const setSelected = useCallback(
    (next: string) => {
      if (!isControlled) setInternal(next);
      onValueChange?.(next);
    },
    [isControlled, onValueChange]
  );

  return [current, setSelected] as const;
}

function nextEnabled(options: readonly ComboboxOption[], from: number, delta: number) {
  if (options.length === 0) return -1;
  let index = from;
  for (let step = 0; step < options.length; step += 1) {
    index = (index + delta + options.length) % options.length;
    if (!options[index]?.disabled) return index;
  }
  return from;
}

function findLastEnabled(options: readonly ComboboxOption[]) {
  for (let index = options.length - 1; index >= 0; index -= 1) {
    if (!options[index]?.disabled) return index;
  }
  return -1;
}

import {
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { Portal } from './Portal';
import { useScrollLock } from '../hooks/useScrollLock';
import { useFocusTrap } from '../hooks/useFocusTrap';
import { useDismiss } from '../hooks/useDismiss';
import { SearchIcon } from './icons';

export interface CommandItem {
  id: string;
  label: string;
  group?: string;
  hint?: string;
  icon?: ReactNode;
  keywords?: string[];
  disabled?: boolean;
  onSelect?: () => void;
}

export interface CommandProps {
  items: CommandItem[];
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  placeholder?: string;
  emptyMessage?: string;
}

/**
 * ⌘K command palette.
 *
 * Implements the combobox-with-listbox pattern: the search input keeps DOM
 * focus, the highlighted row is tracked with `aria-activedescendant`, arrow
 * keys wrap, Home/End jump, and Enter activates.
 */
export function Command({
  items,
  open: openProp,
  onOpenChange,
  placeholder = 'Search commands…',
  emptyMessage = 'No results found',
}: CommandProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(false);
  const open = openProp ?? uncontrolledOpen;
  const setOpen = onOpenChange ?? setUncontrolledOpen;

  const [query, setQuery] = useState('');
  const [activeIndex, setActiveIndex] = useState(0);
  const [panel, setPanel] = useState<HTMLDivElement | null>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const baseId = `pui-cmd-${useId()}`;

  useScrollLock(open);
  useFocusTrap(panel, open);
  // The footer advertises "esc" — so it has to work. Backdrop clicks are
  // handled by the overlay, not here.
  useDismiss(panel, open, () => setOpen(false), { escape: true, outside: false });

  const filtered = useMemo(() => {
    const term = query.trim().toLowerCase();
    if (!term) return items;
    return items.filter((item) =>
      `${item.label} ${item.group ?? ''} ${(item.keywords ?? []).join(' ')}`
        .toLowerCase()
        .includes(term)
    );
  }, [items, query]);

  const enabled = useMemo(
    () =>
      filtered
        .map((item, index) => (item.disabled ? -1 : index))
        .filter((index) => index !== -1),
    [filtered]
  );

  // Reset the highlight whenever the search query or open state changes.
  useEffect(() => {
    setActiveIndex(enabled[0] ?? 0);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [query, open]);

  useEffect(() => {
    if (!open) setQuery('');
  }, [open]);

  useEffect(() => {
    if (!open) return;
    const onKeyDown = (event: KeyboardEvent) => {
      const isCmdK = (event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k';
      const isAltK = event.altKey && event.key.toLowerCase() === 'k';
      if (isCmdK || isAltK) {
        event.preventDefault();
        setOpen(false);
      }
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [open, setOpen]);

  useLayoutEffect(() => {
    if (!open || activeIndex < 0) return;
    listRef.current
      ?.querySelector<HTMLElement>(`[data-index="${activeIndex}"]`)
      ?.scrollIntoView({ block: 'nearest' });
  }, [activeIndex, open]);

  const activate = (index: number) => {
    const item = filtered[index];
    if (!item || item.disabled) return;
    setOpen(false);
    item.onSelect?.();
  };

  const onKeyDown = (event: React.KeyboardEvent) => {
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        setActiveIndex((prev) => {
          const pos = enabled.indexOf(prev);
          return enabled[(pos + 1) % enabled.length] ?? prev;
        });
        break;
      case 'ArrowUp':
        event.preventDefault();
        setActiveIndex((prev) => {
          const pos = enabled.indexOf(prev);
          return enabled[(pos - 1 + enabled.length) % enabled.length] ?? prev;
        });
        break;
      case 'Home':
        event.preventDefault();
        setActiveIndex(enabled[0] ?? 0);
        break;
      case 'End':
        event.preventDefault();
        setActiveIndex(enabled[enabled.length - 1] ?? 0);
        break;
      case 'Enter':
        event.preventDefault();
        activate(activeIndex);
        break;
    }
  };

  if (!open) return null;

  // Group while preserving the filtered order.
  const groups: { name: string; items: { item: CommandItem; index: number }[] }[] = [];
  filtered.forEach((item, index) => {
    const name = item.group ?? '';
    let group = groups.find((entry) => entry.name === name);
    if (!group) {
      group = { name, items: [] };
      groups.push(group);
    }
    group.items.push({ item, index });
  });

  return (
    <Portal>
      <div
        className="pui-command-overlay"
        onMouseDown={(event) => {
          if (event.target === event.currentTarget) setOpen(false);
        }}
      >
        <div
          ref={setPanel}
          role="dialog"
          aria-modal="true"
          aria-label="Command palette"
          className="pui-command"
          onMouseDown={(event) => event.stopPropagation()}
          onKeyDown={onKeyDown}
        >
          <div className="pui-command__search">
            <SearchIcon />
            <input
              className="pui-command__input"
              role="combobox"
              aria-expanded="true"
              aria-controls={`${baseId}-list`}
              aria-activedescendant={
                filtered[activeIndex] ? `${baseId}-opt-${activeIndex}` : undefined
              }
              aria-autocomplete="list"
              autoComplete="off"
              placeholder={placeholder}
              value={query}
              data-autofocus
              onChange={(event) => setQuery(event.target.value)}
            />
            <kbd className="pui-kbd pui-command__kbd">esc</kbd>
          </div>

          <div className="pui-command__list" ref={listRef} id={`${baseId}-list`} role="listbox">
            {filtered.length === 0 ? (
              <div className="pui-command__empty">{emptyMessage}</div>
            ) : (
              groups.map((group) => (
                <div key={group.name} className="pui-command__group" role="group" aria-label={group.name || undefined}>
                  {group.name && <div className="pui-command__group-label">{group.name}</div>}
                  {group.items.map(({ item, index }) => (
                    <div
                      key={item.id}
                      id={`${baseId}-opt-${index}`}
                      role="option"
                      aria-selected={index === activeIndex}
                      aria-disabled={item.disabled || undefined}
                      data-index={index}
                      data-active={index === activeIndex ? 'true' : undefined}
                      data-disabled={item.disabled ? 'true' : undefined}
                      className="pui-command__item"
                      onMouseEnter={() => !item.disabled && setActiveIndex(index)}
                      onMouseDown={(event) => {
                        event.preventDefault();
                        activate(index);
                      }}
                    >
                      {item.icon && <span className="pui-command__item__icon">{item.icon}</span>}
                      <span className="pui-command__item__label">{item.label}</span>
                      {item.hint && <span className="pui-command__item__hint">{item.hint}</span>}
                    </div>
                  ))}
                </div>
              ))
            )}
          </div>

          <div className="pui-command__footer">
            <span>
              <kbd className="pui-kbd">↑</kbd> <kbd className="pui-kbd">↓</kbd> navigate
            </span>
            <span>
              <kbd className="pui-kbd">↵</kbd> select
            </span>
            <span style={{ marginInlineStart: 'auto' }}>{filtered.length} results</span>
          </div>
        </div>
      </div>
    </Portal>
  );
}

/** Registers the Ctrl+K / Alt+K / ⌘K shortcut and reports whether the palette should open. */
export function useCommandShortcut(onToggle: () => void) {
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      const isCmdK = (event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k';
      const isAltK = event.altKey && event.key.toLowerCase() === 'k';
      if (isCmdK || isAltK) {
        event.preventDefault();
        onToggle();
      }
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [onToggle]);
}

import React, { useEffect, useRef, useCallback, type CanvasHTMLAttributes } from 'react';
import { Portal } from './Portal';

export interface ConfettiOrigin {
  /** Normalized x coordinate from 0 (left) to 1 (right). Defaults to 0.5 (center). */
  x?: number;
  /** Normalized y coordinate from 0 (top) to 1 (bottom). Defaults to 0.6. */
  y?: number;
}

export interface ConfettiOptions {
  /** Total number of confetti particles to emit. Defaults to 75. */
  particleCount?: number;
  /** Cone angle spread in degrees. Defaults to 65. */
  spread?: number;
  /** Launch speed velocity. Defaults to 35. */
  startVelocity?: number;
  /** Particle air drag decay rate. Defaults to 0.92. */
  decay?: number;
  /** Downward gravity acceleration multiplier. Defaults to 1. */
  gravity?: number;
  /** Launch angle in degrees (90 = straight up). Defaults to 90. */
  angle?: number;
  /** Palette of hex/hsl colors. Defaults to curated rainbow palette. */
  colors?: string[];
  /** Launch origin coordinate. */
  origin?: ConfettiOrigin;
  /** Callback fired after all particles have settled and faded out. */
  onComplete?: () => void;
}

export interface ConfettiProps extends CanvasHTMLAttributes<HTMLCanvasElement>, ConfettiOptions {
  /** When true or changes to true, fires a confetti celebration blast. */
  active?: boolean;
}

const DEFAULT_COLORS = [
  '#6366f1', // Indigo
  '#ec4899', // Pink
  '#3b82f6', // Blue
  '#10b981', // Emerald
  '#f59e0b', // Amber
  '#8b5cf6', // Violet
  '#06b6d4', // Cyan
];

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  color: string;
  size: number;
  rotation: number;
  vRot: number;
  opacity: number;
  shape: 'rect' | 'circle' | 'strip';
}

/**
 * Imperative confetti fire function that appends a temporary canvas to the document body.
 */
export function fireConfetti(options: ConfettiOptions = {}) {
  if (typeof window === 'undefined') return;

  const {
    particleCount = 80,
    spread = 70,
    startVelocity = 40,
    decay = 0.92,
    gravity = 1,
    angle = 90,
    colors = DEFAULT_COLORS,
    origin = { x: 0.5, y: 0.6 },
    onComplete,
  } = options;

  const canvas = document.createElement('canvas');
  canvas.style.position = 'fixed';
  canvas.style.inset = '0';
  canvas.style.width = '100vw';
  canvas.style.height = '100vh';
  canvas.style.pointerEvents = 'none';
  canvas.style.zIndex = '99999';
  document.body.appendChild(canvas);

  const ctx = canvas.getContext('2d');
  if (!ctx) {
    document.body.removeChild(canvas);
    return;
  }

  const dpr = window.devicePixelRatio || 1;
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);

  const startX = (origin.x ?? 0.5) * window.innerWidth;
  const startY = (origin.y ?? 0.6) * window.innerHeight;

  const particles: Particle[] = [];
  const radAngle = (angle * Math.PI) / 180;
  const radSpread = (spread * Math.PI) / 180;

  for (let i = 0; i < particleCount; i++) {
    const pAngle = radAngle + (Math.random() - 0.5) * radSpread;
    const velocity = startVelocity * (0.6 + Math.random() * 0.8);
    const shapes: ('rect' | 'circle' | 'strip')[] = ['rect', 'circle', 'strip'];

    particles.push({
      x: startX,
      y: startY,
      vx: Math.cos(pAngle) * velocity,
      vy: -Math.sin(pAngle) * velocity,
      color: colors[Math.floor(Math.random() * colors.length)] ?? '#6366f1',
      size: Math.random() * 6 + 5,
      rotation: Math.random() * 360,
      vRot: (Math.random() - 0.5) * 12,
      opacity: 1,
      shape: shapes[Math.floor(Math.random() * shapes.length)] ?? 'rect',
    });
  }

  let animId: number;

  function render() {
    if (!ctx) return;
    ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);

    let activeCount = 0;

    for (const p of particles) {
      if (p.opacity <= 0.01) continue;
      activeCount++;

      p.x += p.vx;
      p.y += p.vy;
      p.vx *= decay;
      p.vy = p.vy * decay + gravity * 0.45;
      p.rotation += p.vRot;
      p.opacity -= 0.009;

      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate((p.rotation * Math.PI) / 180);
      ctx.globalAlpha = Math.max(0, p.opacity);
      ctx.fillStyle = p.color;

      if (p.shape === 'circle') {
        ctx.beginPath();
        ctx.arc(0, 0, p.size / 2, 0, Math.PI * 2);
        ctx.fill();
      } else if (p.shape === 'strip') {
        ctx.fillRect(-p.size / 4, -p.size, p.size / 2, p.size * 2);
      } else {
        ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
      }

      ctx.restore();
    }

    if (activeCount > 0) {
      animId = requestAnimationFrame(render);
    } else {
      cancelAnimationFrame(animId);
      if (document.body.contains(canvas)) {
        document.body.removeChild(canvas);
      }
      onComplete?.();
    }
  }

  animId = requestAnimationFrame(render);
}

/**
 * Declarative Confetti component. Fires when `active` transitions to true.
 */
export function Confetti({
  active = false,
  particleCount = 80,
  spread = 70,
  startVelocity = 40,
