          <div
            ref={menuRef}
            id={menuId}
            role="menu"
            aria-orientation="vertical"
            tabIndex={-1}
            onKeyDown={handleKeyDown}
            className={cn(
              'pui-menu',
              'pui-context-menu',
              `pui-menu--${size}`,
              menuClassName
