            style={{
              position: 'fixed',
              left: `${position.x}px`,
              top: `${position.y}px`,
              zIndex: 'var(--pui-z-popover, 1300)',
            }}
          >
            {items.map((entry, index) => {
              const key = entry.id ?? `ctx-${index}`;

              if (entry.kind === 'separator') {
                return <div key={key} className="pui-menu__separator" role="separator" />;
              }

              if (entry.kind === 'label') {
                return (
                  <div key={key} className="pui-menu__label">
                    {entry.label}
                  </div>
                );
              }

              if (entry.kind === 'checkbox') {
                return (
                  <div
                    key={key}
                    role="menuitemcheckbox"
                    aria-checked={entry.checked}
                    aria-disabled={entry.disabled || undefined}
                    data-disabled={entry.disabled ? 'true' : undefined}
                    data-active={index === activeIndex ? 'true' : undefined}
                    data-index={index}
                    tabIndex={index === activeIndex ? 0 : -1}
                    className={cn(
                      'pui-menu__item',
                      entry.inset && 'pui-menu__item--inset'
                    )}
                    onClick={() => {
                      if (!entry.disabled) {
                        entry.onCheckedChange(!entry.checked);
                      }
                    }}
                    onMouseEnter={() => {
                      if (!entry.disabled) {
                        setActiveIndex(index);
                        setOpenSubmenuIndex(null);
                      }
                    }}
                  >
                    <span className="pui-menu__checkbox" aria-hidden="true">
                      {entry.checked && <CheckIcon size={14} />}
                    </span>
                    <div className="pui-menu__item__body">
                      <div className="pui-menu__item__title">{entry.label}</div>
                      {entry.description && (
                        <div className="pui-menu__item__desc">{entry.description}</div>
                      )}
                    </div>
                  </div>
                );
              }

              if (entry.kind === 'radio') {
                return (
                  <div
                    key={key}
                    role="menuitemradio"
                    aria-checked={entry.checked}
                    aria-disabled={entry.disabled || undefined}
                    data-disabled={entry.disabled ? 'true' : undefined}
                    data-active={index === activeIndex ? 'true' : undefined}
                    data-index={index}
                    tabIndex={index === activeIndex ? 0 : -1}
                    className={cn(
                      'pui-menu__item',
                      entry.inset && 'pui-menu__item--inset'
                    )}
                    onClick={() => {
                      if (!entry.disabled) {
                        entry.onSelect?.(entry.value);
                        close();
                      }
                    }}
                    onMouseEnter={() => {
                      if (!entry.disabled) {
                        setActiveIndex(index);
                        setOpenSubmenuIndex(null);
                      }
                    }}
                  >
                    <span className="pui-menu__radio" aria-hidden="true">
                      {entry.checked && <span className="pui-menu__radio-bullet" />}
                    </span>
                    <div className="pui-menu__item__body">
                      <div className="pui-menu__item__title">{entry.label}</div>
                      {entry.description && (
                        <div className="pui-menu__item__desc">{entry.description}</div>
                      )}
                    </div>
                  </div>
                );
              }

              if (entry.kind === 'submenu') {
                const isSubOpen = openSubmenuIndex === index;
                return (
                  <div
                    key={key}
                    ref={(el) => {
                      if (el) itemElementsRef.current.set(index, el);
                      else itemElementsRef.current.delete(index);
                    }}
                    role="menuitem"
                    aria-haspopup="menu"
                    aria-expanded={isSubOpen}
                    aria-disabled={entry.disabled || undefined}
                    data-disabled={entry.disabled ? 'true' : undefined}
                    data-active={index === activeIndex || isSubOpen ? 'true' : undefined}
                    data-index={index}
                    tabIndex={index === activeIndex ? 0 : -1}
                    className={cn(
                      'pui-menu__item',
                      'pui-menu__submenu-trigger',
                      entry.inset && 'pui-menu__item--inset'
                    )}
                    onClick={() => {
                      if (!entry.disabled) {
                        setOpenSubmenuIndex((prev) => (prev === index ? null : index));
                      }
                    }}
                    onMouseEnter={() => {
                      if (!entry.disabled) {
                        setActiveIndex(index);
                        setOpenSubmenuIndex(index);
                      }
                    }}
                  >
                    {entry.icon && <span className="pui-menu__item__icon">{entry.icon}</span>}
                    <div className="pui-menu__item__body">
                      <div className="pui-menu__item__title">{entry.label}</div>
                      {entry.description && (
                        <div className="pui-menu__item__desc">{entry.description}</div>
                      )}
                    </div>
                    <span className="pui-menu__chevron" aria-hidden="true">
                      <ChevronRightIcon size={14} />
                    </span>
                  </div>
                );
              }

              return (
                <div
                  key={key}
                  role="menuitem"
                  aria-disabled={entry.disabled || undefined}
                  data-disabled={entry.disabled ? 'true' : undefined}
                  data-active={index === activeIndex ? 'true' : undefined}
                  data-index={index}
                  tabIndex={index === activeIndex ? 0 : -1}
                  className={cn(
                    'pui-menu__item',
                    entry.tone === 'danger' && 'pui-menu__item--danger',
                    entry.inset && 'pui-menu__item--inset'
                  )}
                  onClick={() => {
                    if (!entry.disabled) {
                      entry.onSelect?.();
                      close();
                    }
                  }}
                  onMouseEnter={() => {
                    if (!entry.disabled) {
                      setActiveIndex(index);
                      setOpenSubmenuIndex(null);
                    }
                  }}
                >
                  {entry.icon && <span className="pui-menu__item__icon">{entry.icon}</span>}
                  <div className="pui-menu__item__body">
                    <div className="pui-menu__item__title">{entry.label}</div>
                    {entry.description && (
                      <div className="pui-menu__item__desc">{entry.description}</div>
                    )}
                  </div>
                  {entry.shortcut && (
                    <span className="pui-menu__item__shortcut">{entry.shortcut}</span>
                  )}
                </div>
              );
            })}
          </div>
        </Portal>
      )}
    </div>
  );
}

import {
  forwardRef,
  useState,
  type ButtonHTMLAttributes,
  type ReactNode,
} from 'react';
import { cn } from '../utils/cn';
import { CheckIcon, CopyIcon } from './icons';

export interface CopyButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** Text content to be copied to the clipboard. */
  value: string;
  /** Duration in ms for the copied state before resetting. @default 2000 */
  timeout?: number;
  /** Size variant. @default 'md' */
  size?: 'sm' | 'md' | 'lg';
  /** Visual variant. @default 'ghost' */
  variant?: 'ghost' | 'outline' | 'secondary' | 'solid';
  /** Optional custom label next to icon. */
  label?: ReactNode;
  /** Callback fired upon successful copy. */
  onCopySuccess?: (copiedValue: string) => void;
}

/**
 * CopyButton provides a one-click clipboard copy action with instant checkmark feedback.
 */
export const CopyButton = forwardRef<HTMLButtonElement, CopyButtonProps>(function CopyButton(
  {
    value,
    timeout = 2000,
    size = 'md',
    variant = 'ghost',
    label,
    onCopySuccess,
    className,
    disabled = false,
    onClick,
    ...props
  },
  ref
) {
  const [copied, setCopied] = useState(false);

  const handleCopy = async (e: React.MouseEvent<HTMLButtonElement>) => {
    if (disabled) return;
    try {
      await navigator.clipboard.writeText(value);
      setCopied(true);
      onCopySuccess?.(value);
      setTimeout(() => setCopied(false), timeout);
    } catch (err) {
      console.error('Failed to copy to clipboard', err);
    }
    onClick?.(e);
  };

  return (
    <button
      ref={ref}
      type="button"
      disabled={disabled}
      aria-label={copied ? 'Copied to clipboard' : 'Copy to clipboard'}
      data-copied={copied || undefined}
      onClick={handleCopy}
      className={cn(
        'pui-copy-btn',
        `pui-copy-btn--${variant}`,
        `pui-copy-btn--${size}`,
        copied && 'pui-copy-btn--copied',
        className
      )}
      {...props}
    >
      <span className="pui-copy-btn__icon" aria-hidden="true">
        {copied ? <CheckIcon /> : <CopyIcon />}
      </span>
      {label && <span className="pui-copy-btn__label">{copied ? 'Copied!' : label}</span>}
    </button>
  );
});

CopyButton.displayName = 'CopyButton';

'use client';

import { Fragment, useId, useState, type ReactNode } from 'react';
import { cn } from '../utils/cn';
import { Checkbox } from './Choice';
import { Skeleton } from './Badge';
import { Spinner } from './Feedback';
import { ChevronDownIcon, ChevronUpIcon, ChevronRightIcon } from './icons';

export type SortDirection = 'asc' | 'desc';

export interface SortState {
  column: string;
  direction: SortDirection;
}

export interface Column<T> {
  id: string;
  header: ReactNode;
  /** Prefer `accessor` + `cell` so sorting and rendering stay in sync. */
  accessor?: (row: T) => string | number;
  cell?: (row: T, index: number) => ReactNode;
  sortable?: boolean;
  numeric?: boolean;
  width?: string | number;
  align?: 'start' | 'center' | 'end';
  /** Hide below the given breakpoint ('mobile' <= 640px, 'tablet' <= 860px, or custom px). */
  hideBelow?: number | 'mobile' | 'tablet';
  /** Additional CSS class for custom column styles. */
  className?: string;
}

export interface DataTableProps<T> {
  columns: readonly Column<T>[];
  data: readonly T[];
  rowKey: (row: T, index: number) => string;
  sort?: SortState | null;
  onSortChange?: (sort: SortState | null) => void;
  selectable?: boolean;
  selectedKeys?: readonly string[];
  onSelectionChange?: (keys: string[]) => void;
  loading?: boolean;
  /** Number of skeleton rows shown while loading. */
  loadingRows?: number;
  emptyState?: ReactNode;
  toolbar?: ReactNode;
  /** Integrated pagination configuration automatically rendered in the table footer. */
  pagination?: PaginationProps | false;
  /** Bulk actions rendered when one or more rows are selected. */
  bulkActions?: ReactNode | ((selectedKeys: string[]) => ReactNode);
  footer?: ReactNode;
  onRowClick?: (row: T, index: number) => void;
  stickyHeader?: boolean;
  /** Row density scale. @default 'comfortable' */
  density?: 'compact' | 'comfortable' | 'spacious';
  /** Alternate row background striping. @default false */
  striped?: boolean;
  /** Full cell borders. @default false */
  bordered?: boolean;
  /** Highlight row on hover. @default true */
  hoverable?: boolean;
  /** Optional renderer for expandable sub-row panels. */
  expandedRowRender?: (row: T, index: number) => ReactNode;
  /** Controlled array of expanded row keys. */
  expandedKeys?: readonly string[];
  /** Default array of expanded row keys in uncontrolled mode. */
  defaultExpandedKeys?: readonly string[];
  /** Callback fired when expanded row keys change. */
  onExpandedChange?: (keys: string[]) => void;
  className?: string;
  caption?: string;
}

/**
 * Data table with sorting, selection and loading states.
 *
 * Accessibility
 * - `scope="col"` headers, `aria-sort` on the active sortable column.
 * - Sort controls are real buttons inside the header, so they are reachable by
 *   keyboard and announced with their current state.
 * - Row selection uses checkboxes with an accessible name per row, and the
 *   header checkbox reports `aria-checked="mixed"` for partial selection.
 */
export function DataTable<T>({
  columns,
  data,
  rowKey,
  sort = null,
  onSortChange,
  selectable = false,
  selectedKeys,
  onSelectionChange,
  loading = false,
  loadingRows = 5,
  emptyState,
  toolbar,
  footer,
  pagination,
  bulkActions,
  onRowClick,
  stickyHeader = true,
  density = 'comfortable',
  striped = false,
  bordered = false,
  hoverable = true,
  expandedRowRender,
  expandedKeys: controlledExpandedKeys,
  defaultExpandedKeys = [],
  onExpandedChange,
  className,
  caption,
}: DataTableProps<T>) {
  const captionId = useId();
  const allKeys = data.map((row, index) => rowKey(row, index));
  const selected = new Set(selectedKeys ?? []);
  const selectedOnPage = allKeys.filter((key) => selected.has(key));
  const allSelected = allKeys.length > 0 && selectedOnPage.length === allKeys.length;
  const someSelected = selectedOnPage.length > 0 && !allSelected;

  const [internalExpanded, setInternalExpanded] = useState<string[]>(() => [...defaultExpandedKeys]);
  const isExpandedControlled = controlledExpandedKeys !== undefined;
  const currentExpanded = isExpandedControlled ? controlledExpandedKeys : internalExpanded;
  const isExpanded = (key: string) => currentExpanded.includes(key);

  const toggleExpand = (key: string) => {
    const next = isExpanded(key)
      ? currentExpanded.filter((k) => k !== key)
      : [...currentExpanded, key];
    if (!isExpandedControlled) setInternalExpanded(next);
    onExpandedChange?.(next);
  };

  const toggleSort = (columnId: string) => {
    if (!onSortChange) return;
    if (sort?.column !== columnId) onSortChange({ column: columnId, direction: 'asc' });
    else if (sort.direction === 'asc') onSortChange({ column: columnId, direction: 'desc' });
    else onSortChange(null);
  };

  const toggleRow = (key: string) => {
    if (!onSelectionChange) return;
    const next = new Set(selected);
    if (next.has(key)) next.delete(key);
    else next.add(key);
    onSelectionChange(Array.from(next));
  };

  const toggleAll = () => {
    if (!onSelectionChange) return;
    if (allSelected) {
      const next = new Set(selected);
      allKeys.forEach((key) => next.delete(key));
      onSelectionChange(Array.from(next));
    } else {
      const next = new Set(selected);
      allKeys.forEach((key) => next.add(key));
      onSelectionChange(Array.from(next));
    }
  };

  const getHideClass = (column: Column<T>) => {
    if (column.hideBelow === 'mobile' || column.hideBelow === 640) return 'pui-table__hide-mobile';
    if (column.hideBelow === 'tablet' || column.hideBelow === 860) return 'pui-table__hide-tablet';
    return undefined;
  };


  const bulkActionContent =
    selected.size > 0 && bulkActions
      ? typeof bulkActions === 'function'
        ? bulkActions(Array.from(selected))
        : bulkActions
      : null;

  const paginationNode = pagination ? <Pagination {...pagination} /> : null;
  const effectiveFooter =
    footer || paginationNode ? (
      <div className="pui-table-footer" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: '0.75rem' }}>
        <div>{footer}</div>
        {paginationNode}
      </div>
    ) : null;

  const totalCols = columns.length + (selectable ? 1 : 0) + (expandedRowRender ? 1 : 0);

  return (
    <div className={cn('pui-table-wrap', className)}>
      {bulkActionContent ? (
        <div className="pui-table-toolbar" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: 'var(--pui-brand-subtle, #f0fdf4)', padding: '0.625rem 1rem', borderRadius: 'var(--pui-radius-md, 8px)', border: '1px solid var(--pui-brand-base, #16a34a)' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', fontWeight: 600, fontSize: '0.875rem' }}>
            <span>{selected.size} {selected.size === 1 ? 'row' : 'rows'} selected</span>
          </div>
          <div>{bulkActionContent}</div>
        </div>
      ) : toolbar ? (
        <div className="pui-table-toolbar">{toolbar}</div>
      ) : null}

      <table
        className={cn(
          'pui-table',
          `pui-table--${density}`,
          striped && 'pui-table--striped',
          bordered && 'pui-table--bordered',
          (hoverable || onRowClick) && 'pui-table--hover'
        )}
      >
        {caption && (
          <caption id={captionId} className="pui-sr-only">
            {caption}
          </caption>
        )}
        <thead style={stickyHeader ? undefined : { position: 'static' }}>
          <tr>
            {expandedRowRender && (
              <th style={{ width: '2.5rem', paddingInlineEnd: 0 }} aria-label="Expand row column" />
            )}
            {selectable && (
              <th style={{ width: '2.75rem', paddingInlineEnd: 0 }}>
                <Checkbox
                  checked={allSelected}
                  indeterminate={someSelected}
                  onChange={toggleAll}
                  aria-label={allSelected ? 'Deselect all rows' : 'Select all rows'}
                />
              </th>
            )}
            {columns.map((column) => {
              const isSorted = sort?.column === column.id;
              const hideClass = getHideClass(column);
              return (
                <th
                  key={column.id}
                  scope="col"
                  className={cn(hideClass, column.className)}
                  style={{ width: column.width, textAlign: column.align }}
                  aria-sort={
                    isSorted
                      ? sort.direction === 'asc'
                        ? 'ascending'
                        : 'descending'
                      : column.sortable
                        ? 'none'
                        : undefined
                  }
                >
                  {column.sortable ? (
                    <button
                      type="button"
                      className="pui-table__sort"
                      data-dir={isSorted ? sort.direction : undefined}
                      onClick={() => toggleSort(column.id)}
                    >
                      {column.header}
                      {isSorted && sort.direction === 'desc' ? (
                        <ChevronDownIcon />
                      ) : (
                        <ChevronUpIcon />
                      )}
                    </button>
                  ) : (
                    column.header
                  )}
                </th>
              );
            })}
          </tr>
        </thead>

        <tbody>
          {loading ? (
            Array.from({ length: loadingRows }, (_, rowIndex) => (
              <tr key={`skeleton-${rowIndex}`}>
                {expandedRowRender && <td style={{ width: '2.5rem' }} />}
                {selectable && (
                  <td>
                    <Skeleton width={16} height={16} />
                  </td>
                )}
                {columns.map((column) => {
                  const hideClass = getHideClass(column);
                  return (
                    <td key={column.id} className={cn(hideClass, column.className)}>
                      <Skeleton width={column.numeric ? '48%' : '78%'} />
                    </td>
                  );
                })}
              </tr>
            ))
          ) : data.length === 0 ? (
            <tr>
              <td colSpan={totalCols} style={{ padding: 0, border: 'none' }}>
                {emptyState}
              </td>
            </tr>
          ) : (
            data.map((row, index) => {
              const key = rowKey(row, index);
              const isSelected = selected.has(key);
              const isRowExpanded = isExpanded(key);
              return (
                <Fragment key={key}>
                  <tr
                    data-selected={isSelected || undefined}
                    onClick={onRowClick ? () => onRowClick(row, index) : undefined}
                    style={onRowClick ? { cursor: 'pointer' } : undefined}
                  >
                    {expandedRowRender && (
                      <td
                        onClick={(event) => event.stopPropagation()}
                        style={{ width: '2.5rem', paddingInlineEnd: 0 }}
                      >
                        <button
                          type="button"
                          className={cn(
                            'pui-table__expand-btn',
                            isRowExpanded && 'pui-table__expand-btn--open'
                          )}
                          onClick={() => toggleExpand(key)}
                          aria-label={
                            isRowExpanded ? 'Collapse row details' : 'Expand row details'
                          }
                          aria-expanded={isRowExpanded}
                        >
                          <ChevronRightIcon size={14} />
                        </button>
                      </td>
                    )}
                    {selectable && (
                      <td onClick={(event) => event.stopPropagation()}>
                        <Checkbox
                          checked={isSelected}
                          onChange={() => toggleRow(key)}
                          aria-label={`Select row ${index + 1}`}
                        />
                      </td>
                    )}
                    {columns.map((column) => {
                      const hideClass = getHideClass(column);
                      return (
                        <td
                          key={column.id}
                          style={{ textAlign: column.align }}
                          className={cn(
                            column.numeric && 'pui-table__cell--num',
                            hideClass,
                            column.className
                          )}
                        >
                          {column.cell
                            ? column.cell(row, index)
                            : (column.accessor?.(row) as ReactNode)}
                        </td>
                      );
                    })}
                  </tr>
                  {expandedRowRender && isRowExpanded && (
                    <tr className="pui-table__expanded-row">
                      <td colSpan={totalCols}>
                        <div className="pui-table__expanded-content">
                          {expandedRowRender(row, index)}
                        </div>
                      </td>
                    </tr>
                  )}
                </Fragment>
              );
            })
          )}
        </tbody>
      </table>


      {effectiveFooter}

      {loading && (
        <div className="pui-sr-only" role="status">
          <Spinner label="Loading table data" />
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ Pagination */

export interface PaginationProps {
  page: number;
  pageCount?: number;
  total?: number;
  pageSize?: number;
  onPageChange: (page: number) => void;
  siblings?: number;
  size?: 'sm' | 'md' | 'lg';
  simple?: boolean;
  showTotal?: boolean | ((total: number, range: [number, number]) => ReactNode);
  showSizeChanger?: boolean;
  pageSizeOptions?: number[];
  onPageSizeChange?: (pageSize: number) => void;
  className?: string;
}

/**
 * Responsive pagination with ellipsis, total summary, size changer, and simple mode.
 */
export function Pagination({
  page,
  pageCount,
  total,
  pageSize = 10,
  onPageChange,
  siblings = 1,
  size = 'md',
  simple = false,
  showTotal = false,
  showSizeChanger = false,
  pageSizeOptions = [10, 20, 50, 100],
  onPageSizeChange,
  className,
}: PaginationProps) {
  const effectivePageCount = Math.max(1, pageCount ?? (total ? Math.ceil(total / pageSize) : 1));
  const safePage = Math.min(Math.max(1, page), effectivePageCount);
  const startItem = total ? Math.min((safePage - 1) * pageSize + 1, total) : (safePage - 1) * pageSize + 1;
  const endItem = total ? Math.min(safePage * pageSize, total) : safePage * pageSize;

  const totalContent = showTotal ? (
    typeof showTotal === 'function' ? (
      showTotal(total ?? 0, [startItem, endItem])
    ) : (
      <span className="pui-pagination__total">
        {total ? `Showing ${startItem}–${endItem} of ${total}` : `Page ${safePage} of ${effectivePageCount}`}
      </span>
    )
  ) : null;

  const sizeChanger = showSizeChanger ? (
    <select
      className="pui-pagination__size-changer"
      value={pageSize}
      aria-label="Items per page"
      onChange={(e) => onPageSizeChange?.(Number(e.target.value))}
    >
      {pageSizeOptions.map((opt) => (
        <option key={opt} value={opt}>
          {opt} / page
        </option>
      ))}
    </select>
  ) : null;

  if (simple) {
    return (
      <div className={cn('pui-pagination-container', className)}>
        {totalContent}
        <nav className={cn('pui-pagination', `pui-pagination--${size}`)} aria-label="Pagination">
          <button
            type="button"
            className="pui-page-btn"
            disabled={safePage <= 1}
            onClick={() => onPageChange(safePage - 1)}
            aria-label="Previous page"
          >
            ‹
          </button>
          <span className="pui-pagination__simple-text">
            {safePage} / {effectivePageCount}
          </span>
          <button
            type="button"
            className="pui-page-btn"
            disabled={safePage >= effectivePageCount}
            onClick={() => onPageChange(safePage + 1)}
            aria-label="Next page"
          >
            ›
          </button>
        </nav>
        {sizeChanger}
      </div>
    );
  }

  const pages = buildPageRange(safePage, effectivePageCount, siblings);

  return (
    <div className={cn('pui-pagination-container', className)}>
      {totalContent}
      <nav className={cn('pui-pagination', `pui-pagination--${size}`)} aria-label="Pagination">
        <button
          type="button"
          className="pui-page-btn"
          disabled={safePage <= 1}
          onClick={() => onPageChange(safePage - 1)}
          aria-label="Previous page"
        >
          ‹
        </button>

        {pages.map((item, index) =>
          item === 'ellipsis' ? (
            <span key={`gap-${index}`} className="pui-page-ellipsis" aria-hidden="true">
              …
            </span>
          ) : (
            <button
              key={item}
              type="button"
              className="pui-page-btn"
              aria-current={item === safePage ? 'page' : undefined}
              aria-label={`Page ${item}`}
              onClick={() => onPageChange(item)}
            >
              {item}
            </button>
          )
        )}

        <button
          type="button"
          className="pui-page-btn"
          disabled={safePage >= effectivePageCount}
          onClick={() => onPageChange(safePage + 1)}
          aria-label="Next page"
        >
          ›
        </button>
      </nav>
      {sizeChanger}
    </div>
  );
}

function buildPageRange(page: number, pageCount: number, siblings: number): (number | 'ellipsis')[] {
  const totalSlots = siblings * 2 + 5;
  if (pageCount <= totalSlots) {
    return Array.from({ length: pageCount }, (_, index) => index + 1);
  }

  const left = Math.max(page - siblings, 1);
  const right = Math.min(page + siblings, pageCount);
  const showLeftGap = left > 2;
  const showRightGap = right < pageCount - 1;

  const items: (number | 'ellipsis')[] = [1];
  if (showLeftGap) items.push('ellipsis');
  for (let value = left; value <= right; value += 1) {
    if (value !== 1 && value !== pageCount) items.push(value);
  }
  if (showRightGap) items.push('ellipsis');
  items.push(pageCount);
  return items;
}

/**
 * Browser CSV export utility for tabular data.
 * Generates an RFC 4180 UTF-8 encoded CSV file and triggers a client download.
 */
export function exportToCsv<T>(
  columns: readonly Column<T>[],
  data: readonly T[],
  filename = 'table-export.csv'
): void {
  if (typeof window === 'undefined') return;

  const validCols = columns.filter((col) => col.accessor || col.id);
  const header = validCols
    .map((col) => {
      const label = typeof col.header === 'string' ? col.header : col.id;
      return `"${String(label).replace(/"/g, '""')}"`;
    })
    .join(',');

  const rows = data.map((row) =>
    validCols
      .map((col) => {
        let val: unknown = '';
        if (col.accessor) {
          val = col.accessor(row);
        } else if (col.id in (row as Record<string, unknown>)) {
          val = (row as Record<string, unknown>)[col.id];
        }
        const str = val === null || val === undefined ? '' : String(val);
        return `"${str.replace(/"/g, '""')}"`;
      })
      .join(',')
  );

  const csv = '\uFEFF' + [header, ...rows].join('\r\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

import { useState, useId, type ReactNode } from 'react';
import { Popover } from './Popover';
import { Calendar, type CalendarProps } from './Calendar';
import { ChevronDownIcon, XIcon } from './icons';
import { useControllableState } from '../hooks/useControllableState';
import { cn } from '../utils/cn';
import { FieldShell } from './Field';

export interface DatePickerPreset {
  label: string;
  date?: Date | (() => Date);
  range?: [Date, Date] | (() => [Date, Date]);
  getValue?: () => Date;
}

export interface DatePickerProps extends Omit<CalendarProps, 'className' | 'onChange'> {
  label?: ReactNode;
  hint?: ReactNode;
  error?: ReactNode;
  disabled?: boolean;
  id?: string;
  placeholder?: string;
  className?: string;
  format?: (date: Date) => string;
  formatRange?: (start: Date, end: Date) => string;
  presets?: DatePickerPreset[];
  clearable?: boolean;
  size?: 'sm' | 'md' | 'lg';
  onChange?: (date: Date | null) => void;
  onRangeChange?: (range: [Date | null, Date | null]) => void;
}

const defaultFormat = (date: Date) =>
  date.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });

const defaultFormatRange = (start: Date, end: Date) =>
  `${defaultFormat(start)} – ${defaultFormat(end)}`;

/** Calendar inside a Popover, with preset buttons, clearable reset, and text trigger. */
export function DatePicker({
  mode = 'single',
  label,
  hint,
  error,
  disabled = false,
  id: providedId,
  placeholder,
  className,
  format = defaultFormat,
  formatRange = defaultFormatRange,
  value,
  defaultValue = null,
  onChange,
  rangeValue,
  defaultRangeValue = [null, null],
  onRangeChange,
  presets,
  clearable = false,
  size = 'md',
  ...calendarProps
}: DatePickerProps) {
  const generatedId = useId();
  const id = providedId ?? generatedId;

  const [open, setOpen] = useState(false);
  const [selected, setSelected] = useControllableState<Date | null>({
    value,
    defaultValue,
    onChange,
  });

  const [internalRange, setInternalRange] = useState<[Date | null, Date | null]>(() => defaultRangeValue ?? [null, null]);
  const currentRange = rangeValue !== undefined ? rangeValue : internalRange;
  const [rangeStart, rangeEnd] = currentRange;

  const defaultPlaceholder = mode === 'range' ? 'Select date range' : 'Select a date';
  const effectivePlaceholder = placeholder ?? defaultPlaceholder;

  const hasValue = mode === 'range' ? Boolean(rangeStart) : Boolean(selected);

  let labelText = effectivePlaceholder;
  if (mode === 'range') {
    if (rangeStart && rangeEnd) {
      labelText = formatRange(rangeStart, rangeEnd);
    } else if (rangeStart) {
      labelText = `${format(rangeStart)} – …`;
    }
  } else if (selected) {
    labelText = format(selected);
  }

  const handleClear = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (mode === 'range') {
      const resetRange: [Date | null, Date | null] = [null, null];
      if (rangeValue === undefined) setInternalRange(resetRange);
      onRangeChange?.(resetRange);
    } else {
      setSelected(null);
    }
  };

  const pickerPopover = (
    <Popover
      open={!disabled && open}
      onOpenChange={(next) => {
        if (!disabled) setOpen(next);
      }}
      align="start"
      trigger={(props) => (
        <div style={{ position: 'relative', display: 'inline-flex', alignItems: 'center', width: '100%' }}>
          <button
            type="button"
            id={id}
            {...props}
            disabled={disabled}
            className={cn('pui-control', size !== 'md' && `pui-control--${size}`)}
            style={{
              textAlign: 'start',
              display: 'flex',
              alignItems: 'center',
              gap: '0.625rem',
              cursor: disabled ? 'not-allowed' : 'pointer',
              paddingInlineEnd: clearable && hasValue && !disabled ? '2.25rem' : undefined,
              opacity: disabled ? 0.6 : 1,
            }}
          >
            <svg
              width="15"
              height="15"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.75"
              style={{ color: 'var(--pui-fg-subtle)', flexShrink: 0 }}
              aria-hidden="true"
            >
              <rect x="3" y="4" width="18" height="18" rx="2" ry="2" />
              <line x1="16" y1="2" x2="16" y2="6" />
              <line x1="8" y1="2" x2="8" y2="6" />
              <line x1="3" y1="10" x2="21" y2="10" />
            </svg>
            <span style={{ flex: 1, color: hasValue ? undefined : 'var(--pui-fg-subtle)', fontSize: 'inherit' }}>
              {labelText}
            </span>
            <ChevronDownIcon size="0.875rem" />
          </button>
          {clearable && hasValue && !disabled && (
            <button
              type="button"
              aria-label="Clear date"
              onClick={handleClear}
              className="pui-input-clear-btn"
              style={{ position: 'absolute', right: '0.75rem', zIndex: 2 }}
            >
              <XIcon size={12} />
            </button>
          )}
        </div>
      )}
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', padding: '0.25rem' }}>
        {presets && presets.length > 0 && (
          <div
            style={{
              display: 'flex',
              gap: '0.375rem',
              flexWrap: 'wrap',
              paddingBottom: '0.5rem',
              borderBottom: '1px solid var(--pui-border)',
            }}
          >
            {presets.map((preset) => (
              <button
                key={preset.label}
                type="button"
                onClick={() => {
                  const resolvedRange = typeof preset.range === 'function' ? preset.range() : preset.range;
                  const rawDate = preset.date ?? preset.getValue;
                  const resolvedDate = typeof rawDate === 'function' ? rawDate() : rawDate;

                  if (resolvedRange && mode === 'range') {
                    if (rangeValue === undefined) setInternalRange(resolvedRange);
                    onRangeChange?.(resolvedRange);
                    setOpen(false);
                  } else if (resolvedDate) {
                    if (mode === 'range') {
                      const newR: [Date | null, Date | null] = [resolvedDate, resolvedDate];
                      if (rangeValue === undefined) setInternalRange(newR);
                      onRangeChange?.(newR);
                    } else {
                      setSelected(resolvedDate);
                    }
                    setOpen(false);
                  }
                }}
                style={{
                  padding: '0.25rem 0.5rem',
                  fontSize: '0.75rem',
                  fontWeight: 500,
                  borderRadius: 'var(--pui-radius-sm)',
                  background: 'var(--pui-surface-subtle)',
                  border: '1px solid var(--pui-border)',
                  cursor: 'pointer',
                  color: 'var(--pui-fg)',
                }}
              >
                {preset.label}
              </button>
            ))}
          </div>
        )}
        <Calendar
          {...calendarProps}
          mode={mode}
          value={selected}
          rangeValue={currentRange}
          onChange={(date) => {
            setSelected(date);
            setOpen(false);
          }}
          onRangeChange={(newRange) => {
            if (rangeValue === undefined) setInternalRange(newRange);
            onRangeChange?.(newRange);
            if (newRange[0] && newRange[1]) {
              setOpen(false);
            }
          }}
        />
      </div>
    </Popover>
  );

  if (label || hint || error) {
    return (
      <FieldShell
        id={id}
        label={label}
        hint={hint}
        error={error}
        className={className}
      >
        {() => pickerPopover}
      </FieldShell>
    );
  }

  return <div className={className}>{pickerPopover}</div>;
}

'use client';

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useId,
  useState,
  type HTMLAttributes,
  type MouseEvent,
  type ReactNode,
} from 'react';
import { cn } from '../utils/cn';
import { Portal, useScrollLock } from './Portal';
import { useFocusTrap } from '../hooks/useFocusTrap';
import { useDismiss } from '../hooks/useDismiss';
import { Button, IconButton } from './Button';
import { XIcon } from './icons';

type Size = 'sm' | 'md' | 'lg' | 'xl' | 'full';

export interface DialogProps {
  open: boolean;
  onClose: () => void;
  title?: ReactNode;
  description?: ReactNode;
  children?: ReactNode;
  footer?: ReactNode;
  size?: Size;
  /** Clicking the backdrop closes the dialog. Disable for destructive flows. */
  dismissOnBackdrop?: boolean;
  hideCloseButton?: boolean;
  className?: string;
  overlayClassName?: string;
  /** Element inside the dialog to focus first. Falls back to the first focusable. */
  initialFocusRef?: React.RefObject<HTMLElement>;
}

/**
 * Modal dialog following the WAI-ARIA Dialog pattern:
 * focus is trapped, focus returns to the trigger on close, Escape closes,
 * background scroll is locked, and the rest of the page is `aria-hidden`
 * while open.
 */
function DialogRoot({
  open,
  onClose,
  title,
  description,
  children,
  footer,
  size = 'md',
  initialFocusRef,
  dismissOnBackdrop = true,
  hideCloseButton = false,
  className,
  overlayClassName,
}: DialogProps) {
  const dialogId = useId();
  // Held in state, not a ref: <Portal> mounts one commit after this component,
  // so a ref would still be empty when the focus-trap effect runs.
  const [panel, setPanel] = useState<HTMLDivElement | null>(null);

  useScrollLock(open);
  useFocusTrap(panel, open, { initialFocus: initialFocusRef });
  // Escape closes unless the dialog is non-dismissible.
  useDismiss(panel, open && dismissOnBackdrop, onClose, { escape: true, outside: false });

  const onBackdropMouseDown = useCallback(
    (event: MouseEvent<HTMLDivElement>) => {
      // Only close when the press starts *and* ends on the backdrop, so a
      // drag that began inside the panel does not dismiss it.
      if (!dismissOnBackdrop) return;
      if (event.target === event.currentTarget) onClose();
    },
    [dismissOnBackdrop, onClose]
  );

  if (!open) return null;

  const titleId = title ? `pui-dialog-title-${dialogId}` : undefined;
  const descId = description ? `pui-dialog-desc-${dialogId}` : undefined;

  return (
    <Portal>
      <div
        className={cn('pui-overlay', overlayClassName)}
        onMouseDown={onBackdropMouseDown}
        // The overlay itself is not focusable; the panel receives focus.
        aria-hidden="true"
      >
        <div
          ref={setPanel}
          role="dialog"
          aria-modal="true"
          aria-labelledby={titleId}
          aria-describedby={descId}
          className={cn('pui-dialog', `pui-dialog--${size}`, className)}
          onMouseDown={(event) => event.stopPropagation()}
        >
          {(title || description || !hideCloseButton) && (
            <div className="pui-dialog__header">
              <div className="pui-dialog__heading">
                {title && (
                  <h2 id={titleId} className="pui-dialog__title">
                    {title}
                  </h2>
                )}
                {description && (
                  <p id={descId} className="pui-dialog__desc">
                    {description}
                  </p>
                )}
              </div>
              {!hideCloseButton && (
                <IconButton
                  variant="ghost"
                  size="sm"
                  aria-label="Close dialog"
                  className="pui-dialog__close"
                  onClick={onClose}
                >
                  <XIcon />
                </IconButton>
              )}
            </div>
          )}

          {children && <div className="pui-dialog__body">{children}</div>}
          {footer && <div className="pui-dialog__footer">{footer}</div>}
        </div>
      </div>
    </Portal>
  );
}

export interface DrawerProps extends Omit<DialogProps, 'size' | 'overlayClassName'> {
  side?: 'left' | 'right' | 'top' | 'bottom';
  size?: 'sm' | 'md' | 'lg' | 'full';
  handle?: boolean;
}

/** Edge-anchored panel. Same a11y guarantees as Dialog, different motion. */
export function Drawer({
  side = 'right',
  size = 'md',
  handle = side === 'bottom',
  className,
  ...props
}: DrawerProps) {
  const [panel, setPanel] = useState<HTMLDivElement | null>(null);
  useScrollLock(props.open);
  useFocusTrap(panel, props.open);
  useDismiss(panel, props.open && props.dismissOnBackdrop !== false, props.onClose, {
    escape: true,
    outside: false,
  });

  if (!props.open) return null;

  return (
    <Portal>
      <div
        className={cn('pui-overlay', `pui-overlay--drawer-${side}`)}
        onMouseDown={(event) => {
          if (props.dismissOnBackdrop !== false && event.target === event.currentTarget) {
            props.onClose();
          }
        }}
      >
        <div
          ref={setPanel}
          role="dialog"
          aria-modal="true"
          aria-labelledby={props.title ? 'pui-drawer-title' : undefined}
          className={cn('pui-dialog', 'pui-drawer', `pui-drawer--${side}`, `pui-drawer--${size}`, className)}
          onMouseDown={(event) => event.stopPropagation()}
        >
          {handle && side === 'bottom' && (
            <div className="pui-drawer__handle-bar" aria-hidden="true">
              <div className="pui-drawer__handle" />
            </div>
          )}
          {(props.title || !props.hideCloseButton) && (
            <div className="pui-dialog__header">
              <div className="pui-dialog__heading">
                {props.title && (
                  <h2 id="pui-drawer-title" className="pui-dialog__title">
                    {props.title}
                  </h2>
                )}
                {props.description && (
                  <p className="pui-dialog__desc">{props.description}</p>
                )}
              </div>
              {!props.hideCloseButton && (
                <IconButton
                  variant="ghost"
                  size="sm"
                  aria-label="Close panel"
                  className="pui-dialog__close"
                  onClick={props.onClose}
                >
                  <XIcon />
                </IconButton>
              )}
            </div>
          )}
          {props.children && <div className="pui-dialog__body">{props.children}</div>}
          {props.footer && <div className="pui-dialog__footer">{props.footer}</div>}
        </div>
      </div>
    </Portal>
  );
}

/** Convenience: a Dialog wired to a boolean pair, for confirm-style flows. */
export interface ConfirmDialogProps extends Omit<DialogProps, 'title' | 'footer'> {
  title?: ReactNode;
  confirmLabel?: string;
  cancelLabel?: string;
  tone?: 'primary' | 'danger';
  onConfirm: () => void;
  loading?: boolean;
}

export function ConfirmDialog({
  title = 'Are you sure?',
  confirmLabel = 'Confirm',
  cancelLabel = 'Cancel',
  tone = 'primary',
  onConfirm,
  loading,
  ...props
}: ConfirmDialogProps) {
  return (
    <Dialog
      {...props}
      title={title}
      size="sm"
      footer={
        <>
          <Button variant="secondary" size="md" onClick={props.onClose}>
            {cancelLabel}
          </Button>
          <Button
            variant={tone}
            size="md"
            data-autofocus
            onClick={onConfirm}
            loading={loading}
          >
            {confirmLabel}
          </Button>
        </>
      }
    />
  );
}

export function DialogBody(props: HTMLAttributes<HTMLDivElement>) {
  return <div className="pui-dialog__body" {...props} />;
}

/* ---------------------------------------------------------------- Adaptive Dialog */

export interface AdaptiveDialogProps extends DialogProps {
  /** Viewport width in pixels below which the component renders as a bottom drawer. @default 640 */
  breakpoint?: number;
}

/**
 * Responsive modal dialog: renders as a standard centered Dialog on desktop screens,
 * and seamlessly converts into a thumb-friendly bottom Drawer on mobile devices.
 */
export function AdaptiveDialog({
  breakpoint = 640,
  size = 'md',
  ...props
}: AdaptiveDialogProps) {
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const mql = window.matchMedia(`(max-width: ${breakpoint}px)`);
    setIsMobile(mql.matches);

    const handler = (e: MediaQueryListEvent) => setIsMobile(e.matches);
    mql.addEventListener('change', handler);
    return () => mql.removeEventListener('change', handler);
  }, [breakpoint]);

  if (isMobile) {
    return <Drawer side="bottom" size={size === 'xl' ? 'lg' : size} handle {...props} />;
  }

  return <Dialog size={size} {...props} />;
}

/* ---------------------------------------------------------------- useConfirm */

export interface ConfirmOptions {
  title?: ReactNode;
  description?: ReactNode;
  confirmLabel?: string;
  cancelLabel?: string;
  tone?: 'primary' | 'danger';
}

interface ConfirmContextValue {
  confirm: (options: ConfirmOptions) => Promise<boolean>;
}

const ConfirmContext = createContext<ConfirmContextValue | null>(null);

export function ConfirmProvider({ children }: { children: ReactNode }) {
  const [dialogState, setDialogState] = useState<{
    open: boolean;
    options: ConfirmOptions;
    resolve: (value: boolean) => void;
  } | null>(null);

  const confirm = useCallback((options: ConfirmOptions): Promise<boolean> => {
    return new Promise<boolean>((resolve) => {
      setDialogState({
        open: true,
        options,
        resolve,
      });
    });
  }, []);

  const handleClose = useCallback(() => {
    dialogState?.resolve(false);
    setDialogState(null);
  }, [dialogState]);

  const handleConfirm = useCallback(() => {
    dialogState?.resolve(true);
    setDialogState(null);
  }, [dialogState]);

  return (
    <ConfirmContext.Provider value={{ confirm }}>
      {children}
      {dialogState && (
        <ConfirmDialog
          open={dialogState.open}
          onClose={handleClose}
          onConfirm={handleConfirm}
          title={dialogState.options.title}
          tone={dialogState.options.tone}
          confirmLabel={dialogState.options.confirmLabel}
          cancelLabel={dialogState.options.cancelLabel}
        >
          {dialogState.options.description}
        </ConfirmDialog>
      )}
    </ConfirmContext.Provider>
  );
}

export function useConfirm(): (options: ConfirmOptions) => Promise<boolean> {
  const ctx = useContext(ConfirmContext);
  if (!ctx) {
    throw new Error('useConfirm() must be used inside <ConfirmProvider>.');
  }
  return ctx.confirm;
}

export const Dialog = Object.assign(DialogRoot, {
  Body: DialogBody,
  Confirm: ConfirmDialog,
  Adaptive: AdaptiveDialog,
});

import React, { useMemo, type HTMLAttributes } from 'react';
import { cn } from '../utils/cn';

export type DiffViewMode = 'unified' | 'split';

export interface DiffViewerProps extends HTMLAttributes<HTMLDivElement> {
  /** Original base string or code. */
  oldValue: string;
  /** New/modified string or code. */
  newValue: string;
  /** Layout presentation style: 'unified' (single column) or 'split' (side-by-side). Defaults to 'unified'. */
  mode?: DiffViewMode;
  /** Optional title or branch label for old version. */
  oldTitle?: string;
  /** Optional title or branch label for new version. */
  newTitle?: string;
  /** Whether to hide line numbers in the gutter. Defaults to false. */
  hideLineNumbers?: boolean;
}

type DiffType = 'add' | 'delete' | 'normal';

interface DiffLine {
  type: DiffType;
  oldNum?: number;
  newNum?: number;
  content: string;
}

interface SplitRow {
  oldLine?: { num: number; content: string; type: DiffType };
  newLine?: { num: number; content: string; type: DiffType };
}

/**
 * Computes a standard line-by-line diff using Longest Common Subsequence (LCS).
 * Zero runtime dependencies.
 */
function computeDiff(oldText: string, newText: string): DiffLine[] {
  const oldLines = oldText.split('\n');
  const newLines = newText.split('\n');
  const m = oldLines.length;
  const n = newLines.length;

  // Build DP table for LCS
  const dp: number[][] = [];
  for (let idx = 0; idx <= m; idx++) {
    dp[idx] = new Array(n + 1).fill(0);
  }

  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (oldLines[i] === newLines[j]) {
        dp[i + 1]![j + 1] = (dp[i]![j] ?? 0) + 1;
      } else {
        dp[i + 1]![j + 1] = Math.max(dp[i + 1]![j] ?? 0, dp[i]![j + 1] ?? 0);
      }
    }
  }

  // Backtrack to find diff
  const result: DiffLine[] = [];
  let i = m;
  let j = n;

  const stack: DiffLine[] = [];
  let oldNum = m;
  let newNum = n;

  while (i > 0 || j > 0) {
    const oLine = oldLines[i - 1] ?? '';
    const nLine = newLines[j - 1] ?? '';
    const dpLeft = j > 0 && dp[i] ? (dp[i]![j - 1] ?? 0) : 0;
    const dpUp = i > 0 && dp[i - 1] ? (dp[i - 1]![j] ?? 0) : 0;

    if (i > 0 && j > 0 && oLine === nLine) {
      stack.push({
        type: 'normal',
        oldNum: oldNum--,
        newNum: newNum--,
        content: oLine,
      });
      i--;
      j--;
    } else if (j > 0 && (i === 0 || dpLeft >= dpUp)) {
      stack.push({
        type: 'add',
        newNum: newNum--,
        content: nLine,
      });
      j--;
    } else if (i > 0) {
      stack.push({
        type: 'delete',
        oldNum: oldNum--,
        content: oLine,
      });
      i--;
    }
  }

  while (stack.length > 0) {
    result.push(stack.pop()!);
  }

  return result;
}

/**
 * Transforms unified diff lines into aligned side-by-side rows.
 */
function toSplitRows(diffLines: DiffLine[]): SplitRow[] {
  const rows: SplitRow[] = [];
  let i = 0;

  while (i < diffLines.length) {
    const cur = diffLines[i];
    if (!cur) break;

    if (cur.type === 'normal') {
      rows.push({
        oldLine: { num: cur.oldNum ?? 0, content: cur.content, type: 'normal' },
        newLine: { num: cur.newNum ?? 0, content: cur.content, type: 'normal' },
      });
      i++;
    } else {
      // Gather consecutive deletes and adds
      const deletes: DiffLine[] = [];
      const adds: DiffLine[] = [];

      while (i < diffLines.length && diffLines[i]?.type === 'delete') {
        const d = diffLines[i];
        if (d) deletes.push(d);
        i++;
      }
      while (i < diffLines.length && diffLines[i]?.type === 'add') {
        const a = diffLines[i];
        if (a) adds.push(a);
        i++;
      }

      const maxLen = Math.max(deletes.length, adds.length);
      for (let k = 0; k < maxLen; k++) {
        const del = deletes[k];
        const add = adds[k];
        rows.push({
          oldLine: del ? { num: del.oldNum ?? 0, content: del.content, type: 'delete' } : undefined,
          newLine: add ? { num: add.newNum ?? 0, content: add.content, type: 'add' } : undefined,
        });
      }
    }
  }

  return rows;
}

export function DiffViewer({
  oldValue,
  newValue,
  mode = 'unified',
  oldTitle = 'Original',
  newTitle = 'Modified',
  hideLineNumbers = false,
  className,
  style,
  ...rest
}: DiffViewerProps) {
  const diffLines = useMemo(() => computeDiff(oldValue, newValue), [oldValue, newValue]);
  const splitRows = useMemo(() => (mode === 'split' ? toSplitRows(diffLines) : []), [diffLines, mode]);

  const stats = useMemo(() => {
    let additions = 0;
    let deletions = 0;
    for (const line of diffLines) {
      if (line.type === 'add') additions++;
      else if (line.type === 'delete') deletions++;
    }
    return { additions, deletions };
  }, [diffLines]);

  return (
    <div
      className={cn('pui-diff-viewer', className)}
      style={{
        border: '1px solid var(--pui-border, #e2e8f0)',
        borderRadius: 'var(--pui-radius-lg, 8px)',
        overflow: 'hidden',
        background: 'var(--pui-surface, #ffffff)',
        fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace',
        fontSize: '0.8125rem',
        lineHeight: 1.5,
        ...style,
      }}
      {...rest}
    >
      {/* Diff Bar Header */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '0.5rem 0.875rem',
          background: 'var(--pui-surface-subtle, #f8fafc)',
          borderBottom: '1px solid var(--pui-border, #e2e8f0)',
          fontSize: '0.75rem',
          fontWeight: 600,
          color: 'var(--pui-fg-muted, #64748b)',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
          <span>{mode === 'split' ? `${oldTitle} ↔ ${newTitle}` : 'Diff View'}</span>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <span style={{ color: 'var(--pui-success, #10b981)', fontWeight: 700 }}>
            +{stats.additions}
          </span>
          <span style={{ color: 'var(--pui-danger, #ef4444)', fontWeight: 700 }}>
            -{stats.deletions}
          </span>
        </div>
      </div>

      {/* Unified Diff Mode */}
      {mode === 'unified' && (
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
            <tbody>
              {diffLines.map((line, idx) => {
                const isAdd = line.type === 'add';
                const isDel = line.type === 'delete';

                const bg = isAdd
                  ? 'rgba(16, 185, 129, 0.12)'
                  : isDel
                  ? 'rgba(239, 68, 68, 0.12)'
                  : 'transparent';

                const color = isAdd
                  ? 'var(--pui-success, #059669)'
                  : isDel
                  ? 'var(--pui-danger, #dc2626)'
                  : 'inherit';

                const prefix = isAdd ? '+' : isDel ? '-' : ' ';

                return (
                  <tr key={idx} style={{ background: bg }}>
                    {!hideLineNumbers && (
                      <>
                        <td
                          style={{
                            width: '2.5rem',
                            textAlign: 'right',
                            padding: '0 0.5rem',
                            color: 'var(--pui-fg-subtle, #94a3b8)',
                            userSelect: 'none',
                            borderRight: '1px solid var(--pui-border, #f1f5f9)',
                          }}
                        >
                          {line.oldNum || ''}
                        </td>
                        <td
                          style={{
                            width: '2.5rem',
                            textAlign: 'right',
                            padding: '0 0.5rem',
                            color: 'var(--pui-fg-subtle, #94a3b8)',
                            userSelect: 'none',
                            borderRight: '1px solid var(--pui-border, #f1f5f9)',
                          }}
                        >
                          {line.newNum || ''}
                        </td>
                      </>
                    )}
                    <td
                      style={{
                        width: '1.25rem',
                        textAlign: 'center',
                        color,
                        fontWeight: 700,
                        userSelect: 'none',
                      }}
                    >
                      {prefix}
                    </td>
                    <td
                      style={{
                        padding: '0 0.75rem',
                        whiteSpace: 'pre',
                        color: isAdd || isDel ? color : 'var(--pui-fg, #1e293b)',
                      }}
                    >
                      {line.content}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* Split Side-by-Side Mode */}
      {mode === 'split' && (
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', tableLayout: 'fixed' }}>
            <tbody>
              {splitRows.map((row, idx) => {
                const oldBg =
                  row.oldLine?.type === 'delete' ? 'rgba(239, 68, 68, 0.12)' : 'transparent';
                const newBg =
                  row.newLine?.type === 'add' ? 'rgba(16, 185, 129, 0.12)' : 'transparent';

                return (
                  <tr key={idx}>
                    {/* Left side (Old) */}
                    {!hideLineNumbers && (
                      <td
                        style={{
                          width: '2.5rem',
                          textAlign: 'right',
                          padding: '0 0.5rem',
                          color: 'var(--pui-fg-subtle, #94a3b8)',
                          userSelect: 'none',
                          borderRight: '1px solid var(--pui-border, #f1f5f9)',
                          background: oldBg,
                        }}
                      >
                        {row.oldLine?.num || ''}
                      </td>
                    )}
                    <td
                      style={{
                        width: 'calc(50% - 2.5rem)',
                        padding: '0 0.625rem',
                        whiteSpace: 'pre',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        background: oldBg,
                        color:
                          row.oldLine?.type === 'delete'
                            ? 'var(--pui-danger, #dc2626)'
                            : 'var(--pui-fg, #1e293b)',
                        borderRight: '2px solid var(--pui-border, #e2e8f0)',
                      }}
                    >
                      {row.oldLine ? (row.oldLine.type === 'delete' ? '- ' : '  ') + row.oldLine.content : ''}
                    </td>

                    {/* Right side (New) */}
                    {!hideLineNumbers && (
                      <td
                        style={{
                          width: '2.5rem',
                          textAlign: 'right',
                          padding: '0 0.5rem',
                          color: 'var(--pui-fg-subtle, #94a3b8)',
                          userSelect: 'none',
                          borderRight: '1px solid var(--pui-border, #f1f5f9)',
                          background: newBg,
                        }}
                      >
                        {row.newLine?.num || ''}
                      </td>
                    )}
                    <td
                      style={{
                        width: 'calc(50% - 2.5rem)',
                        padding: '0 0.625rem',
                        whiteSpace: 'pre',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        background: newBg,
                        color:
                          row.newLine?.type === 'add'
                            ? 'var(--pui-success, #059669)'
                            : 'var(--pui-fg, #1e293b)',
                      }}
                    >
                      {row.newLine ? (row.newLine.type === 'add' ? '+ ' : '  ') + row.newLine.content : ''}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import {
  forwardRef,
  useRef,
  useState,
  type HTMLAttributes,
  type ReactNode,
  type MouseEvent as ReactMouseEvent,
} from 'react';
import { cn } from '../utils/cn';

export interface DockProps extends HTMLAttributes<HTMLDivElement> {
  /** Maximum icon size on magnification (px). @default 56 */
  magnification?: number;
  /** Distance around cursor to apply magnification (px). @default 120 */
  distance?: number;
  /** Visual variant. @default 'glass' */
  variant?: 'glass' | 'solid' | 'subtle';
  children: ReactNode;
}

/**
 * Dock provides a floating macOS-style action bar with smooth cursor magnification
 * and glassmorphic elevated backdrop.
 */
export const Dock = forwardRef<HTMLDivElement, DockProps>(function Dock(
  {
    magnification = 52,
    distance = 100,
    variant = 'glass',
    className,
    children,
    ...props
  },
  ref
) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const [mouseX, setMouseX] = useState<number | null>(null);

  const handleMouseMove = (e: ReactMouseEvent<HTMLDivElement>) => {
    setMouseX(e.clientX);
  };

  const handleMouseLeave = () => {
    setMouseX(null);
  };

  return (
    <div
      ref={(node) => {
        containerRef.current = node;
        if (typeof ref === 'function') ref(node);
        else if (ref) (ref as any).current = node;
      }}
      role="toolbar"
      aria-label="Floating action dock"
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      className={cn(
        'pui-dock',
        `pui-dock--${variant}`,
        className
      )}
      {...props}
    >
      {children}
    </div>
  );
});

Dock.displayName = 'Dock';

export interface DockIconProps extends HTMLAttributes<HTMLButtonElement> {
  /** Accessible label and tooltip title. */
  label: string;
  /** Whether the dock item is active. */
  active?: boolean;
