      {active && <span className="pui-dock__dot" aria-hidden="true" />}
    </button>
  );
});

DockIcon.displayName = 'DockIcon';

import { useCallback, useEffect, useRef, useState, type DragEvent, type ReactNode } from 'react';
import { cn } from '../utils/cn';

export interface DropzoneFile {
  file: File;
  id: string;
  previewUrl?: string;
  status?: 'idle' | 'uploading' | 'done' | 'error';
  progress?: number;
  error?: string;
}

export interface DropzoneProps {
  accept?: string;
  multiple?: boolean;
  maxFiles?: number;
  maxSize?: number; // bytes
  disabled?: boolean;
  hint?: string;
  files?: DropzoneFile[];
  onFilesChange?: (files: DropzoneFile[]) => void;
  onFiles?: (files: File[]) => void;
  children?: ReactNode;
  className?: string;
  /** Optionally simulate progress for showcase/demo purposes. Defaults to false. */
  simulateProgress?: boolean;
}

function createPreview(file: File): string | undefined {
  if (file.type.startsWith('image/')) {
    try {
      return URL.createObjectURL(file);
    } catch {
      return undefined;
    }
  }
  return undefined;
}

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

export function Dropzone({
  accept,
  multiple = true,
  maxFiles = 10,
  maxSize,
  disabled = false,
  hint,
  files: controlledFiles,
  onFilesChange,
  onFiles,
  children,
  className,
  simulateProgress = false,
}: DropzoneProps) {
  const [internalFiles, setInternalFiles] = useState<DropzoneFile[]>([]);
  const [dragOver, setDragOver] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const timersRef = useRef<number[]>([]);

  useEffect(() => {
    return () => {
      timersRef.current.forEach((t) => window.clearInterval(t));
    };
  }, []);

  const files = controlledFiles ?? internalFiles;

  const addFiles = useCallback(
    (incoming: FileList | File[]) => {
      const arr = Array.from(incoming);
      if (arr.length === 0) return;

      // Validate count
      if (files.length + arr.length > maxFiles) {
        setError(`You can only upload up to ${maxFiles} files`);
        return;
      }

      const next: DropzoneFile[] = [];
      for (const file of arr) {
        if (maxSize && file.size > maxSize) {
          setError(`${file.name} is too large (max ${formatBytes(maxSize)})`);
          continue;
        }
        next.push({
          id: `${file.name}-${file.size}-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
          file,
          previewUrl: createPreview(file),
          status: 'idle',
          progress: 0,
        });
      }

      if (next.length === 0) return;
      setError(null);

      const merged = [...files, ...next];
      if (controlledFiles === undefined) setInternalFiles(merged);
      onFilesChange?.(merged);
      onFiles?.(next.map((f) => f.file));

      if (simulateProgress) {
        next.forEach((item) => {
          let p = 0;
          const iv = window.setInterval(() => {
            p += Math.random() * 18 + 6;
            if (p >= 100) {
              p = 100;
              window.clearInterval(iv);
            }
            const nextStatus: DropzoneFile['status'] = p === 100 ? 'done' : 'uploading';
            const updater = (prev: DropzoneFile[]) =>
              prev.map((f) => (f.id === item.id ? { ...f, progress: p, status: nextStatus } : f));
            if (controlledFiles === undefined) {
              setInternalFiles(updater);
            }
          }, 120);
          timersRef.current.push(iv);
        });
      }
    },
    [files, maxFiles, maxSize, controlledFiles, onFilesChange, onFiles, simulateProgress]
  );

  const onDrop = useCallback(
    (e: DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      if (disabled) return;
      setDragOver(false);
      if (e.dataTransfer.files) addFiles(e.dataTransfer.files);
    },
    [addFiles, disabled]
  );

  const onDragOver = useCallback(
    (e: DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      if (!disabled) setDragOver(true);
    },
    [disabled]
  );

  const onDragLeave = useCallback((e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setDragOver(false);
  }, []);

  const openPicker = useCallback(() => {
    if (!disabled) inputRef.current?.click();
  }, [disabled]);

  const removeFile = useCallback(
    (id: string) => {
      const f = files.find((x) => x.id === id);
      if (f?.previewUrl) URL.revokeObjectURL(f.previewUrl);
      const next = files.filter((x) => x.id !== id);
      if (controlledFiles === undefined) setInternalFiles(next);
      onFilesChange?.(next);
      setError(null);
    },
    [files, controlledFiles, onFilesChange]
  );

  return (
    <div className={cn('pui-dropzone-root', className)}>
      <div
        className={cn(
          'pui-dropzone',
          dragOver && 'pui-dropzone--drag',
          disabled && 'pui-dropzone--disabled',
          error && 'pui-dropzone--error'
        )}
        onDrop={onDrop}
        onDragOver={onDragOver}
        onDragLeave={onDragLeave}
        onClick={openPicker}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            openPicker();
          }
        }}
        role="button"
        tabIndex={disabled ? -1 : 0}
        aria-disabled={disabled}
        aria-label="Upload files"
      >
        <input
          ref={inputRef}
          type="file"
          accept={accept}
          multiple={multiple}
          hidden
          disabled={disabled}
          onChange={(e) => {
            if (e.target.files) addFiles(e.target.files);
            // reset so same file can be picked again
            e.target.value = '';
          }}
        />

        <div className="pui-dropzone__icon">
          <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            <path d="M12 16V4" />
            <path d="M8 8l4-4 4 4" />
            <path d="M4 20h16" />
            <path d="M4 16v2a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-2" opacity="0.35" />
          </svg>
        </div>

        <div className="pui-dropzone__body">
          {children ?? (
            <>
              <div className="pui-dropzone__title">
                Drop files here or <span className="pui-dropzone__action">browse</span>
              </div>
              <div className="pui-dropzone__hint">{hint ?? 'PNG, JPG, PDF up to 5MB'}</div>
            </>
          )}
        </div>

        <div className="pui-dropzone__glow" aria-hidden="true" />
      </div>

      {error && (
        <div className="pui-dropzone__error" role="alert">
          {error}
        </div>
      )}

      {files.length > 0 && (
        <div className="pui-dropzone__list" role="list">
          {files.map((item) => (
            <div key={item.id} className="pui-dropzone__file" role="listitem">
              <div className="pui-dropzone__file-thumb">
                {item.previewUrl ? (
                  <img src={item.previewUrl} alt="" />
                ) : (
                  <span className="pui-dropzone__file-ext">{item.file.name.split('.').pop()?.slice(0, 4).toUpperCase()}</span>
                )}
              </div>
              <div className="pui-dropzone__file-meta">
                <div className="pui-dropzone__file-name">{item.file.name}</div>
                <div className="pui-dropzone__file-sub">
                  {formatBytes(item.file.size)} · {item.status === 'done' ? 'Uploaded' : item.status === 'uploading' ? `${Math.round(item.progress ?? 0)}%` : 'Queued'}
                </div>
                <div className="pui-dropzone__file-bar">
                  <div className="pui-dropzone__file-bar-fill" style={{ width: `${item.progress ?? 0}%` }} />
                </div>
              </div>
              <button type="button" className="pui-dropzone__file-remove" onClick={(e) => { e.stopPropagation(); removeFile(item.id); }} aria-label={`Remove ${item.file.name}`}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6L6 18M6 6l12 12" /></svg>
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { forwardRef, type HTMLAttributes, type ReactNode } from 'react';
import { cn } from '../utils/cn';
import {
  AlertCircleIcon,
  AlertTriangleIcon,
  ArrowDownIcon,
  ArrowUpIcon,
  CheckCircleIcon,
  InfoIcon,
  InboxIcon,
} from './icons';

/* ------------------------------------------------------------------ Spinner */

export interface SpinnerProps extends HTMLAttributes<HTMLSpanElement> {
  size?: 'sm' | 'md' | 'lg';
  label?: string;
}

export const Spinner = forwardRef<HTMLSpanElement, SpinnerProps>(function Spinner(
  { size = 'md', label = 'Loading', className, ...props },
  ref
) {
  return (
    <span ref={ref} className={cn('pui-spinner', size !== 'md' && `pui-spinner--${size}`, className)} role="status" aria-label={label} {...props} />
  );
});

export function LoadingRow({ label = 'Loading…' }: { label?: string }) {
  return (
    <div className="pui-loading-row" role="status">
      <Spinner />
      {label}
    </div>
  );
}

/* ------------------------------------------------------------------ Alert */

export type AlertTone = 'info' | 'success' | 'warning' | 'danger' | 'neutral';
export type AlertVariant = 'subtle' | 'solid' | 'outline' | 'accent' | 'glass';

export interface AlertProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  tone?: AlertTone;
  variant?: AlertVariant;
  title?: ReactNode;
  icon?: ReactNode | false;
  action?: ReactNode;
  secondaryAction?: ReactNode;
  /** Renders a dismiss button. */
  onDismiss?: () => void;
}

const ALERT_ICONS: Record<AlertTone, typeof InfoIcon> = {
  info: InfoIcon,
  success: CheckCircleIcon,
  warning: AlertTriangleIcon,
  danger: AlertCircleIcon,
  neutral: InfoIcon,
};

/**
 * `role="status"` for informational tones, `role="alert"` for danger/warning so
 * those interrupt the screen reader. Assertive announcements on every alert
 * would be hostile to assistive-tech users.
 */
export function Alert({
  tone = 'info',
  variant = 'subtle',
  title,
  icon,
  action,
  secondaryAction,
  onDismiss,
  children,
  className,
  ...props
}: AlertProps) {
  const IconComponent = ALERT_ICONS[tone] ?? InfoIcon;
  const assertive = tone === 'danger' || tone === 'warning';
  const renderIcon = icon !== false;

  return (
    <div
      role={assertive ? 'alert' : 'status'}
      className={cn(
        'pui-alert',
        `pui-alert--${tone}`,
        variant !== 'subtle' && `pui-alert--${variant}`,
        className
      )}
      {...props}
    >
      {renderIcon && (
        <span className="pui-alert__icon">
          {icon ?? <IconComponent />}
        </span>
      )}
      <div className="pui-alert__body">
        {title && <div className="pui-alert__title">{title}</div>}
        {children && <div className="pui-alert__desc">{children}</div>}
        {(action || secondaryAction) && (
          <div className="pui-alert__actions">
            {action}
            {secondaryAction}
          </div>
        )}
      </div>
      {onDismiss && (
        <button
          type="button"
          aria-label="Dismiss"
          onClick={onDismiss}
          className="pui-alert__dismiss"
        >
          <span aria-hidden="true" style={{ fontSize: '1.25rem', lineHeight: 1 }}>
            ×
          </span>
        </button>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ EmptyState */

export interface EmptyStateProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  icon?: ReactNode;
  title: ReactNode;
  description?: ReactNode;
  action?: ReactNode;
  secondaryAction?: ReactNode;
  /** Removes the dashed border and background for inline use. */
  plain?: boolean;
}

export function EmptyState({
  icon,
  title,
  description,
  action,
  secondaryAction,
  plain = false,
  className,
  ...props
}: EmptyStateProps) {
  return (
    <div className={cn('pui-empty', plain && 'pui-empty--plain', className)} {...props}>
      <span className="pui-empty__icon">{icon ?? <InboxIcon />}</span>
      <h3 className="pui-empty__title">{title}</h3>
      {description && <p className="pui-empty__desc">{description}</p>}
      {(action || secondaryAction) && (
        <div className="pui-empty__actions">
          {action}
          {secondaryAction}
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ Progress */

export interface ProgressSegment {
  value: number;
  tone?: 'primary' | 'success' | 'warning' | 'danger' | 'info';
  label?: string;
}

export interface ProgressProps extends HTMLAttributes<HTMLDivElement> {
  value?: number;
  max?: number;
  tone?: 'primary' | 'success' | 'warning' | 'danger' | 'info' | 'gradient';
  size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
  striped?: boolean;
  animated?: boolean;
  showValue?: boolean;
  segments?: ProgressSegment[];
  /** Unknown duration — animates a sweeping bar instead of a fixed width. */
  indeterminate?: boolean;
  label?: string;
}

export function Progress({
  value = 0,
  max = 100,
  tone = 'primary',
  size = 'md',
  striped = false,
  animated = false,
  showValue = false,
  segments,
  indeterminate = false,
  label,
  className,
  ...props
}: ProgressProps) {
  const pct = max <= 0 ? 0 : Math.min(100, Math.max(0, (value / max) * 100));

  const progressNode = (
    <div
      role="progressbar"
      aria-valuemin={0}
      aria-valuemax={indeterminate ? undefined : max}
      aria-valuenow={indeterminate ? undefined : value}
      aria-label={label}
      className={cn(
        'pui-progress',
        `pui-progress--${size}`,
        tone !== 'primary' && `pui-progress--${tone}`,
        striped && 'pui-progress--striped',
        animated && 'pui-progress--animated',
        indeterminate && 'pui-progress--indeterminate',
        className
      )}
      {...props}
    >
      {segments && segments.length > 0 ? (
        segments.map((seg, i) => {
          const segPct = max <= 0 ? 0 : Math.min(100, (seg.value / max) * 100);
          return (
            <div
              key={i}
              className={cn(
                'pui-progress__segment',
                `pui-progress__segment--${seg.tone ?? 'primary'}`
              )}
              style={{ width: `${segPct}%` }}
              title={seg.label ? `${seg.label}: ${seg.value}` : undefined}
            />
          );
        })
      ) : (
        <div
          className="pui-progress__bar"
          style={indeterminate ? undefined : { width: `${pct}%` }}
        />
      )}
    </div>
  );

  if (showValue || label) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.375rem', width: '100%' }}>
        {(label || showValue) && (
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '0.8125rem' }}>
            {label && <span style={{ fontWeight: 500, color: 'var(--pui-fg)' }}>{label}</span>}
            {showValue && !indeterminate && (
              <span style={{ fontWeight: 600, color: 'var(--pui-fg-subtle)', marginInlineStart: 'auto' }}>
                {Math.round(pct)}%
              </span>
            )}
          </div>
        )}
        {progressNode}
      </div>
    );
  }

  return progressNode;
}

/* ------------------------------------------------------------------ Stat */

export interface StatProps extends HTMLAttributes<HTMLDivElement> {
  label: ReactNode;
  value: ReactNode;
  /** Percentage change. Sign is inferred from the number. */
  delta?: number;
  /** Overrides the auto up/down icon and wording. */
  deltaLabel?: ReactNode;
  /** Rendered under the value — typically a small sparkline. */
  children?: ReactNode;
  size?: 'sm' | 'md' | 'lg';
}

export function Stat({ label, value, delta, deltaLabel, children, size = 'md', className, ...props }: StatProps) {
  const direction = delta === undefined ? 'flat' : delta > 0 ? 'up' : delta < 0 ? 'down' : 'flat';
  const IconComponent = direction === 'up' ? ArrowUpIcon : ArrowDownIcon;

  return (
    <div className={cn('pui-stat', className)} {...props}>
      <div className="pui-stat__label">{label}</div>
      <div
        className="pui-stat__value"
        style={size === 'sm' ? { fontSize: 'var(--pui-text-2xl)' } : size === 'lg' ? { fontSize: 'var(--pui-text-4xl)' } : undefined}
      >
        {value}
      </div>
      {delta !== undefined && (
        <div className={cn('pui-stat__delta', `pui-stat__delta--${direction}`)}>
          <IconComponent />
          {deltaLabel ?? `${Math.abs(delta).toFixed(1)}%`}
          <span style={{ color: 'var(--pui-fg-subtle)', fontWeight: 400 }}>vs last month</span>
        </div>
      )}
      {deltaLabel && delta === undefined && (
        <div className="pui-stat__delta pui-stat__delta--flat">{deltaLabel}</div>
      )}
      {children && <div className="pui-stat__spark">{children}</div>}
    </div>
  );
}

/* ------------------------------------------------------------------ Kbd */

export interface KbdProps extends HTMLAttributes<HTMLElement> {
  size?: 'sm' | 'md' | 'lg';
  /** Shortcut string like "mod+k", "ctrl+shift+p" */
  shortcut?: string;
  children?: ReactNode;
}

export function Kbd({ size = 'md', shortcut, children, className, ...props }: KbdProps) {
  if (shortcut) {
    const isMac = typeof navigator !== 'undefined' && /Mac|iPod|iPhone|iPad/.test(navigator.platform || '');
    const keys = shortcut.split('+').map((k) => k.trim());
    return (
      <span className="pui-kbd-group" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem' }}>
        {keys.map((key, i) => {
          let label = key;
          const lower = key.toLowerCase();
          if (lower === 'mod' || lower === 'meta' || lower === 'cmd' || lower === 'command') {
            label = isMac ? '⌘' : 'Ctrl';
          } else if (lower === 'shift') {
            label = isMac ? '⇧' : 'Shift';
          } else if (lower === 'alt' || lower === 'option') {
            label = isMac ? '⌥' : 'Alt';
          } else if (lower === 'ctrl' || lower === 'control') {
            label = isMac ? '⌃' : 'Ctrl';
          } else if (lower === 'enter') {
            label = '↵';
          } else {
            label = key.toUpperCase();
          }

          return (
            <kbd
              key={i}
              className={cn(
                'pui-kbd',
                size === 'sm' && 'pui-kbd--sm',
                size === 'lg' && 'pui-kbd--lg',
                className
              )}
              {...props}
            >
              {label}
            </kbd>
          );
        })}
      </span>
    );
  }

  return (
    <kbd
      className={cn(
        'pui-kbd',
        size === 'sm' && 'pui-kbd--sm',
        size === 'lg' && 'pui-kbd--lg',
        className
      )}
      {...props}
    >
      {children}
    </kbd>
  );
}

import {
  forwardRef,
  useId,
  useState,
  type InputHTMLAttributes,
  type ReactNode,
  type SelectHTMLAttributes,
  type TextareaHTMLAttributes,
} from 'react';
import { cn } from '../utils/cn';
import { AlertCircleIcon } from './icons';

/* ------------------------------------------------------------------ Field shell
   Shared label / hint / error plumbing so every control announces itself the
   same way to assistive tech. */

interface FieldShellProps {
  id: string;
  label?: ReactNode;
  hint?: ReactNode;
  error?: ReactNode;
  required?: boolean;
  optionalText?: string;
  className?: string;
  /**
   * Receives the `aria-describedby` value so the control can carry it.
   * Descriptions are only announced when they sit on the control itself —
   * putting them on a wrapper element is a silent no-op.
   */
  children: ReactNode | ((describedBy: string | undefined) => ReactNode);
}

export function FieldShell({
  id,
  label,
  hint,
  error,
  required,
  optionalText,
  className,
  children,
}: FieldShellProps) {
  const describedBy =
    [error ? `${id}-error` : null, hint ? `${id}-hint` : null].filter(Boolean).join(' ') ||
    undefined;

  const content = typeof children === 'function' ? children(describedBy) : children;

  return (
    <div className={cn('pui-field', className)} data-invalid={error ? '' : undefined}>
      {label && (
        <label htmlFor={id} className="pui-label">
          {label}
          {required ? (
            <>
              <span className="pui-label__req" aria-hidden="true">
                *
              </span>
              <span className="pui-sr-only">(required)</span>
            </>
          ) : (
            optionalText && <span className="pui-label__opt">{optionalText}</span>
          )}
        </label>
      )}
      {content}
      {error ? (
        <p id={`${id}-error`} className="pui-error" role="alert">
          <AlertCircleIcon />
          {error}
        </p>
      ) : (
        hint && (
          <p id={`${id}-hint`} className="pui-hint">
            {hint}
          </p>
        )
      )}
    </div>
  );
}

export interface FieldBaseProps {
  label?: ReactNode;
  hint?: ReactNode;
  error?: ReactNode;
  optionalText?: string;
  className?: string;
  containerClassName?: string;
}

/* ------------------------------------------------------------------ Input */

export interface InputProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'size' | 'className'>,
    FieldBaseProps {
  size?: 'sm' | 'md' | 'lg';
  leftAddon?: ReactNode;
  rightAddon?: ReactNode;
  clearable?: boolean;
  onClear?: () => void;
}

export const Input = forwardRef<HTMLInputElement, InputProps>(function Input(
  {
    label,
    hint,
    error,
    optionalText,
    className,
    containerClassName,
    leftAddon,
    rightAddon,
    clearable = false,
    onClear,
    size = 'md',
    required,
    id: providedId,
    value,
    ...props
  },
  ref
) {
  const generated = useId();
  const id = providedId ?? generated;
  const showClear = clearable && Boolean(value);

  const renderControl = (describedBy?: string) => (
    <input
      ref={ref}
      id={id}
      required={required}
      aria-invalid={error ? true : undefined}
      aria-describedby={describedBy}
      value={value}
      className={cn('pui-control', size !== 'md' && `pui-control--${size}`, className)}
      {...props}
    />
  );

  const shell = (describedBy?: string) =>
    leftAddon || rightAddon || showClear ? (
      <div
        className={cn(
          'pui-input-wrap',
          leftAddon && 'pui-input-wrap--start',
          (rightAddon || showClear) && 'pui-input-wrap--end',
          size !== 'md' && `pui-input-wrap--${size}`
        )}
      >
        {leftAddon && <span className="pui-affix pui-affix--start">{leftAddon}</span>}
        {renderControl(describedBy)}
        {showClear && (
          <button
            type="button"
            aria-label="Clear input"
            onClick={onClear}
            className="pui-input-clear-btn"
          >
            ×
          </button>
        )}
        {rightAddon && <span className="pui-affix pui-affix--end">{rightAddon}</span>}
      </div>
    ) : (
      renderControl(describedBy)
    );

  return (
    <FieldShell
      id={id}
      label={label}
      hint={hint}
      error={error}
      required={required}
      optionalText={optionalText}
      className={containerClassName}
    >
      {(describedBy) => shell(describedBy)}
    </FieldShell>
  );
});

/* ------------------------------------------------------------------ Textarea */

export interface TextareaProps
  extends Omit<TextareaHTMLAttributes<HTMLTextAreaElement>, 'className' | 'size'>,
    FieldBaseProps {
  rows?: number;
  size?: 'sm' | 'md' | 'lg';
  showCount?: boolean;
  maxLength?: number;
}

export const Textarea = forwardRef<HTMLTextAreaElement, TextareaProps>(function Textarea(
  {
    label,
    hint,
    error,
    optionalText,
    className,
    containerClassName,
    required,
    id: providedId,
    rows = 4,
    size = 'md',
    showCount = false,
    maxLength,
    value,
    defaultValue,
    onChange,
    ...props
  },
  ref
) {
  const generated = useId();
  const id = providedId ?? generated;
  const [internalVal, setInternalVal] = useState<string>(() => String(value ?? defaultValue ?? ''));

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setInternalVal(e.target.value);
    onChange?.(e);
  };

  const currentLength = value !== undefined ? String(value).length : internalVal.length;
  const limitState = maxLength
    ? currentLength > maxLength
      ? 'exceeded'
      : currentLength >= maxLength * 0.9
        ? 'warning'
        : 'normal'
    : 'normal';

  return (
    <FieldShell
      id={id}
      label={label}
      hint={hint}
      error={error}
      required={required}
      optionalText={optionalText}
      className={containerClassName}
    >
      {(describedBy) => (
        <div className="pui-textarea-wrap">
          <textarea
            ref={ref}
            id={id}
            rows={rows}
            required={required}
            maxLength={maxLength}
            value={value}
            defaultValue={defaultValue}
            onChange={handleChange}
            aria-invalid={error ? true : undefined}
            aria-describedby={describedBy}
            className={cn('pui-control', size !== 'md' && `pui-control--${size}`, className)}
            {...props}
          />
          {showCount && (
            <div
              className="pui-textarea-count"
              data-limit={limitState}
              aria-live="polite"
            >
              {currentLength} {maxLength ? `/ ${maxLength}` : 'chars'}
            </div>
          )}
        </div>
      )}
    </FieldShell>
  );
});

/* ------------------------------------------------------------------ Select */

export interface SelectOption {
  value: string;
  label: string;
  disabled?: boolean;
  group?: string;
}

export interface SelectProps
  extends Omit<SelectHTMLAttributes<HTMLSelectElement>, 'className' | 'children' | 'size'>,
    FieldBaseProps {
  options: readonly SelectOption[];
  placeholder?: string;
  size?: 'sm' | 'md' | 'lg';
}

/**
 * Native `<select>`.
 *
 * Deliberately not a custom listbox: the native element gets free platform
 * behaviour on iOS/Android, typeahead, and screen-reader semantics. Reach for
 * <Combobox /> only when you need search or async loading.
 */
export const Select = forwardRef<HTMLSelectElement, SelectProps>(function Select(
  {
    label,
    hint,
    error,
    optionalText,
    className,
    containerClassName,
    options,
    placeholder,
    size = 'md',
    required,
    id: providedId,
    ...props
  },
  ref
) {
  const generated = useId();
  const id = providedId ?? generated;

  // Group options if any option specifies a `group`
  const hasGroups = options.some((opt) => opt.group);
  const grouped = hasGroups
    ? options.reduce<Record<string, SelectOption[]>>((acc, opt) => {
        const grp = opt.group ?? 'Other';
        if (!acc[grp]) acc[grp] = [];
        acc[grp].push(opt);
        return acc;
      }, {})
    : null;

  return (
    <FieldShell
      id={id}
      label={label}
      hint={hint}
      error={error}
      required={required}
      optionalText={optionalText}
      className={containerClassName}
    >
      {(describedBy) => (
        <select
          ref={ref}
          id={id}
          required={required}
          aria-invalid={error ? true : undefined}
          aria-describedby={describedBy}
          className={cn('pui-control', size !== 'md' && `pui-control--${size}`, className)}
          {...props}
        >
          {placeholder && (
            <option value="" disabled>
              {placeholder}
            </option>
          )}
          {grouped
            ? Object.entries(grouped).map(([groupName, groupOptions]) => (
                <optgroup key={groupName} label={groupName}>
                  {groupOptions.map((option) => (
                    <option key={option.value} value={option.value} disabled={option.disabled}>
                      {option.label}
                    </option>
                  ))}
                </optgroup>
              ))
            : options.map((option) => (
                <option key={option.value} value={option.value} disabled={option.disabled}>
                  {option.label}
                </option>
              ))}
        </select>
      )}
    </FieldShell>
  );
});

'use client';

import {
  createContext,
  forwardRef,
  useContext,
  useId,
  useRef,
  type FormHTMLAttributes,
  type HTMLAttributes,
  type LabelHTMLAttributes,
  type ReactElement,
  type ReactNode,
  cloneElement,
  isValidElement,
} from 'react';
import { cn } from '../utils/cn';
import { AlertCircleIcon } from './icons';

/* ---------------------------------------------------------------- Contexts */

export interface FormFieldContextValue {
  name: string;
  id: string;
  errorId: string;
  descriptionId: string;
  error?: ReactNode;
  hint?: ReactNode;
}

const FormFieldContext = createContext<FormFieldContextValue | null>(null);

export function useFormField(): FormFieldContextValue {
  const ctx = useContext(FormFieldContext);
  const fallbackId = useId();
  if (!ctx) {
    return {
      name: '',
      id: `pui-field-${fallbackId}`,
      errorId: `pui-field-${fallbackId}-error`,
      descriptionId: `pui-field-${fallbackId}-hint`,
      error: undefined,
      hint: undefined,
    };
  }
  return ctx;
}

/* ---------------------------------------------------------------- Form */

export interface FormProps extends FormHTMLAttributes<HTMLFormElement> {
  /** Automatically focus the first invalid field when form submission fails. @default true */
  autoFocusError?: boolean;
}

const FormRoot = forwardRef<HTMLFormElement, FormProps>(function Form(
  { autoFocusError = true, onSubmit, className, children, ...props },
  ref
) {
  const localRef = useRef<HTMLFormElement | null>(null);

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    if (onSubmit) {
      onSubmit(e);
    }
    if (autoFocusError && e.isDefaultPrevented()) {
      const formEl = localRef.current;
      if (formEl) {
        const invalidEl = formEl.querySelector<HTMLElement>(
          '[aria-invalid="true"], :invalid, [data-invalid]'
        );
        invalidEl?.focus();
      }
    }
  };

  return (
    <form
      ref={(node) => {
        localRef.current = node;
        if (typeof ref === 'function') ref(node);
        else if (ref) (ref as React.MutableRefObject<HTMLFormElement | null>).current = node;
      }}
      className={cn('pui-form', className)}
      onSubmit={handleSubmit}
      {...props}
    >
      {children}
    </form>
  );
});

/* ---------------------------------------------------------------- FormField */

export interface FormFieldRenderProps {
  field: {
    name: string;
    id: string;
    'aria-describedby': string;
    'aria-invalid': boolean;
  };
  fieldState: {
    invalid: boolean;
    error?: ReactNode;
  };
}

export interface FormFieldProps {
  name: string;
  error?: ReactNode;
  hint?: ReactNode;
  children?: ReactNode | ((props: FormFieldRenderProps) => ReactNode);
  render?: (props: FormFieldRenderProps) => ReactNode;
}

export function FormField({ name, error, hint, children, render }: FormFieldProps) {
  const generatedId = useId();
  const id = `pui-field-${name}-${generatedId}`;
  const errorId = `${id}-error`;
  const descriptionId = `${id}-hint`;

  const contextValue: FormFieldContextValue = {
    name,
    id,
    errorId,
    descriptionId,
    error,
    hint,
  };

  const describedBy = [error ? errorId : null, hint ? descriptionId : null]
    .filter(Boolean)
    .join(' ');

  const renderProps: FormFieldRenderProps = {
    field: {
      name,
      id,
      'aria-describedby': describedBy,
      'aria-invalid': Boolean(error),
    },
    fieldState: {
      invalid: Boolean(error),
      error,
    },
  };

  return (
    <FormFieldContext.Provider value={contextValue}>
      {render
        ? render(renderProps)
        : typeof children === 'function'
        ? children(renderProps)
        : children}
    </FormFieldContext.Provider>
  );
}

/* ---------------------------------------------------------------- FormItem */

export interface FormItemProps extends HTMLAttributes<HTMLDivElement> {
  error?: ReactNode;
}

export const FormItem = forwardRef<HTMLDivElement, FormItemProps>(function FormItem(
  { error, className, children, ...props },
  ref
) {
  const field = useContext(FormFieldContext);
  const isInvalid = Boolean(error !== undefined ? error : field?.error);

  return (
    <div
      ref={ref}
      className={cn('pui-field', className)}
      data-invalid={isInvalid ? '' : undefined}
      {...props}
    >
      {children}
    </div>
  );
});

/* ---------------------------------------------------------------- FormLabel */

export interface FormLabelProps extends LabelHTMLAttributes<HTMLLabelElement> {
  required?: boolean;
}

export const FormLabel = forwardRef<HTMLLabelElement, FormLabelProps>(function FormLabel(
  { required, className, children, htmlFor, ...props },
  ref
) {
  const { id } = useFormField();

  return (
    <label
      ref={ref}
      htmlFor={htmlFor ?? id}
      className={cn('pui-label', className)}
      {...props}
    >
      {children}
      {required && (
        <>
          <span className="pui-label__req" aria-hidden="true">
            *
          </span>
          <span className="pui-sr-only">(required)</span>
        </>
      )}
    </label>
  );
});

/* ---------------------------------------------------------------- FormControl */

export interface FormControlProps {
  children: ReactElement<any>;
}

export function FormControl({ children }: FormControlProps) {
  const { id, errorId, descriptionId, error } = useFormField();

  if (!isValidElement(children)) return children;

  const child = children as ReactElement<any>;
  const existingDescribedBy = child.props['aria-describedby'];
  const describedBy = [existingDescribedBy, error ? errorId : null, descriptionId]
    .filter(Boolean)
    .join(' ');

  const isInvalid = Boolean(error) || child.props['aria-invalid'] === true || child.props['aria-invalid'] === 'true' || Boolean(child.props.invalid);

  return cloneElement(child, {
    id: child.props.id ?? id,
    'aria-describedby': describedBy || undefined,
    'aria-invalid': isInvalid ? true : undefined,
    invalid: isInvalid ? true : child.props.invalid,
  });
}

/* ---------------------------------------------------------------- FormDescription */

export const FormDescription = forwardRef<
  HTMLParagraphElement,
  HTMLAttributes<HTMLParagraphElement>
>(function FormDescription({ className, children, id: providedId, ...props }, ref) {
  const { descriptionId } = useFormField();

  return (
    <p
      ref={ref}
      id={providedId ?? descriptionId}
      className={cn('pui-hint', className)}
      {...props}
    >
      {children}
    </p>
  );
});

/* ---------------------------------------------------------------- FormMessage */

export interface FormMessageProps extends HTMLAttributes<HTMLParagraphElement> {
  error?: ReactNode;
}

export const FormMessage = forwardRef<HTMLParagraphElement, FormMessageProps>(
  function FormMessage({ error, className, children, id: providedId, ...props }, ref) {
    const field = useContext(FormFieldContext);
    const content = error ?? children ?? field?.error;

    if (!content) return null;

    return (
      <p
        ref={ref}
        id={providedId ?? field?.errorId}
        role="alert"
        className={cn('pui-error', className)}
        {...props}
      >
        <AlertCircleIcon />
        <span>{content}</span>
      </p>
    );
  }
);

/* ---------------------------------------------------------------- Compound Export */

export const Form = Object.assign(FormRoot, {
  Field: FormField,
  Item: FormItem,
  Label: FormLabel,
  Control: FormControl,
  Description: FormDescription,
  Message: FormMessage,
});

import React, { forwardRef, type ReactNode, type HTMLAttributes } from 'react';
import { cn } from '../utils/cn';

export interface GaugeProps extends HTMLAttributes<HTMLDivElement> {
  value: number;
  min?: number;
  max?: number;
  type?: 'circle' | 'semicircle' | 'arc';
  size?: number;
  strokeWidth?: number;
  tone?: 'primary' | 'success' | 'warning' | 'danger' | 'gradient';
  showValue?: boolean;
  valueFormatter?: (val: number) => ReactNode;
  label?: ReactNode;
  sublabel?: ReactNode;
  roundedCaps?: boolean;
}

export const Gauge = forwardRef<HTMLDivElement, GaugeProps>(function Gauge(
  {
    value,
    min = 0,
    max = 100,
    type = 'circle',
    size = 140,
    strokeWidth = 12,
    tone = 'primary',
    showValue = true,
    valueFormatter,
    label,
    sublabel,
    roundedCaps = true,
    className,
    ...props
  },
  ref
) {
  const clampedValue = Math.min(Math.max(value, min), max);
  const percentage = (clampedValue - min) / (max - min || 1);

  const radius = (size - strokeWidth) / 2;
  const center = size / 2;

  let totalAngle = 360;
  let startAngle = -90;
  let height = size;

  if (type === 'semicircle') {
    totalAngle = 180;
    startAngle = 180;
    height = size / 2 + strokeWidth;
  } else if (type === 'arc') {
    totalAngle = 240;
    startAngle = 150;
    height = size * 0.88;
  }

  const circumference = 2 * Math.PI * radius;
  const arcLength = (totalAngle / 360) * circumference;
  const dashoffset = arcLength * (1 - percentage);

  // Convert polar coordinates to Cartesian for SVG arc path
  const polarToCartesian = (cx: number, cy: number, r: number, angleInDegrees: number) => {
    const angleInRadians = ((angleInDegrees - 90) * Math.PI) / 180.0;
    return {
      x: cx + r * Math.cos(angleInRadians),
      y: cy + r * Math.sin(angleInRadians),
    };
  };

  const describeArc = (x: number, y: number, r: number, startA: number, endA: number) => {
    const start = polarToCartesian(x, y, r, endA);
    const end = polarToCartesian(x, y, r, startA);
    const largeArcFlag = endA - startA <= 180 ? '0' : '1';
    return ['M', start.x, start.y, 'A', r, r, 0, largeArcFlag, 0, end.x, end.y].join(' ');
  };

  const isFullCircle = type === 'circle';
  const trackPath = isFullCircle
    ? undefined
    : describeArc(center, center, radius, startAngle, startAngle + totalAngle);

  const formattedValue = valueFormatter
    ? valueFormatter(clampedValue)
    : `${Math.round(clampedValue)}${max === 100 && min === 0 ? '%' : ''}`;

  return (
    <div
      ref={ref}
      role="meter"
      aria-valuenow={clampedValue}
      aria-valuemin={min}
      aria-valuemax={max}
      className={cn('hesh-gauge', `hesh-gauge--${type}`, `hesh-gauge--${tone}`, className)}
      style={{ width: size, height }}
      {...props}
    >
      <svg
        width={size}
        height={height}
        viewBox={`0 0 ${size} ${height}`}
        className="hesh-gauge__svg"
      >
        <defs>
          <linearGradient id={`hesh-gauge-grad-${tone}`} x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="var(--hesh-primary, #6366f1)" />
            <stop offset="100%" stopColor="var(--hesh-accent, #ec4899)" />
          </linearGradient>
        </defs>

        {isFullCircle ? (
          <>
            <circle
              cx={center}
              cy={center}
              r={radius}
              fill="none"
              stroke="var(--hesh-surface-subtle, rgba(255,255,255,0.08))"
              strokeWidth={strokeWidth}
            />
            <circle
              cx={center}
              cy={center}
              r={radius}
              fill="none"
              stroke={tone === 'gradient' ? `url(#hesh-gauge-grad-${tone})` : 'currentColor'}
              strokeWidth={strokeWidth}
              strokeDasharray={circumference}
              strokeDashoffset={circumference * (1 - percentage)}
              strokeLinecap={roundedCaps ? 'round' : 'butt'}
              transform={`rotate(-90 ${center} ${center})`}
              className="hesh-gauge__arc"
            />
          </>
        ) : (
          <>
            <path
              d={trackPath}
              fill="none"
              stroke="var(--hesh-surface-subtle, rgba(255,255,255,0.08))"
              strokeWidth={strokeWidth}
              strokeLinecap={roundedCaps ? 'round' : 'butt'}
            />
            <path
              d={trackPath}
              fill="none"
              stroke={tone === 'gradient' ? `url(#hesh-gauge-grad-${tone})` : 'currentColor'}
              strokeWidth={strokeWidth}
              strokeDasharray={arcLength}
              strokeDashoffset={dashoffset}
              strokeLinecap={roundedCaps ? 'round' : 'butt'}
              className="hesh-gauge__arc"
            />
          </>
        )}
      </svg>

      <div className="hesh-gauge__center">
        {showValue && <div className="hesh-gauge__value">{formattedValue}</div>}
        {label && <div className="hesh-gauge__label">{label}</div>}
        {sublabel && <div className="hesh-gauge__sublabel">{sublabel}</div>}
      </div>
    </div>
  );
});

import React, {
  cloneElement,
  useId,
  useRef,
  useState,
  type ReactElement,
  type ReactNode,
} from 'react';
import { cn } from '../utils/cn';
import { Portal } from './Portal';
import { useFloating } from '../hooks/useFloating';
import { useDismiss } from '../hooks/useDismiss';

export interface HoverCardProps {
  /** Rich preview content rendered inside the floating card. */
  content: ReactNode;
  /** Trigger element that spawns the hover card. */
  children: ReactElement;
  /** Placement direction relative to the trigger. @default 'bottom' */
  placement?: 'top' | 'bottom' | 'left' | 'right';
  /** Alignment along the placement edge. @default 'start' */
  align?: 'start' | 'center' | 'end';
  /** Optional custom card width or max-width. */
  width?: number | string;
  /** Render an anchor arrow pointer. @default false */
  arrow?: boolean;
  /** Delay in milliseconds before opening on pointer hover. @default 200 */
  openDelay?: number;
  /** Delay in milliseconds before closing when pointer leaves. @default 250 */
  closeDelay?: number;
  /** Pixel distance between trigger and card. @default 8 */
  offset?: number;
  /** Whether the hover card is disabled. @default false */
  disabled?: boolean;
  /** Controlled open state. */
  open?: boolean;
  /** Callback fired when open state changes. */
  onOpenChange?: (open: boolean) => void;
  /** Optional custom class for the floating card container. */
  cardClassName?: string;
}

/**
 * HoverCard renders a rich floating preview popup on hover or focus.
 * Includes interactive hover buffer so users can move their cursor into the card.
 */
export function HoverCard({
  content,
  children,
  placement = 'bottom',
  align = 'start',
  width,
  arrow = false,
  openDelay = 200,
  closeDelay = 250,
  offset = 8,
  disabled = false,
  open: controlledOpen,
  onOpenChange,
  cardClassName,
}: HoverCardProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(false);
  const isControlled = controlledOpen !== undefined;
  const isOpen = (isControlled ? controlledOpen : uncontrolledOpen) && !disabled;

  const anchorRef = useRef<HTMLElement | null>(null);
  const cardRef = useRef<HTMLDivElement | null>(null);
  const openTimerRef = useRef<number | null>(null);
  const closeTimerRef = useRef<number | null>(null);
  const id = `pui-hover-card-${useId()}`;

  const { setFloating, coords, ready } = useFloating<HTMLDivElement>(
    anchorRef as React.RefObject<HTMLElement>,
    isOpen,
    { placement, align, offset }
  );

  const clearTimers = () => {
    if (openTimerRef.current) {
      window.clearTimeout(openTimerRef.current);
      openTimerRef.current = null;
    }
    if (closeTimerRef.current) {
      window.clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  };

  const setOpenState = (next: boolean) => {
    if (!isControlled) setUncontrolledOpen(next);
    onOpenChange?.(next);
  };

  const scheduleOpen = (immediate = false) => {
    if (disabled) return;
    clearTimers();
    if (immediate) {
      setOpenState(true);
    } else {
      openTimerRef.current = window.setTimeout(() => setOpenState(true), openDelay);
    }
  };

  const scheduleClose = (immediate = false) => {
    clearTimers();
    if (immediate) {
      setOpenState(false);
    } else {
      closeTimerRef.current = window.setTimeout(() => setOpenState(false), closeDelay);
    }
  };

  useDismiss(cardRef, isOpen, () => scheduleClose(true), { ignore: [anchorRef] });

  const trigger = cloneElement(children, {
    ref: (node: HTMLElement | null) => {
      anchorRef.current = node;
      const childRef = (children as ReactElement & { ref?: unknown }).ref;
      if (typeof childRef === 'function') childRef(node);
      else if (childRef && typeof childRef === 'object') {
        (childRef as { current: unknown }).current = node;
      }
    },
    'aria-haspopup': 'dialog',
    'aria-expanded': isOpen,
    'aria-controls': isOpen ? id : undefined,
    onMouseEnter: (e: React.MouseEvent) => {
      scheduleOpen();
      (children.props as { onMouseEnter?: (e: React.MouseEvent) => void }).onMouseEnter?.(e);
    },
    onMouseLeave: (e: React.MouseEvent) => {
      scheduleClose();
      (children.props as { onMouseLeave?: (e: React.MouseEvent) => void }).onMouseLeave?.(e);
    },
    onFocus: (e: React.FocusEvent) => {
      scheduleOpen(true);
      (children.props as { onFocus?: (e: React.FocusEvent) => void }).onFocus?.(e);
    },
    onBlur: (e: React.FocusEvent) => {
      scheduleClose();
      (children.props as { onBlur?: (e: React.FocusEvent) => void }).onBlur?.(e);
    },
    onClick: (e: React.MouseEvent) => {
      const isTouch =
        (e.nativeEvent as PointerEvent)?.pointerType === 'touch' ||
        'ontouchstart' in window ||
        (typeof navigator !== 'undefined' && navigator.maxTouchPoints > 0);
      if (isTouch) {
        if (!isOpen) {
          // Prevent link navigation if tapped to open on mobile
          e.preventDefault();
        }
        setOpenState(!isOpen);
      }
      (children.props as { onClick?: (e: React.MouseEvent) => void }).onClick?.(e);
    },
  } as Partial<unknown> as never);

  return (
    <>
      {trigger}

      {isOpen && (
        <Portal>
          <div
            ref={(node) => {
              cardRef.current = node;
              setFloating(node);
            }}
            id={id}
            role="dialog"
            aria-label="Hover Card Preview"
            className={cn(
              'pui-hover-card',
              `pui-hover-card--${placement}`,
              `pui-hover-card--align-${align}`,
              cardClassName
            )}
            style={{
              position: 'fixed',
              left: `${coords.x}px`,
              top: `${coords.y}px`,
              visibility: ready ? 'visible' : 'hidden',
              width: width
                ? typeof width === 'number'
                  ? `min(${width}px, calc(100vw - 24px))`
                  : width
                : undefined,
              maxWidth: 'calc(100vw - 24px)',
            }}
            onMouseEnter={clearTimers}
            onMouseLeave={() => scheduleClose()}
          >
            {arrow && <div className="pui-hover-card__arrow" aria-hidden="true" />}
            {content}
          </div>
        </Portal>
      )}
    </>
  );
}

import type { SVGProps } from 'react';

/**
 * Hand-tuned 24px stroke icon set.
 *
 * Why not lucide-react / react-icons: importing an icon library pulls the whole
 * bundle unless the consumer sets up per-icon imports. These are ~350 bytes
 * each, tree-shake naturally, and inherit `currentColor` + `1em` sizing.
 */
export type IconProps = SVGProps<SVGSVGElement> & { size?: number | string };

function Icon({ size = '1em', children, ...props }: IconProps & { children: React.ReactNode }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.75}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      {...props}
    >
      {children}
    </svg>
  );
}

