/**
 * Backward compatibility barrel for interactive components.
 * Components have been moved to their own dedicated files in accordance with the
 * library's "one component family per file" architecture:
 * - Popover.tsx
 * - Command.tsx
 * - Accordion.tsx
 * - Slider.tsx
 * - Calendar.tsx
 * - DatePicker.tsx
 */

export { Popover } from './Popover';
export type { PopoverProps } from './Popover';

export { Command, useCommandShortcut } from './Command';
export type { CommandProps, CommandItem } from './Command';

export { Accordion } from './Accordion';
export type { AccordionProps, AccordionItem } from './Accordion';

export { Slider } from './Slider';
export type { SliderProps } from './Slider';

export { Calendar } from './Calendar';
export type { CalendarProps } from './Calendar';

export { DatePicker } from './DatePicker';
export type { DatePickerProps } from './DatePicker';

import { useCallback, useState, type ReactNode } from 'react';
import { cn } from '../utils/cn';
import { Badge } from './Badge';
import { ChevronLeftIcon, ChevronRightIcon } from './icons';

export interface KanbanColumn {
  id: string;
  title: string;
  icon?: ReactNode;
}

export interface KanbanCard {
  id: string;
  columnId: string;
  title: string;
  description?: string;
  tags?: { label: string; tone?: 'neutral' | 'primary' | 'success' | 'warning' | 'danger' }[];
  assignee?: { name: string; avatarUrl?: string; initials?: string };
  priority?: 'low' | 'medium' | 'high' | 'urgent';
  due?: string;
}

export interface KanbanProps {
  columns: KanbanColumn[];
  cards: KanbanCard[];
  onMove?: (cardId: string, toColumnId: string, toIndex: number) => void;
  onCardClick?: (card: KanbanCard) => void;
  className?: string;
}

const priorityMap = {
  low: { label: 'Low', tone: 'neutral' as const },
  medium: { label: 'Med', tone: 'primary' as const },
  high: { label: 'High', tone: 'warning' as const },
  urgent: { label: 'Urgent', tone: 'danger' as const },
};

export function Kanban({ columns, cards, onMove, onCardClick, className }: KanbanProps) {
  const [draggedId, setDraggedId] = useState<string | null>(null);
  const [dragOverColumn, setDragOverColumn] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<string>('all');

  const cardsByColumn = (colId: string) => cards.filter((c) => c.columnId === colId);
  const visibleColumns = activeTab === 'all' ? columns : columns.filter((c) => c.id === activeTab);

  const handleDragStart = useCallback((e: React.DragEvent, id: string) => {
    setDraggedId(id);
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', id);
    // ghost styling
    const el = e.currentTarget as HTMLElement;
    requestAnimationFrame(() => el.classList.add('pui-kanban__card--dragging'));
  }, []);

  const handleDragEnd = useCallback((e: React.DragEvent) => {
    (e.currentTarget as HTMLElement).classList.remove('pui-kanban__card--dragging');
    setDraggedId(null);
    setDragOverColumn(null);
  }, []);

  const handleDragOver = useCallback((e: React.DragEvent, colId: string) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    setDragOverColumn(colId);
  }, []);

  const handleDrop = useCallback(
    (e: React.DragEvent, colId: string) => {
      e.preventDefault();
      const id = e.dataTransfer.getData('text/plain') || draggedId;
      if (!id) return;
      const colCards = cardsByColumn(colId);
      onMove?.(id, colId, colCards.length);
      setDraggedId(null);
      setDragOverColumn(null);
    },
    [draggedId, cards, onMove]
  );

  return (
    <div className={cn('pui-kanban-root', className)}>
      {/* Mobile Column Tabs: visible on small screens / containers to filter or view all */}
      {columns.length > 1 && (
        <div className="pui-kanban__mobile-tabs" role="tablist" aria-label="Filter columns">
          <button
            type="button"
            role="tab"
            aria-selected={activeTab === 'all'}
            className={cn('pui-kanban__mobile-tab', activeTab === 'all' && 'pui-kanban__mobile-tab--active')}
            onClick={() => setActiveTab('all')}
          >
            All <span className="pui-kanban__tab-count">{cards.length}</span>
          </button>
          {columns.map((col) => {
            const count = cardsByColumn(col.id).length;
            return (
              <button
                key={col.id}
                type="button"
                role="tab"
                aria-selected={activeTab === col.id}
                className={cn('pui-kanban__mobile-tab', activeTab === col.id && 'pui-kanban__mobile-tab--active')}
                onClick={() => setActiveTab(col.id)}
              >
                {col.title} <span className="pui-kanban__tab-count">{count}</span>
              </button>
            );
          })}
        </div>
      )}

      <div className="pui-kanban">
        {visibleColumns.map((col) => {
          const colCards = cardsByColumn(col.id);
          const colIndex = columns.findIndex((c) => c.id === col.id);
          const prevCol = colIndex > 0 ? columns[colIndex - 1] : null;
          const nextCol = colIndex < columns.length - 1 ? columns[colIndex + 1] : null;

          return (
            <div
              key={col.id}
              className={cn('pui-kanban__col', dragOverColumn === col.id && 'pui-kanban__col--over')}
              onDragOver={(e) => handleDragOver(e, col.id)}
              onDragLeave={() => setDragOverColumn((prev) => (prev === col.id ? null : prev))}
              onDrop={(e) => handleDrop(e, col.id)}
            >
              <div className="pui-kanban__col-head">
                <div className="pui-kanban__col-title">
                  {col.icon && <span className="pui-kanban__col-icon">{col.icon}</span>}
                  {col.title}
                </div>
                <Badge tone="neutral" pill>{colCards.length}</Badge>
              </div>

              <div className="pui-kanban__col-body">
                {colCards.map((card) => (
                  <div
                    key={card.id}
                    draggable
                    onDragStart={(e) => handleDragStart(e, card.id)}
                    onDragEnd={handleDragEnd}
                    onClick={() => onCardClick?.(card)}
                    className={cn('pui-kanban__card', draggedId === card.id && 'pui-kanban__card--dragging')}
                    role="button"
                    tabIndex={0}
                    aria-label={`${card.title} in ${col.title}`}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        onCardClick?.(card);
                      }
                    }}
                  >
                    <div className="pui-kanban__card-top">
                      <div className="row-wrap" style={{ gap: '0.375rem', alignItems: 'center' }}>
                        {card.priority && (
                          <Badge tone={priorityMap[card.priority].tone} pill>
                            {priorityMap[card.priority].label}
                          </Badge>
                        )}
                        {card.due && <span className="pui-kanban__card-due">{card.due}</span>}
                      </div>

                      {/* Quick Move Buttons (accessible on mobile/touch & keyboard) */}
                      {onMove && (prevCol || nextCol) && (
                        <div
                          className="pui-kanban__card-move-cluster"
                          onClick={(e) => e.stopPropagation()}
                          role="group"
                          aria-label="Move card"
                        >
                          {prevCol && (
                            <button
                              type="button"
                              className="pui-kanban__move-btn"
                              title={`Move to ${prevCol.title}`}
                              aria-label={`Move to ${prevCol.title}`}
                              onClick={() => onMove(card.id, prevCol.id, 0)}
                            >
                              <ChevronLeftIcon size={12} />
                            </button>
                          )}
                          {nextCol && (
                            <button
                              type="button"
                              className="pui-kanban__move-btn"
                              title={`Move to ${nextCol.title}`}
                              aria-label={`Move to ${nextCol.title}`}
                              onClick={() => onMove(card.id, nextCol.id, 0)}
                            >
                              <ChevronRightIcon size={12} />
                            </button>
                          )}
                        </div>
                      )}
                    </div>

                    <div className="pui-kanban__card-title">{card.title}</div>
                    {card.description && <div className="pui-kanban__card-desc">{card.description}</div>}

                    {(card.tags && card.tags.length > 0) || card.assignee ? (
                      <div className="pui-kanban__card-foot">
                        <div className="pui-kanban__card-tags">
                          {card.tags?.map((t) => (
                            <Badge key={t.label} tone={t.tone ?? 'neutral'}>{t.label}</Badge>
                          ))}
                        </div>
                        {card.assignee && (
                          <div className="pui-kanban__card-assignee" title={card.assignee.name}>
                            {card.assignee.avatarUrl ? (
                              <img src={card.assignee.avatarUrl} alt="" />
                            ) : (
                              <span>{card.assignee.initials ?? card.assignee.name.slice(0, 2).toUpperCase()}</span>
                            )}
                          </div>
                        )}
                      </div>
                    ) : null}
                  </div>
                ))}

                {colCards.length === 0 && (
                  <div className="pui-kanban__empty">No cards — drop here</div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import React, {
  forwardRef,
  type ReactNode,
  type HTMLAttributes,
} from 'react';
import { cn } from '../utils/cn';

export interface MarqueeProps extends HTMLAttributes<HTMLDivElement> {
  direction?: 'left' | 'right' | 'up' | 'down';
  speed?: number; // duration in seconds
  pauseOnHover?: boolean;
  pauseOnClick?: boolean;
  gap?: string;
  fade?: boolean;
  repeat?: number;
  children: ReactNode;
}

export const Marquee = forwardRef<HTMLDivElement, MarqueeProps>(function Marquee(
  {
    direction = 'left',
    speed = 25,
    pauseOnHover = true,
    pauseOnClick = false,
    gap = '2rem',
    fade = true,
    repeat = 2,
    children,
    className,
    style,
    ...props
  },
  ref
) {
  const isVertical = direction === 'up' || direction === 'down';

  return (
    <div
      ref={ref}
      className={cn(
        'hesh-marquee',
        `hesh-marquee--${direction}`,
        pauseOnHover && 'hesh-marquee--pause-hover',
        pauseOnClick && 'hesh-marquee--pause-click',
        fade && (isVertical ? 'hesh-marquee--fade-y' : 'hesh-marquee--fade-x'),
        className
      )}
      style={
        {
          '--marquee-duration': `${speed}s`,
          '--marquee-gap': gap,
          ...style,
        } as React.CSSProperties
      }
      {...props}
    >
      {Array.from({ length: repeat }).map((_, index) => (
        <div
          key={index}
          className="hesh-marquee__content"
          aria-hidden={index > 0 ? true : undefined}
        >
          {children}
        </div>
      ))}
    </div>
  );
});

import React, {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { cn } from '../utils/cn';
import { Portal } from './Portal';
import { useFloating } from '../hooks/useFloating';
import { useDismiss } from '../hooks/useDismiss';
import { CheckIcon, ChevronRightIcon } from './icons';

export interface MenuItemSpec {
  id?: string;
  label: ReactNode;
  icon?: ReactNode;
  shortcut?: string;
  disabled?: boolean;
  tone?: 'default' | 'danger';
  inset?: boolean;
  description?: ReactNode;
  onSelect?: () => void;
}

export interface MenuCheckboxSpec {
  id?: string;
  label: ReactNode;
  checked: boolean;
  disabled?: boolean;
  inset?: boolean;
  description?: ReactNode;
  onCheckedChange: (checked: boolean) => void;
}

export interface MenuRadioSpec {
  id?: string;
  label: ReactNode;
  value: string;
  group?: string;
  checked?: boolean;
  disabled?: boolean;
  inset?: boolean;
  description?: ReactNode;
  onSelect?: (value: string) => void;
}

export interface MenuSubmenuSpec {
  id?: string;
  label: ReactNode;
  icon?: ReactNode;
  disabled?: boolean;
  inset?: boolean;
  description?: ReactNode;
  items: readonly MenuEntry[];
}

export type MenuEntry =
  | ({ kind: 'item' } & MenuItemSpec)
  | ({ kind: 'checkbox' } & MenuCheckboxSpec)
  | ({ kind: 'radio' } & MenuRadioSpec)
  | ({ kind: 'submenu' } & MenuSubmenuSpec)
  | { kind: 'separator'; id?: string }
  | { kind: 'label'; id?: string; label: ReactNode };

export interface TriggerRenderProps {
  ref: (node: HTMLElement | null) => void;
  open: boolean;
  'aria-haspopup': 'menu';
  'aria-expanded': boolean;
  'aria-controls': string;
  onClick: () => void;
  onKeyDown: (event: React.KeyboardEvent) => void;
}

export interface DropdownMenuProps {
  items: readonly MenuEntry[];
  trigger: (props: TriggerRenderProps) => ReactNode;
  align?: 'start' | 'center' | 'end';
  placement?: 'top' | 'bottom' | 'left' | 'right';
  size?: 'sm' | 'md' | 'lg';
  arrow?: boolean;
  offset?: number;
  modal?: boolean;
  className?: string;
}

export const isFocusableMenuEntry = (entry: MenuEntry): boolean =>
  (entry.kind === 'item' && !entry.disabled) ||
  (entry.kind === 'checkbox' && !entry.disabled) ||
  (entry.kind === 'radio' && !entry.disabled) ||
  (entry.kind === 'submenu' && !entry.disabled);

interface SubmenuFloatingProps {
  items: readonly MenuEntry[];
  parentItemEl: HTMLElement | null;
  size?: 'sm' | 'md' | 'lg';
  className?: string;
  onCloseAll: () => void;
  onCloseSubmenu: () => void;
}

/**
 * Floating child submenu panel positioned adjacent to parent menu item.
 */
function SubmenuPanel({
  items,
  parentItemEl,
  size = 'md',
  className,
  onCloseAll,
  onCloseSubmenu,
}: SubmenuFloatingProps) {
  const panelRef = useRef<HTMLDivElement | null>(null);
  const [activeIndex, setActiveIndex] = useState(0);
  const [coords, setCoords] = useState({ x: 0, y: 0 });
  const [ready, setReady] = useState(false);
  const submenuId = `pui-submenu-${useId()}`;

  const focusableIndexes = items
    .map((e, idx) => (isFocusableMenuEntry(e) ? idx : -1))
    .filter((idx) => idx !== -1);

  // Position submenu to right (or left if edge collision) of parentItemEl
  useEffect(() => {
    if (!parentItemEl) return;
    const parentRect = parentItemEl.getBoundingClientRect();
    const menuWidth = size === 'sm' ? 180 : size === 'lg' ? 240 : 200;
    const gap = 4;

    let x = parentRect.right + gap;
    if (x + menuWidth > window.innerWidth - 12) {
      x = Math.max(12, parentRect.left - menuWidth - gap);
    }

    let y = parentRect.top - 4;
    const estimatedHeight = Math.min(items.length * 36 + 16, 320);
    if (y + estimatedHeight > window.innerHeight - 12) {
      y = Math.max(12, window.innerHeight - estimatedHeight - 12);
    }

    setCoords({ x, y });
    setReady(true);
    requestAnimationFrame(() => {
      panelRef.current?.focus();
    });
  }, [parentItemEl, items.length, size]);

  const move = (delta: number) => {
    if (focusableIndexes.length === 0) return;
    const currentPos = focusableIndexes.indexOf(activeIndex);
    const nextPos =
      currentPos === -1
        ? delta > 0
          ? 0
          : focusableIndexes.length - 1
        : (currentPos + delta + focusableIndexes.length) % focusableIndexes.length;
    setActiveIndex(focusableIndexes[nextPos]!);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        move(1);
        break;
      case 'ArrowUp':
        e.preventDefault();
        move(-1);
        break;
      case 'ArrowLeft':
        e.preventDefault();
        onCloseSubmenu();
        break;
      case 'Home':
        e.preventDefault();
        setActiveIndex(focusableIndexes[0] ?? -1);
        break;
      case 'End':
        e.preventDefault();
        setActiveIndex(focusableIndexes[focusableIndexes.length - 1] ?? -1);
        break;
      case 'Escape':
        e.preventDefault();
        onCloseAll();
        break;
      case 'Enter':
      case ' ': {
        e.preventDefault();
        const entry = items[activeIndex];
        if (!entry) break;
        if (entry.kind === 'item' && !entry.disabled) {
          entry.onSelect?.();
          onCloseAll();
        } else if (entry.kind === 'checkbox' && !entry.disabled) {
          entry.onCheckedChange(!entry.checked);
        } else if (entry.kind === 'radio' && !entry.disabled) {
          entry.onSelect?.(entry.value);
          onCloseAll();
        }
        break;
      }
    }
  };

  return (
    <Portal>
      <div
        ref={panelRef}
        id={submenuId}
        role="menu"
        tabIndex={-1}
        className={cn(
          'pui-menu',
          'pui-menu--submenu',
          `pui-menu--${size}`,
          className
        )}
        style={{
          position: 'fixed',
          left: coords.x,
          top: coords.y,
          visibility: ready ? 'visible' : 'hidden',
          zIndex: 'calc(var(--pui-z-popover, 1300) + 10)',
        }}
        onKeyDown={handleKeyDown}
      >
        {items.map((entry, index) => {
          const key = entry.id ?? `sub-${index}`;

          if (entry.kind === 'separator') {
            return <div key={key} role="separator" className="pui-menu__separator" />;
          }

          if (entry.kind === 'label') {
            return (
              <div key={key} className="pui-menu__label">
                {entry.label}
              </div>
            );
          }

          if (entry.kind === 'checkbox') {
            return (
              <div
                key={key}
                role="menuitemcheckbox"
                aria-checked={entry.checked}
                aria-disabled={entry.disabled || undefined}
                data-disabled={entry.disabled ? 'true' : undefined}
                data-active={index === activeIndex ? 'true' : undefined}
                className={cn('pui-menu__item', entry.inset && 'pui-menu__item--inset')}
                onClick={() => {
                  if (entry.disabled) return;
                  entry.onCheckedChange(!entry.checked);
                }}
                onMouseEnter={() => !entry.disabled && setActiveIndex(index)}
              >
                <span className="pui-menu__checkbox" aria-hidden="true">
                  {entry.checked && <CheckIcon size={14} />}
                </span>
                <div className="pui-menu__item__body">
                  <div className="pui-menu__item__title">{entry.label}</div>
                  {entry.description && (
                    <div className="pui-menu__item__desc">{entry.description}</div>
                  )}
                </div>
              </div>
            );
          }

          if (entry.kind === 'radio') {
            return (
              <div
                key={key}
                role="menuitemradio"
                aria-checked={entry.checked}
                aria-disabled={entry.disabled || undefined}
                data-disabled={entry.disabled ? 'true' : undefined}
                data-active={index === activeIndex ? 'true' : undefined}
                className={cn('pui-menu__item', entry.inset && 'pui-menu__item--inset')}
                onClick={() => {
                  if (entry.disabled) return;
                  entry.onSelect?.(entry.value);
                  onCloseAll();
                }}
                onMouseEnter={() => !entry.disabled && setActiveIndex(index)}
              >
                <span className="pui-menu__radio" aria-hidden="true">
                  {entry.checked && <span className="pui-menu__radio-bullet" />}
                </span>
                <div className="pui-menu__item__body">
                  <div className="pui-menu__item__title">{entry.label}</div>
                  {entry.description && (
                    <div className="pui-menu__item__desc">{entry.description}</div>
                  )}
                </div>
              </div>
            );
          }

          if (entry.kind === 'item') {
            return (
              <div
                key={key}
                role="menuitem"
                aria-disabled={entry.disabled || undefined}
                data-disabled={entry.disabled ? 'true' : undefined}
                data-active={index === activeIndex ? 'true' : undefined}
                className={cn(
                  'pui-menu__item',
                  entry.tone === 'danger' && 'pui-menu__item--danger',
                  entry.inset && 'pui-menu__item--inset'
                )}
                onClick={() => {
                  if (entry.disabled) return;
                  entry.onSelect?.();
                  onCloseAll();
                }}
                onMouseEnter={() => !entry.disabled && setActiveIndex(index)}
              >
                {entry.icon && <span className="pui-menu__item__icon">{entry.icon}</span>}
                <div className="pui-menu__item__body">
                  <div className="pui-menu__item__title">{entry.label}</div>
                  {entry.description && (
                    <div className="pui-menu__item__desc">{entry.description}</div>
                  )}
                </div>
                {entry.shortcut && (
                  <span className="pui-menu__item__shortcut">{entry.shortcut}</span>
                )}
              </div>
            );
          }

          return null;
        })}
      </div>
    </Portal>
  );
}

/**
 * Menu button following the WAI-ARIA Menu Button pattern.
 *
 * - Trigger keeps DOM focus; popup uses `aria-activedescendant` for screen reader announcements.
 * - Arrow keys wrap, Home/End jump, Escape closes and returns focus to trigger.
 * - Supports cascading submenus, radio groups, checkboxes, descriptions, shortcuts, and sizes.
 */
export function DropdownMenu({
  items,
  trigger,
  align = 'start',
  placement = 'bottom',
  size = 'md',
  arrow = false,
  offset = 6,
  modal = false,
  className,
}: DropdownMenuProps) {
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const [typeahead, setTypeahead] = useState('');
  const [openSubmenuIndex, setOpenSubmenuIndex] = useState<number | null>(null);

  const triggerRef = useRef<HTMLElement | null>(null);
  const itemElementsRef = useRef<Map<number, HTMLElement>>(new Map());
  const submenuTimerRef = useRef<number | null>(null);
  const menuId = `pui-menu-${useId()}`;

  const { setFloating, floatingRef, coords, ready } = useFloating<HTMLDivElement>(
    triggerRef as React.RefObject<HTMLElement>,
    open,
    { placement, align, offset }
  );

  const wrapperRef = useRef<HTMLDivElement>(null);
  const close = useCallback(() => {
    setOpen(false);
    setActiveIndex(-1);
    setTypeahead('');
    setOpenSubmenuIndex(null);
  }, []);

  useDismiss(wrapperRef, open, close, { escape: true, outside: true, ignore: [floatingRef] });

  // Move DOM focus into menu on open
  useEffect(() => {
    if (!open) return;
    const raf = requestAnimationFrame(() => floatingRef.current?.focus());
    return () => cancelAnimationFrame(raf);
  }, [open, floatingRef]);

  const focusableIndexes = items
    .map((entry, index) => (isFocusableMenuEntry(entry) ? index : -1))
    .filter((index) => index !== -1);

  const move = useCallback(
    (delta: number) => {
      if (focusableIndexes.length === 0) return;
      const currentPosition = focusableIndexes.indexOf(activeIndex);
      const nextPosition =
        currentPosition === -1
          ? delta > 0
            ? 0
            : focusableIndexes.length - 1
          : (currentPosition + delta + focusableIndexes.length) % focusableIndexes.length;
      setActiveIndex(focusableIndexes[nextPosition]!);
      setOpenSubmenuIndex(null);
    },
    [activeIndex, focusableIndexes]
  );

  const onTriggerKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp' || event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      setOpen(true);
      setActiveIndex(focusableIndexes[0] ?? -1);
    }
  };

  const onMenuKeyDown = (event: React.KeyboardEvent) => {
    const activeEntry = items[activeIndex];

    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        move(1);
        break;
      case 'ArrowUp':
        event.preventDefault();
        move(-1);
        break;
      case 'ArrowRight': {
        if (activeEntry && activeEntry.kind === 'submenu' && !activeEntry.disabled) {
          event.preventDefault();
          setOpenSubmenuIndex(activeIndex);
        }
        break;
      }
      case 'Home':
        event.preventDefault();
        setActiveIndex(focusableIndexes[0] ?? -1);
        setOpenSubmenuIndex(null);
        break;
      case 'End':
        event.preventDefault();
        setActiveIndex(focusableIndexes[focusableIndexes.length - 1] ?? -1);
        setOpenSubmenuIndex(null);
        break;
      case 'Tab':
        event.preventDefault();
        close();
        triggerRef.current?.focus();
        break;
      case 'Enter':
      case ' ': {
        event.preventDefault();
        if (!activeEntry) break;
        if (activeEntry.kind === 'submenu' && !activeEntry.disabled) {
          setOpenSubmenuIndex(activeIndex);
        } else if (activeEntry.kind === 'item' && !activeEntry.disabled) {
          activeEntry.onSelect?.();
          close();
          triggerRef.current?.focus();
        } else if (activeEntry.kind === 'checkbox' && !activeEntry.disabled) {
          activeEntry.onCheckedChange(!activeEntry.checked);
        } else if (activeEntry.kind === 'radio' && !activeEntry.disabled) {
          activeEntry.onSelect?.(activeEntry.value);
          close();
          triggerRef.current?.focus();
        }
        break;
      }
      default: {
        if (event.key.length === 1 && !event.metaKey && !event.ctrlKey && !event.altKey) {
          const next = typeahead + event.key.toLowerCase();
          setTypeahead(next);
          const match = focusableIndexes.find((index) => {
            const entry = items[index];
            const label =
              entry && 'label' in entry && typeof entry.label === 'string'
                ? entry.label.toLowerCase()
                : '';
            return label.startsWith(next);
          });
          if (match !== undefined) {
            setActiveIndex(match);
            setOpenSubmenuIndex(null);
          }
          window.clearTimeout((onMenuKeyDown as { _t?: number })._t);
          (onMenuKeyDown as { _t?: number })._t = window.setTimeout(() => setTypeahead(''), 600);
        }
      }
    }
  };

  // Keep highlighted row visible in scroll view
  useEffect(() => {
    if (!open || activeIndex < 0) return;
    const node = floatingRef.current?.querySelector<HTMLElement>(`[data-index="${activeIndex}"]`);
    node?.scrollIntoView({ block: 'nearest' });
  }, [activeIndex, open, floatingRef]);

  const scheduleSubmenuOpen = (index: number) => {
    if (submenuTimerRef.current) window.clearTimeout(submenuTimerRef.current);
    submenuTimerRef.current = window.setTimeout(() => {
      setOpenSubmenuIndex(index);
    }, 120);
  };

  const scheduleSubmenuClose = () => {
    if (submenuTimerRef.current) window.clearTimeout(submenuTimerRef.current);
    submenuTimerRef.current = window.setTimeout(() => {
      setOpenSubmenuIndex(null);
    }, 180);
  };

  const element = trigger({
    ref: (node) => {
      triggerRef.current = node;
    },
    open,
    'aria-haspopup': 'menu',
    'aria-expanded': open,
    'aria-controls': open ? menuId : '',
    onClick: () => {
      setOpen((prev) => !prev);
      setActiveIndex(focusableIndexes[0] ?? -1);
      setOpenSubmenuIndex(null);
    },
    onKeyDown: onTriggerKeyDown,
  });

  return (
    <div ref={wrapperRef} style={{ display: 'inline-flex' }}>
      {element}
      {open && (
        <>
          {modal && (
            <div
              className="pui-menu__backdrop"
              aria-hidden="true"
              onClick={close}
            />
          )}
          <Portal>
            <div
              ref={setFloating}
              id={menuId}
              role="menu"
              tabIndex={-1}
              aria-activedescendant={
                activeIndex >= 0 ? `${menuId}-opt-${activeIndex}` : undefined
              }
              className={cn(
                'pui-menu',
                `pui-menu--${size}`,
                className
              )}
              style={{
                position: 'fixed',
                top: coords.y,
                left: coords.x,
                visibility: ready ? 'visible' : 'hidden',
              }}
              onKeyDown={onMenuKeyDown}
            >
              {arrow && <div className="pui-menu__arrow" aria-hidden="true" />}
              {items.map((entry, index) => {
                const key = entry.id ?? `entry-${index}`;

                if (entry.kind === 'separator') {
                  return <div key={key} role="separator" className="pui-menu__separator" />;
                }

                if (entry.kind === 'label') {
                  return (
                    <div key={key} className="pui-menu__label">
                      {entry.label}
                    </div>
                  );
                }

                if (entry.kind === 'checkbox') {
                  return (
                    <div
                      key={key}
                      id={`${menuId}-opt-${index}`}
                      role="menuitemcheckbox"
                      aria-checked={entry.checked}
                      aria-disabled={entry.disabled || undefined}
                      data-disabled={entry.disabled ? 'true' : undefined}
                      data-active={index === activeIndex ? 'true' : undefined}
                      data-index={index}
                      className={cn('pui-menu__item', entry.inset && 'pui-menu__item--inset')}
                      onClick={() => {
                        if (entry.disabled) return;
                        entry.onCheckedChange(!entry.checked);
                      }}
                      onMouseEnter={() => {
                        if (!entry.disabled) {
                          setActiveIndex(index);
                          scheduleSubmenuClose();
                        }
                      }}
                    >
                      <span className="pui-menu__checkbox" aria-hidden="true">
                        {entry.checked && <CheckIcon size={14} />}
                      </span>
                      <div className="pui-menu__item__body">
                        <div className="pui-menu__item__title">{entry.label}</div>
                        {entry.description && (
                          <div className="pui-menu__item__desc">{entry.description}</div>
                        )}
                      </div>
                    </div>
                  );
                }

                if (entry.kind === 'radio') {
                  return (
                    <div
                      key={key}
                      id={`${menuId}-opt-${index}`}
                      role="menuitemradio"
                      aria-checked={entry.checked}
                      aria-disabled={entry.disabled || undefined}
                      data-disabled={entry.disabled ? 'true' : undefined}
                      data-active={index === activeIndex ? 'true' : undefined}
                      data-index={index}
                      className={cn('pui-menu__item', entry.inset && 'pui-menu__item--inset')}
                      onClick={() => {
                        if (entry.disabled) return;
                        entry.onSelect?.(entry.value);
                        close();
                        triggerRef.current?.focus();
                      }}
                      onMouseEnter={() => {
                        if (!entry.disabled) {
                          setActiveIndex(index);
                          scheduleSubmenuClose();
                        }
                      }}
                    >
                      <span className="pui-menu__radio" aria-hidden="true">
                        {entry.checked && <span className="pui-menu__radio-bullet" />}
                      </span>
                      <div className="pui-menu__item__body">
                        <div className="pui-menu__item__title">{entry.label}</div>
                        {entry.description && (
                          <div className="pui-menu__item__desc">{entry.description}</div>
                        )}
                      </div>
                    </div>
                  );
                }

                if (entry.kind === 'submenu') {
                  const isSubmenuOpen = openSubmenuIndex === index;
                  return (
                    <div
                      key={key}
                      ref={(el) => {
                        if (el) itemElementsRef.current.set(index, el);
                        else itemElementsRef.current.delete(index);
                      }}
                      id={`${menuId}-opt-${index}`}
                      role="menuitem"
                      aria-haspopup="menu"
                      aria-expanded={isSubmenuOpen}
                      aria-disabled={entry.disabled || undefined}
                      data-disabled={entry.disabled ? 'true' : undefined}
                      data-active={index === activeIndex || isSubmenuOpen ? 'true' : undefined}
                      data-index={index}
                      className={cn(
                        'pui-menu__item',
                        'pui-menu__submenu-trigger',
                        entry.inset && 'pui-menu__item--inset'
                      )}
                      onClick={() => {
                        if (entry.disabled) return;
                        setOpenSubmenuIndex((prev) => (prev === index ? null : index));
                      }}
                      onMouseEnter={() => {
                        if (!entry.disabled) {
                          setActiveIndex(index);
                          scheduleSubmenuOpen(index);
                        }
                      }}
                    >
                      {entry.icon && <span className="pui-menu__item__icon">{entry.icon}</span>}
                      <div className="pui-menu__item__body">
                        <div className="pui-menu__item__title">{entry.label}</div>
                        {entry.description && (
                          <div className="pui-menu__item__desc">{entry.description}</div>
                        )}
                      </div>
                      <span className="pui-menu__chevron" aria-hidden="true">
                        <ChevronRightIcon size={14} />
                      </span>

                      {isSubmenuOpen && (
                        <SubmenuPanel
                          items={entry.items}
                          parentItemEl={itemElementsRef.current.get(index) ?? null}
                          size={size}
                          onCloseAll={close}
                          onCloseSubmenu={() => setOpenSubmenuIndex(null)}
                        />
                      )}
                    </div>
                  );
                }

                return (
                  <div
                    key={key}
                    id={`${menuId}-opt-${index}`}
                    role="menuitem"
                    aria-disabled={entry.disabled || undefined}
                    data-disabled={entry.disabled ? 'true' : undefined}
                    data-active={index === activeIndex ? 'true' : undefined}
                    data-index={index}
                    className={cn(
                      'pui-menu__item',
                      entry.tone === 'danger' && 'pui-menu__item--danger',
                      entry.inset && 'pui-menu__item--inset'
                    )}
                    onClick={() => {
                      if (entry.disabled) return;
                      entry.onSelect?.();
                      close();
                      triggerRef.current?.focus();
                    }}
                    onMouseEnter={() => {
                      if (!entry.disabled) {
                        setActiveIndex(index);
                        scheduleSubmenuClose();
                      }
                    }}
                  >
                    {entry.icon && <span className="pui-menu__item__icon">{entry.icon}</span>}
                    <div className="pui-menu__item__body">
                      <div className="pui-menu__item__title">{entry.label}</div>
                      {entry.description && (
                        <div className="pui-menu__item__desc">{entry.description}</div>
                      )}
                    </div>
                    {entry.shortcut && (
                      <span className="pui-menu__item__shortcut">{entry.shortcut}</span>
                    )}
                  </div>
                );
              })}
            </div>
          </Portal>
        </>
      )}
    </div>
  );
}

import { forwardRef, type HTMLAttributes, type ReactNode } from 'react';
import { cn } from '../utils/cn';

/* ------------------------------------------------------------------ Breadcrumbs */

export interface BreadcrumbItem {
  label: ReactNode;
  href?: string;
  onClick?: () => void;
}

export interface BreadcrumbsProps extends HTMLAttributes<HTMLElement> {
  items: readonly BreadcrumbItem[];
  separator?: ReactNode;
}

export function Breadcrumbs({ items, separator = '/', className, ...props }: BreadcrumbsProps) {
  return (
    <nav aria-label="Breadcrumb" className={cn('pui-breadcrumbs', className)} {...props}>
      <ol style={{ display: 'flex', alignItems: 'center', gap: 'var(--pui-space-1_5, 0.375rem)', flexWrap: 'wrap' }}>
        {items.map((item, index) => {
          const isLast = index === items.length - 1;
          return (
            <li key={index} style={{ display: 'inline-flex', alignItems: 'center', gap: 'var(--pui-space-1_5, 0.375rem)' }}>
              {isLast ? (
                <span aria-current="page">{item.label}</span>
              ) : item.href ? (
                <a href={item.href}>{item.label}</a>
              ) : (
                <button type="button" onClick={item.onClick} style={{ color: 'inherit' }}>
                  {item.label}
                </button>
              )}
              {!isLast && (
                <span className="pui-breadcrumbs__sep" aria-hidden="true">
                  {separator}
                </span>
              )}
            </li>
          );
        })}
      </ol>
    </nav>
  );
}

/* ------------------------------------------------------------------ PageHeader */

export interface PageHeaderProps extends Omit<HTMLAttributes<HTMLElement>, 'title'> {
  title: ReactNode;
  description?: ReactNode;
  /** Small uppercase label above the title. */
  eyebrow?: ReactNode;
  actions?: ReactNode;
  breadcrumbs?: ReactNode;
}

/**
 * Standard page masthead. Uses `<header>` + a single `<h1>` so each page keeps
 * one top-level heading for document outline and screen-reader navigation.
 */
export function PageHeader({
  title,
  description,
  eyebrow,
  actions,
  breadcrumbs,
  className,
  children,
  ...props
}: PageHeaderProps) {
  return (
    <header className={cn('pui-page-header', className)} {...props}>
      <div className="pui-page-header__main">
        {breadcrumbs}
        {eyebrow && <div className="pui-page-header__eyebrow">{eyebrow}</div>}
        <h1 className="pui-page-header__title">{title}</h1>
        {description && <p className="pui-page-header__desc">{description}</p>}
        {children}
      </div>
      {actions && <div className="pui-page-header__actions">{actions}</div>}
    </header>
  );
}

/* ------------------------------------------------------------------ SidebarNav */

export interface NavItem {
  id: string;
  label: ReactNode;
  icon?: ReactNode;
  href?: string;
  onClick?: () => void;
  badge?: ReactNode;
  disabled?: boolean;
}

export interface NavGroup {
  label?: ReactNode;
  items: readonly NavItem[];
}

export interface SidebarNavProps extends HTMLAttributes<HTMLElement> {
  groups: readonly NavGroup[];
  /** id of the item that represents the current page. */
  activeId?: string;
  'aria-label'?: string;
}

export const SidebarNav = forwardRef<HTMLElement, SidebarNavProps>(function SidebarNav(
  { groups, activeId, className, ...props },
  ref
) {
  return (
    <nav
      ref={ref}
      aria-label={props['aria-label'] ?? 'Main navigation'}
      className={cn('pui-nav', className)}
      {...props}
    >
      {groups.map((group, groupIndex) => (
        <div key={groupIndex} className="pui-nav__group">
          {group.label && <div className="pui-nav__group-label">{group.label}</div>}
          {group.items.map((item) => {
            const isActive = item.id === activeId;
            const content = (
              <>
                {item.icon && <span className="pui-nav__item__icon">{item.icon}</span>}
                <span className="pui-nav__item__text">{item.label}</span>
                {item.badge}
              </>
            );

            const shared = {
              className: 'pui-nav__item',
              'aria-current': isActive ? ('page' as const) : undefined,
              'aria-disabled': item.disabled || undefined,
            };

            if (item.disabled) {
              return (
                <span key={item.id} {...shared} aria-disabled="true" style={{ opacity: 0.45, cursor: 'not-allowed' }}>
                  {content}
                </span>
              );
            }

            if (item.href) {
              return (
                <a key={item.id} href={item.href} {...shared}>
                  {content}
                </a>
              );
            }

            return (
              <button key={item.id} type="button" onClick={item.onClick} {...shared}>
                {content}
              </button>
            );
          })}
        </div>
      ))}
    </nav>
  );
});

import React, {
  createContext,
  useContext,
  useState,
  useRef,
  forwardRef,
  type ReactNode,
  type HTMLAttributes,
  type ButtonHTMLAttributes,
  type AnchorHTMLAttributes,
} from 'react';
import { ChevronDownIcon } from './icons';
import { useDismiss } from '../hooks/useDismiss';
import { cn } from '../utils/cn';

interface NavigationMenuContextValue {
  activeItem: string | null;
  setActiveItem: (id: string | null) => void;
}

const NavigationMenuContext = createContext<NavigationMenuContextValue | null>(null);

export interface NavigationMenuProps extends HTMLAttributes<HTMLElement> {
  children?: ReactNode;
}

export const NavigationMenu = forwardRef<HTMLElement, NavigationMenuProps>(function NavigationMenu(
  { children, className, ...props },
  ref
) {
  const [activeItem, setActiveItem] = useState<string | null>(null);
  const containerRef = useRef<HTMLElement | null>(null);

  useDismiss(containerRef, activeItem !== null, () => setActiveItem(null));

  return (
    <NavigationMenuContext.Provider value={{ activeItem, setActiveItem }}>
      <nav
        ref={(node) => {
          containerRef.current = node;
          if (typeof ref === 'function') ref(node);
          else if (ref) ref.current = node;
        }}
        aria-label="Main Navigation"
        className={cn('hesh-nav-menu', className)}
        {...props}
      >
        {children}
      </nav>
    </NavigationMenuContext.Provider>
  );
});

export interface NavigationMenuListProps extends HTMLAttributes<HTMLUListElement> {
  children?: ReactNode;
}

export const NavigationMenuList = forwardRef<HTMLUListElement, NavigationMenuListProps>(
  function NavigationMenuList({ children, className, ...props }, ref) {
    return (
      <ul ref={ref} role="menubar" className={cn('hesh-nav-menu__list', className)} {...props}>
