import React, { forwardRef, type HTMLAttributes, type ReactNode } from 'react';
import { cn } from '../utils/cn';

export type NotificationBadgeTone = 'danger' | 'primary' | 'success' | 'warning' | 'neutral';
export type NotificationBadgePlacement = 'top-right' | 'top-left' | 'bottom-right' | 'bottom-left';

export interface NotificationBadgeProps extends HTMLAttributes<HTMLDivElement> {
  /** Number to display inside the badge. */
  count?: number;
  /** Maximum number to show before displaying as `{max}+`. Defaults to 99. */
  max?: number;
  /** If true, renders a compact status dot instead of a count. */
  dot?: boolean;
  /** If true, renders an animated pinging pulse ring behind the badge. */
  pulse?: boolean;
  /** Color theme tone of the badge. Defaults to 'danger'. */
  tone?: NotificationBadgeTone;
  /** Corner anchor placement. Defaults to 'top-right'. */
  placement?: NotificationBadgePlacement;
  /** Whether to show the badge when count is 0. Defaults to false. */
  showZero?: boolean;
  /** The child component (Avatar, Button, Icon) to anchor to. */
  children?: ReactNode;
}

export const NotificationBadge = forwardRef<HTMLDivElement, NotificationBadgeProps>(
  function NotificationBadge(
    {
      count,
      max = 99,
      dot = false,
      pulse = false,
      tone = 'danger',
      placement = 'top-right',
      showZero = false,
      children,
      className,
      style,
      ...rest
    },
    ref
  ) {
    const isHidden = !dot && count !== undefined && count <= 0 && !showZero;

    const displayCount =
      count !== undefined ? (count > max ? `${max}+` : String(count)) : null;

    const toneStyles: Record<NotificationBadgeTone, { bg: string; color: string; border: string }> = {
      danger: {
        bg: 'var(--pui-danger, #ef4444)',
        color: '#ffffff',
        border: 'var(--pui-surface, #ffffff)',
      },
      primary: {
        bg: 'var(--pui-primary, #6366f1)',
        color: '#ffffff',
        border: 'var(--pui-surface, #ffffff)',
      },
      success: {
        bg: 'var(--pui-success, #10b981)',
        color: '#ffffff',
        border: 'var(--pui-surface, #ffffff)',
      },
      warning: {
        bg: 'var(--pui-warning, #f59e0b)',
        color: '#000000',
        border: 'var(--pui-surface, #ffffff)',
      },
      neutral: {
        bg: 'var(--pui-fg-muted, #71717a)',
        color: '#ffffff',
        border: 'var(--pui-surface, #ffffff)',
      },
    };

    const currentTone = toneStyles[tone];

    const placementStyles: Record<NotificationBadgePlacement, React.CSSProperties> = {
      'top-right': { top: 0, right: 0, transform: 'translate(45%, -45%)' },
      'top-left': { top: 0, left: 0, transform: 'translate(-45%, -45%)' },
      'bottom-right': { bottom: 0, right: 0, transform: 'translate(45%, 45%)' },
      'bottom-left': { bottom: 0, left: 0, transform: 'translate(-45%, 45%)' },
    };

    if (!children) {
      // Standalone badge
      if (isHidden) return null;
      return (
        <span
          ref={ref as any}
          className={cn('pui-badge-count', className)}
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: dot ? '3px' : '0 6px',
            minWidth: dot ? '8px' : '18px',
            height: dot ? '8px' : '18px',
            borderRadius: '9999px',
            fontSize: '0.6875rem',
            fontWeight: 700,
            lineHeight: 1,
            backgroundColor: currentTone.bg,
            color: currentTone.color,
            ...style,
          }}
          {...(rest as any)}
        >
          {!dot && displayCount}
        </span>
      );
    }

    return (
      <div
        ref={ref}
        className={cn('pui-badge-anchor', className)}
        style={{
          position: 'relative',
          display: 'inline-flex',
          verticalAlign: 'middle',
          flexShrink: 0,
          ...style,
        }}
        {...rest}
      >
        {children}

        {!isHidden && (
          <span
            style={{
              position: 'absolute',
              zIndex: 10,
              display: 'inline-flex',
              alignItems: 'center',
              justifyContent: 'center',
              padding: dot ? 0 : '0 5px',
              minWidth: dot ? '9px' : '18px',
              height: dot ? '9px' : '18px',
              borderRadius: '9999px',
              fontSize: '0.6875rem',
              fontWeight: 700,
              lineHeight: 1,
              whiteSpace: 'nowrap',
              backgroundColor: currentTone.bg,
              color: currentTone.color,
              border: `2px solid ${currentTone.border}`,
              boxShadow: '0 1px 3px rgba(0,0,0,0.15)',
              userSelect: 'none',
              pointerEvents: 'none',
              ...placementStyles[placement],
            }}
          >
            {pulse && (
              <span
                style={{
                  position: 'absolute',
                  inset: -2,
                  borderRadius: '9999px',
                  backgroundColor: currentTone.bg,
                  opacity: 0.6,
                  animation: 'pui-ping 1.4s cubic-bezier(0, 0, 0.2, 1) infinite',
                  zIndex: -1,
                }}
              />
            )}
            {!dot && displayCount}
          </span>
        )}
      </div>
    );
  }
);

import React, {
  forwardRef,
  useRef,
  useState,
  useEffect,
  type ReactNode,
  type HTMLAttributes,
} from 'react';
import { ChevronUpIcon, ChevronDownIcon, PlusIcon, MinusIcon } from './icons';
import { cn } from '../utils/cn';

export interface NumberInputProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange' | 'prefix'> {
  value?: number;
  defaultValue?: number;
  onChange?: (val: number | undefined) => void;
  min?: number;
  max?: number;
  step?: number;
  precision?: number;
  allowNegative?: boolean;
  prefix?: ReactNode;
  suffix?: ReactNode;
  size?: 'sm' | 'md' | 'lg';
  stepperPosition?: 'right' | 'split';
  disabled?: boolean;
  readOnly?: boolean;
  placeholder?: string;
  name?: string;
  id?: string;
  required?: boolean;
  invalid?: boolean;
}

export const NumberInput = forwardRef<HTMLDivElement, NumberInputProps>(function NumberInput(
  {
    value: controlledValue,
    defaultValue,
    onChange,
    min,
    max,
    step = 1,
    precision,
    allowNegative = true,
    prefix,
    suffix,
    size = 'md',
    stepperPosition = 'right',
    disabled = false,
    readOnly = false,
    placeholder,
    name,
    id,
    required = false,
    invalid = false,
    className,
    ...props
  },
  ref
) {
  const isControlled = controlledValue !== undefined;
  const [internalValue, setInternalValue] = useState<number | undefined>(
    defaultValue ?? controlledValue
  );
  const currentValue = isControlled ? controlledValue : internalValue;

  const [textValue, setTextValue] = useState<string>(
    currentValue !== undefined ? String(currentValue) : ''
  );

  useEffect(() => {
    if (isControlled) {
      setTextValue(controlledValue !== undefined ? String(controlledValue) : '');
    }
  }, [controlledValue, isControlled]);

  const clampAndRound = (num: number): number => {
    let result = num;
    if (min !== undefined && result < min) result = min;
    if (max !== undefined && result > max) result = max;
    if (precision !== undefined) {
      result = Number(result.toFixed(precision));
    }
    return result;
  };

  const updateValue = (newVal: number | undefined) => {
    if (disabled || readOnly) return;
    if (newVal !== undefined) {
      newVal = clampAndRound(newVal);
      setTextValue(String(newVal));
    } else {
      setTextValue('');
    }
    if (!isControlled) {
      setInternalValue(newVal);
    }
    onChange?.(newVal);
  };

  const handleStep = (direction: 'up' | 'down', multiplier = 1) => {
    const current = currentValue ?? min ?? 0;
    const delta = step * multiplier * (direction === 'up' ? 1 : -1);
    updateValue(current + delta);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    if (!allowNegative && val.includes('-')) return;
    setTextValue(val);
    const parsed = parseFloat(val);
    if (!isNaN(parsed)) {
      if (!isControlled) {
        setInternalValue(parsed);
      }
      onChange?.(parsed);
    } else if (val === '' || val === '-') {
      if (!isControlled) {
        setInternalValue(undefined);
      }
      onChange?.(undefined);
    }
  };

  const handleBlur = () => {
    if (textValue.trim() === '') {
      updateValue(undefined);
    } else {
      const parsed = parseFloat(textValue);
      if (!isNaN(parsed)) {
        updateValue(parsed);
      } else {
        updateValue(currentValue);
      }
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (disabled || readOnly) return;
    const mult = e.shiftKey ? 10 : 1;
    if (e.key === 'ArrowUp') {
      e.preventDefault();
      handleStep('up', mult);
    } else if (e.key === 'ArrowDown') {
      e.preventDefault();
      handleStep('down', mult);
    } else if (e.key === 'Home' && min !== undefined) {
      e.preventDefault();
      updateValue(min);
    } else if (e.key === 'End' && max !== undefined) {
      e.preventDefault();
      updateValue(max);
    }
  };

  const timerRef = useRef<number | null>(null);
  const startStepping = (direction: 'up' | 'down') => {
    if (disabled || readOnly) return;
    handleStep(direction);
    timerRef.current = window.setInterval(() => {
      handleStep(direction);
    }, 120);
  };

  const stopStepping = () => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  };

  return (
    <div
      ref={ref}
      className={cn(
        'hesh-number-input',
        `hesh-number-input--${size}`,
        `hesh-number-input--stepper-${stepperPosition}`,
        disabled && 'hesh-number-input--disabled',
        readOnly && 'hesh-number-input--readonly',
        invalid && 'hesh-number-input--invalid',
        className
      )}
      {...props}
    >
      {stepperPosition === 'split' && (
        <button
          type="button"
          tabIndex={-1}
          disabled={disabled || readOnly || (min !== undefined && currentValue !== undefined && currentValue <= min)}
          onMouseDown={() => startStepping('down')}
          onMouseUp={stopStepping}
          onMouseLeave={stopStepping}
          aria-label="Decrement"
          className="hesh-number-input__btn hesh-number-input__btn--split-left"
        >
          <MinusIcon size={14} />
        </button>
      )}

      <div className="hesh-number-input__field">
        {prefix && <span className="hesh-number-input__prefix">{prefix}</span>}
        <input
          id={id}
          name={name}
          type="text"
          inputMode="decimal"
          role="spinbutton"
          aria-valuenow={currentValue}
          aria-valuemin={min}
          aria-valuemax={max}
          aria-invalid={invalid}
          aria-required={required}
          disabled={disabled}
          readOnly={readOnly}
          placeholder={placeholder}
          value={textValue}
          onChange={handleInputChange}
          onBlur={handleBlur}
          onKeyDown={handleKeyDown}
          className="hesh-number-input__input"
        />
        {suffix && <span className="hesh-number-input__suffix">{suffix}</span>}
      </div>

      {stepperPosition === 'split' ? (
        <button
          type="button"
          tabIndex={-1}
          disabled={disabled || readOnly || (max !== undefined && currentValue !== undefined && currentValue >= max)}
          onMouseDown={() => startStepping('up')}
          onMouseUp={stopStepping}
          onMouseLeave={stopStepping}
          aria-label="Increment"
          className="hesh-number-input__btn hesh-number-input__btn--split-right"
        >
          <PlusIcon size={14} />
        </button>
      ) : (
        <div className="hesh-number-input__steppers">
          <button
            type="button"
            tabIndex={-1}
            disabled={disabled || readOnly || (max !== undefined && currentValue !== undefined && currentValue >= max)}
            onMouseDown={() => startStepping('up')}
            onMouseUp={stopStepping}
            onMouseLeave={stopStepping}
            aria-label="Increment"
            className="hesh-number-input__stepper hesh-number-input__stepper--up"
          >
            <ChevronUpIcon size={12} />
          </button>
          <button
            type="button"
            tabIndex={-1}
            disabled={disabled || readOnly || (min !== undefined && currentValue !== undefined && currentValue <= min)}
            onMouseDown={() => startStepping('down')}
            onMouseUp={stopStepping}
            onMouseLeave={stopStepping}
            aria-label="Decrement"
            className="hesh-number-input__stepper hesh-number-input__stepper--down"
          >
            <ChevronDownIcon size={12} />
          </button>
        </div>
      )}
    </div>
  );
});

import React, {
  forwardRef,
  useRef,
  useState,
  useEffect,
  type KeyboardEvent,
  type ClipboardEvent,
  type ChangeEvent,
} from 'react';
import { cn } from '../utils/cn';

export interface OtpInputProps {
  /** Number of verification code slots. @default 6 */
  length?: number;
  /** Value of the code (controlled). */
  value?: string;
  /** Default value (uncontrolled). */
  defaultValue?: string;
  /** Callback fired whenever the entered code changes. */
  onChange?: (value: string) => void;
  /** Callback fired automatically when all slots are filled. */
  onComplete?: (value: string) => void;
  /** Input type allowed. @default 'numeric' */
  type?: 'numeric' | 'alphanumeric';
  /** Whether to mask the input for password/PIN privacy. @default false */
  mask?: boolean;
  /** Whether the inputs are disabled. */
  disabled?: boolean;
  /** Whether the field is in an invalid/error state. */
  invalid?: boolean;
  /** Accessible label for screen readers. @default 'Verification code' */
  'aria-label'?: string;
  /** Additional container CSS class. */
  className?: string;
}

/**
 * OtpInput provides a multi-digit input for 2FA, OTP, and PIN verification.
 * Automatically advances focus, supports copy-paste splitting, and provides full mobile responsiveness.
 */
export const OtpInput = forwardRef<HTMLDivElement, OtpInputProps>(
  (
    {
      length = 6,
      value: controlledValue,
      defaultValue = '',
      onChange,
      onComplete,
      type = 'numeric',
      mask = false,
      disabled = false,
      invalid = false,
      'aria-label': ariaLabel = 'Verification code',
      className,
    },
    ref
  ) => {
    const isControlled = controlledValue !== undefined;
    const [internalValue, setInternalValue] = useState(() => defaultValue.slice(0, length));
    const currentVal = isControlled ? controlledValue.slice(0, length) : internalValue;

    const inputRefs = useRef<(HTMLInputElement | null)[]>([]);

    const chars = Array.from({ length }, (_, i) => currentVal[i] || '');

    const isValidChar = (char: string) => {
      if (type === 'numeric') return /^[0-9]$/.test(char);
      return /^[a-zA-Z0-9]$/.test(char);
    };

    const updateValue = (newVal: string) => {
      if (!isControlled) {
        setInternalValue(newVal);
      }
      onChange?.(newVal);
      if (newVal.length === length) {
        onComplete?.(newVal);
      }
    };

    const handleChange = (e: ChangeEvent<HTMLInputElement>, index: number) => {
      const incoming = e.target.value;
      if (!incoming) return;

      const lastChar = incoming[incoming.length - 1] || '';
      if (!isValidChar(lastChar)) return;

      const newChars = [...chars];
      newChars[index] = lastChar;
      const joined = newChars.join('');
      updateValue(joined);

      // Advance to next slot if available
      if (index < length - 1) {
        inputRefs.current[index + 1]?.focus();
      }
    };

    const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>, index: number) => {
      if (e.key === 'Backspace') {
        e.preventDefault();
        const newChars = [...chars];

        if (newChars[index]) {
          newChars[index] = '';
          updateValue(newChars.join(''));
        } else if (index > 0) {
          newChars[index - 1] = '';
          updateValue(newChars.join(''));
          inputRefs.current[index - 1]?.focus();
        }
      } else if (e.key === 'ArrowLeft' && index > 0) {
        e.preventDefault();
        inputRefs.current[index - 1]?.focus();
      } else if (e.key === 'ArrowRight' && index < length - 1) {
        e.preventDefault();
        inputRefs.current[index + 1]?.focus();
      }
    };

    const handlePaste = (e: ClipboardEvent<HTMLInputElement>) => {
      e.preventDefault();
      const pasted = e.clipboardData.getData('text/plain').trim();
      const filtered = pasted
        .split('')
        .filter(isValidChar)
        .slice(0, length)
        .join('');

      if (!filtered) return;

      updateValue(filtered);

      const nextFocus = Math.min(filtered.length, length - 1);
      inputRefs.current[nextFocus]?.focus();
    };

    return (
      <div
        ref={ref}
        role="group"
        aria-label={ariaLabel}
        className={cn('pui-otp-input', invalid && 'pui-otp-input--invalid', className)}
      >
        {chars.map((char, i) => (
          <input
            key={i}
            ref={(el) => {
              inputRefs.current[i] = el;
            }}
            type={mask ? 'password' : 'text'}
            inputMode={type === 'numeric' ? 'numeric' : 'text'}
            pattern={type === 'numeric' ? '[0-9]*' : '[a-zA-Z0-9]*'}
            autoComplete="one-time-code"
            maxLength={1}
            value={char}
            disabled={disabled}
            aria-label={`Digit ${i + 1} of ${length}`}
            className={cn('pui-otp-slot', char && 'pui-otp-slot--filled')}
            onChange={(e) => handleChange(e, i)}
            onKeyDown={(e) => handleKeyDown(e, i)}
            onPaste={handlePaste}
            onFocus={(e) => e.target.select()}
          />
        ))}
      </div>
    );
  }
);

