      aria-label={title}
      {...rest}
    >
      <svg
        viewBox={`0 0 ${matrixSize} ${matrixSize}`}
        width={size}
        height={size}
        shapeRendering="crispEdges"
        style={{ display: 'block' }}
      >
        {bgColor !== 'transparent' && (
          <rect width={matrixSize} height={matrixSize} fill={bgColor} />
