} from 'react';
import { cn } from '../utils/cn';
import { StarIcon } from './icons';

export interface RatingProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange'> {
  /** Total number of rating items. @default 5 */
  count?: number;
  /** Current rating value (controlled). */
  value?: number;
  /** Default rating value (uncontrolled). @default 0 */
  defaultValue?: number;
  /** Precision allowed: full stars (1) or half stars (0.5). @default 1 */
  precision?: 1 | 0.5;
  /** Callback fired when rating changes. */
  onChange?: (value: number) => void;
  /** Whether the rating is read-only. @default false */
  readOnly?: boolean;
  /** Whether the rating is disabled. @default false */
  disabled?: boolean;
  /** Sizing of the rating icons. @default 'md' */
  size?: 'sm' | 'md' | 'lg';
  /** Custom icon generator. Defaults to StarIcon. */
  icon?: (filled: boolean, value: number) => ReactNode;
}

const SIZE_MAP = {
  sm: 16,
  md: 20,
  lg: 26,
};

/**
 * Rating displays interactive or read-only star reviews.
 * Supports half-star precision, hover preview, and full keyboard navigation.
 */
export const Rating = forwardRef<HTMLDivElement, RatingProps>(
  (
    {
      count = 5,
      value: controlledValue,
      defaultValue = 0,
      precision = 1,
      onChange,
      readOnly = false,
      disabled = false,
      size = 'md',
      icon,
      className,
      ...props
    },
    ref
  ) => {
    const isControlled = controlledValue !== undefined;
    const [internalValue, setInternalValue] = useState(defaultValue);
    const [hoverValue, setHoverValue] = useState<number | null>(null);

    const currentValue = isControlled ? controlledValue : internalValue;
    const displayValue = hoverValue !== null ? hoverValue : currentValue;

    const safeCount = Math.max(1, Math.min(20, Math.floor(count || 5)));
    const safeCurrentValue = typeof currentValue === 'number' && !isNaN(currentValue) ? currentValue : 0;
    const safeDisplayValue = typeof displayValue === 'number' && !isNaN(displayValue) ? displayValue : 0;

    const iconSize = SIZE_MAP[size] ?? SIZE_MAP.md;

    const setValue = (newVal: number) => {
      if (readOnly || disabled) return;
      if (!isControlled) {
        setInternalValue(newVal);
      }
      onChange?.(newVal);
    };

    const handleMouseMove = (e: MouseEvent<HTMLSpanElement>, index: number) => {
      if (readOnly || disabled) return;
      const rect = e.currentTarget.getBoundingClientRect();
      const isLeftHalf = e.clientX - rect.left < rect.width / 2;
      const starVal = index + 1;
      const calculatedVal = precision === 0.5 && isLeftHalf ? starVal - 0.5 : starVal;
      setHoverValue(calculatedVal);
    };

    const handleClick = (e: MouseEvent<HTMLSpanElement>, index: number) => {
      if (readOnly || disabled) return;
      const rect = e.currentTarget.getBoundingClientRect();
      const isLeftHalf = e.clientX - rect.left < rect.width / 2;
      const starVal = index + 1;
      const calculatedVal = precision === 0.5 && isLeftHalf ? starVal - 0.5 : starVal;
      setValue(calculatedVal);
    };

    const handleKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
      if (readOnly || disabled) return;

      const step = precision;
      if (e.key === 'ArrowRight' || e.key === 'ArrowUp') {
        e.preventDefault();
        setValue(Math.min(safeCount, Number((safeCurrentValue + step).toFixed(1))));
      } else if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') {
        e.preventDefault();
        setValue(Math.max(0, Number((safeCurrentValue - step).toFixed(1))));
      } else if (e.key === 'Home') {
        e.preventDefault();
        setValue(0);
      } else if (e.key === 'End') {
        e.preventDefault();
        setValue(safeCount);
      }
    };

    return (
      <div
        ref={ref}
        role={readOnly ? 'img' : 'slider'}
        aria-label={readOnly ? `Rated ${safeCurrentValue} out of ${safeCount} stars` : 'Rating'}
        aria-valuemin={0}
        aria-valuemax={safeCount}
        aria-valuenow={safeCurrentValue}
        tabIndex={disabled || readOnly ? -1 : 0}
        onKeyDown={handleKeyDown}
        onMouseLeave={() => setHoverValue(null)}
        className={cn(
          'pui-rating',
          `pui-rating--${size}`,
          readOnly && 'pui-rating--readonly',
          disabled && 'pui-rating--disabled',
          className
        )}
        {...props}
      >
        {Array.from({ length: safeCount }, (_, i) => {
          const starIndex = i + 1;
          const fillRatio = Math.max(0, Math.min(1, safeDisplayValue - i));

          return (
            <span
              key={i}
              className={cn(
                'pui-rating__star',
                fillRatio === 1 && 'pui-rating__star--full',
                fillRatio > 0 && fillRatio < 1 && 'pui-rating__star--half',
                fillRatio === 0 && 'pui-rating__star--empty'
              )}
              onMouseMove={(e) => handleMouseMove(e, i)}
              onClick={(e) => handleClick(e, i)}
            >
              {icon ? (
                icon(fillRatio > 0, starIndex)
              ) : (
                <span className="pui-rating__star-inner" style={{ width: iconSize, height: iconSize }}>
                  {/* Background base outline star */}
                  <span className="pui-rating__star-base">
                    <StarIcon size={iconSize} />
                  </span>
                  {/* Filled star foreground clipped to fillRatio */}
                  <span
                    className="pui-rating__star-fill"
                    style={{ width: `${fillRatio * 100}%` }}
                    aria-hidden="true"
                  >
                    <StarIcon size={iconSize} />
                  </span>
                </span>
              )}
            </span>
          );
        })}
        <span className="pui-rating__value-label" aria-hidden="true">
          {displayValue > 0 ? displayValue.toFixed(precision === 0.5 ? 1 : 0) : ''}
        </span>
      </div>
    );
  }
);

Rating.displayName = 'Rating';

import {
  createContext,
  forwardRef,
  useContext,
  useRef,
  useState,
  useCallback,
  type HTMLAttributes,
  type ReactNode,
  type MouseEvent as ReactMouseEvent,
} from 'react';
import { cn } from '../utils/cn';

interface ResizableContextValue {
  direction: 'horizontal' | 'vertical';
  isDragging: boolean;
  startDragging: (index: number) => void;
}

const ResizableContext = createContext<ResizableContextValue | null>(null);

export interface ResizablePanelGroupProps extends HTMLAttributes<HTMLDivElement> {
  /** Layout direction: 'horizontal' or 'vertical'. @default 'horizontal' */
  direction?: 'horizontal' | 'vertical';
  children: ReactNode;
}

/**
 * ResizablePanelGroup manages flexible, draggable split panels.
 */
export const ResizablePanelGroup = forwardRef<HTMLDivElement, ResizablePanelGroupProps>(
  function ResizablePanelGroup({ direction = 'horizontal', className, children, ...props }, ref) {
    const containerRef = useRef<HTMLDivElement | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const activeHandleRef = useRef<number | null>(null);

    const startDragging = useCallback((handleIndex: number) => {
      setIsDragging(true);
      activeHandleRef.current = handleIndex;

      const handleMouseMove = (e: globalThis.MouseEvent) => {
        if (!containerRef.current || activeHandleRef.current === null) return;
        const rect = containerRef.current.getBoundingClientRect();

        const panels = Array.from(
          containerRef.current.querySelectorAll<HTMLElement>(':scope > .pui-resizable__panel')
        );
        const idx = activeHandleRef.current;
        if (!panels[idx] || !panels[idx + 1]) return;

        let deltaPercentage: number;
        if (direction === 'horizontal') {
          const totalWidth = rect.width;
          const currentX = e.clientX - rect.left;
          deltaPercentage = Math.max(15, Math.min(85, (currentX / totalWidth) * 100));
        } else {
          const totalHeight = rect.height;
          const currentY = e.clientY - rect.top;
          deltaPercentage = Math.max(15, Math.min(85, (currentY / totalHeight) * 100));
        }

        const p1 = panels[idx];
        const p2 = panels[idx + 1];
        if (p1 && p2) {
          p1.style.flex = `${deltaPercentage} 1 0%`;
          p2.style.flex = `${100 - deltaPercentage} 1 0%`;
        }
      };

      const handleMouseUp = () => {
        setIsDragging(false);
        activeHandleRef.current = null;
        window.removeEventListener('mousemove', handleMouseMove);
        window.removeEventListener('mouseup', handleMouseUp);
      };

      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }, [direction]);

    return (
      <ResizableContext.Provider value={{ direction, isDragging, startDragging }}>
        <div
          ref={(node) => {
            containerRef.current = node;
            if (typeof ref === 'function') ref(node);
            else if (ref) (ref as any).current = node;
          }}
          className={cn(
            'pui-resizable',
            `pui-resizable--${direction}`,
            isDragging && 'pui-resizable--dragging',
            className
          )}
          {...props}
        >
          {children}
        </div>
      </ResizableContext.Provider>
    );
  }
);

ResizablePanelGroup.displayName = 'ResizablePanelGroup';

export interface ResizablePanelProps extends HTMLAttributes<HTMLDivElement> {
  /** Initial flex percentage (1-100). @default 50 */
  defaultSize?: number;
  /** Minimum flex percentage. @default 15 */
  minSize?: number;
  /** Maximum flex percentage. @default 85 */
  maxSize?: number;
  children?: ReactNode;
}

export const ResizablePanel = forwardRef<HTMLDivElement, ResizablePanelProps>(
  function ResizablePanel({ defaultSize = 50, minSize = 15, maxSize = 85, className, children, style, ...props }, ref) {
    return (
      <div
        ref={ref}
        className={cn('pui-resizable__panel', className)}
        style={{
          flex: `${defaultSize} 1 0%`,
          ...style,
        }}
        {...props}
      >
