  showTooltip = false,
  formatTooltip = (v) => v,
  size = 'md',
  disabled = false,
  label,
  className,
}: SliderProps) {
  const [current, setCurrent] = useControllableState<number>({
    value,
    defaultValue,
    onChange: onValueChange,
  });
  const [dragging, setDragging] = useState(false);

  const pct = Math.min(100, Math.max(0, ((current - min) / (max - min || 1)) * 100));

  return (
    <div
      className={cn('pui-slider', `pui-slider--${size}`, className)}
      data-dragging={dragging || undefined}
      aria-disabled={disabled || undefined}
    >
      <div className="pui-slider__track">
        <div className="pui-slider__range" style={{ insetInlineStart: 0, width: `${pct}%` }} />
        {marks?.map((mark) => {
          const markPct = Math.min(100, Math.max(0, ((mark.value - min) / (max - min || 1)) * 100));
          return (
            <div
              key={mark.value}
              className="pui-slider__mark"
              data-active={mark.value <= current || undefined}
              style={{ left: `${markPct}%` }}
            />
          );
        })}
      </div>

      <div className="pui-slider__thumb" style={{ insetInlineStart: `${pct}%` }} aria-hidden="true">
        {showTooltip && (
          <div className="pui-slider__tooltip">
            {formatTooltip(current)}
          </div>
        )}
      </div>

      {marks?.map((mark) => {
        if (!mark.label) return null;
        const markPct = Math.min(100, Math.max(0, ((mark.value - min) / (max - min || 1)) * 100));
        return (
          <div
            key={`lbl-${mark.value}`}
            className="pui-slider__mark-label"
            style={{ left: `${markPct}%` }}
          >
            {mark.label}
          </div>
        );
      })}

      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={current}
        disabled={disabled}
        aria-label={label}
        aria-valuetext={label ? undefined : String(current)}
        onChange={(event) => setCurrent(Number(event.target.value))}
        onPointerDown={() => setDragging(true)}
        onPointerUp={() => setDragging(false)}
        onBlur={() => setDragging(false)}
        style={{
          position: 'absolute',
          inset: 0,
          width: '100%',
          height: '100%',
          opacity: 0,
          cursor: disabled ? 'not-allowed' : 'pointer',
          margin: 0,
          zIndex: 3,
        }}
      />
    </div>
  );
}

/**
 * Dual-thumb RangeSlider for min/max intervals (e.g., pricing filters).
 */
export function RangeSlider({
  value,
  defaultValue = [20, 80],
  onValueChange,
  min = 0,
  max = 100,
  step = 1,
  marks,
  showTooltip = false,
  formatTooltip = (v) => v,
  size = 'md',
  disabled = false,
  label,
  className,
}: RangeSliderProps) {
  const [current, setCurrent] = useControllableState<[number, number]>({
    value,
    defaultValue,
    onChange: onValueChange,
  });
  const [dragging, setDragging] = useState<'min' | 'max' | null>(null);

  const minPct = Math.min(100, Math.max(0, ((current[0] - min) / (max - min || 1)) * 100));
  const maxPct = Math.min(100, Math.max(0, ((current[1] - min) / (max - min || 1)) * 100));

  const handleMinChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = Math.min(Number(e.target.value), current[1] - step);
    setCurrent([val, current[1]]);
  };

  const handleMaxChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = Math.max(Number(e.target.value), current[0] + step);
    setCurrent([current[0], val]);
  };

  return (
    <div
      className={cn('pui-slider', `pui-slider--${size}`, className)}
      data-dragging={Boolean(dragging) || undefined}
      aria-disabled={disabled || undefined}
      style={{ position: 'relative' }}
    >
      <div className="pui-slider__track">
        <div
          className="pui-slider__range"
          style={{ insetInlineStart: `${minPct}%`, width: `${maxPct - minPct}%` }}
        />
        {marks?.map((mark) => {
          const markPct = Math.min(100, Math.max(0, ((mark.value - min) / (max - min || 1)) * 100));
          const inRange = mark.value >= current[0] && mark.value <= current[1];
          return (
            <div
              key={mark.value}
              className="pui-slider__mark"
              data-active={inRange || undefined}
              style={{ left: `${markPct}%` }}
            />
          );
        })}
      </div>

      {/* Min Thumb */}
      <div
        className="pui-slider__thumb"
        style={{ insetInlineStart: `${minPct}%` }}
        aria-hidden="true"
      >
        {showTooltip && (
          <div className="pui-slider__tooltip">
            {formatTooltip(current[0])}
          </div>
        )}
      </div>

      {/* Max Thumb */}
      <div
        className="pui-slider__thumb"
        style={{ insetInlineStart: `${maxPct}%` }}
        aria-hidden="true"
      >
        {showTooltip && (
          <div className="pui-slider__tooltip">
            {formatTooltip(current[1])}
          </div>
        )}
      </div>

      {marks?.map((mark) => {
        if (!mark.label) return null;
        const markPct = Math.min(100, Math.max(0, ((mark.value - min) / (max - min || 1)) * 100));
        return (
          <div
            key={`lbl-${mark.value}`}
            className="pui-slider__mark-label"
            style={{ left: `${markPct}%` }}
          >
            {mark.label}
          </div>
        );
      })}

      {/* Native Min Input */}
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={current[0]}
        disabled={disabled}
        aria-label={label ? `${label} minimum` : 'Minimum value'}
        onChange={handleMinChange}
        onPointerDown={() => setDragging('min')}
        onPointerUp={() => setDragging(null)}
        onBlur={() => setDragging(null)}
        style={{
          position: 'absolute',
          inset: 0,
          width: '100%',
          height: '100%',
          opacity: 0,
          cursor: disabled ? 'not-allowed' : 'pointer',
          margin: 0,
          zIndex: current[0] > max - 10 ? 5 : 3,
        }}
      />

      {/* Native Max Input */}
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={current[1]}
        disabled={disabled}
        aria-label={label ? `${label} maximum` : 'Maximum value'}
        onChange={handleMaxChange}
        onPointerDown={() => setDragging('max')}
        onPointerUp={() => setDragging(null)}
        onBlur={() => setDragging(null)}
        style={{
          position: 'absolute',
          inset: 0,
          width: '100%',
          height: '100%',
          opacity: 0,
          cursor: disabled ? 'not-allowed' : 'pointer',
          margin: 0,
          zIndex: 4,
        }}
      />
    </div>
  );
}

import React, {
  forwardRef,
  useRef,
  type ReactNode,
  type HTMLAttributes,
  type ButtonHTMLAttributes,
} from 'react';
import { useControllableState } from '../hooks/useControllableState';
import { useDismiss } from '../hooks/useDismiss';
import { PlusIcon } from './icons';
import { cn } from '../utils/cn';

export interface SpeedDialActionSpec {
  icon: ReactNode;
  label: ReactNode;
  onClick?: () => void;
  tone?: 'neutral' | 'primary' | 'danger';
  disabled?: boolean;
}

export interface SpeedDialProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange'> {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  direction?: 'up' | 'down' | 'left' | 'right';
  position?: 'bottom-right' | 'bottom-left' | 'top-right' | 'top-left' | 'relative';
  icon?: ReactNode;
  activeIcon?: ReactNode;
  label?: string;
  actions?: SpeedDialActionSpec[];
  children?: ReactNode;
}

export const SpeedDial = forwardRef<HTMLDivElement, SpeedDialProps>(function SpeedDial(
  {
    open: controlledOpen,
    defaultOpen = false,
    onOpenChange,
    direction = 'up',
    position = 'relative',
    icon = <PlusIcon size={20} />,
    activeIcon,
    label = 'Speed dial actions',
    actions = [],
    children,
    className,
    ...props
  },
  ref
) {
  const [isOpen, setIsOpen] = useControllableState<boolean>({
    value: controlledOpen,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  });

  const rootRef = useRef<HTMLDivElement | null>(null);

  useDismiss(rootRef, isOpen, () => setIsOpen(false));

  const toggleOpen = () => {
    setIsOpen(!isOpen);
  };

  return (
    <div
      ref={(node) => {
        rootRef.current = node;
        if (typeof ref === 'function') ref(node);
        else if (ref) ref.current = node;
      }}
      className={cn(
        'hesh-speed-dial',
        `hesh-speed-dial--${direction}`,
        position !== 'relative' && `hesh-speed-dial--${position}`,
        isOpen && 'hesh-speed-dial--open',
        className
      )}
      {...props}
    >
      {/* Expanded Actions List */}
      <div
        className={cn(
          'hesh-speed-dial__actions',
          `hesh-speed-dial__actions--${direction}`,
          isOpen && 'hesh-speed-dial__actions--visible'
        )}
        role="menu"
        aria-hidden={!isOpen}
      >
        {actions.map((act, idx) => (
          <div
            key={idx}
            className="hesh-speed-dial__action-row"
            style={{ '--action-index': idx } as React.CSSProperties}
          >
            {act.label && (
              <span className="hesh-speed-dial__label" id={`speed-dial-label-${idx}`}>
                {act.label}
              </span>
            )}
            <button
              type="button"
              role="menuitem"
              disabled={act.disabled}
              aria-labelledby={act.label ? `speed-dial-label-${idx}` : undefined}
              aria-label={typeof act.label === 'string' ? act.label : undefined}
              className={cn(
                'hesh-speed-dial__action-btn',
                act.tone && `hesh-speed-dial__action-btn--${act.tone}`
              )}
              onClick={() => {
                act.onClick?.();
                setIsOpen(false);
              }}
            >
              {act.icon}
            </button>
          </div>
        ))}
        {children}
      </div>

      {/* Main Trigger FAB */}
      <button
        type="button"
        aria-label={label}
        aria-expanded={isOpen}
        aria-haspopup="menu"
        onClick={toggleOpen}
        className={cn(
          'hesh-speed-dial__trigger',
          isOpen && 'hesh-speed-dial__trigger--active'
        )}
      >
        <span
          className={cn(
            'hesh-speed-dial__icon-holder',
            isOpen && !activeIcon && 'hesh-speed-dial__icon-holder--rotated'
          )}
        >
          {isOpen && activeIcon ? activeIcon : icon}
        </span>
      </button>
    </div>
  );
});

import React, { forwardRef, type HTMLAttributes, type ReactNode } from 'react';
import { cn } from '../utils/cn';
import { CheckIcon } from './icons';

export interface StepItem {
  /** Title of the step. */
  title: ReactNode;
  /** Optional secondary subtitle or explanation. */
  description?: ReactNode;
  /** Optional custom step icon. */
  icon?: ReactNode;
  /** Optional custom status override. */
  status?: 'completed' | 'current' | 'upcoming' | 'error';
  /** Whether this individual step is disabled for click navigation. */
  disabled?: boolean;
}

export interface StepperProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange'> {
  /** Array of step definitions. */
  steps: readonly StepItem[];
  /** Zero-based index of the currently active step. */
  current: number;
  /** Callback fired when a step indicator is clicked. */
  onChange?: (stepIndex: number) => void;
  /** Layout orientation. @default 'horizontal' */
  orientation?: 'horizontal' | 'vertical';
  /** Size variant. @default 'md' */
  size?: 'sm' | 'md' | 'lg';
}

/**
 * Stepper displays a sequence of numbered or icon stages in a multi-step workflow.
 * Completely responsive across vertical and horizontal configurations for mobile and desktop.
 */
export const Stepper = forwardRef<HTMLDivElement, StepperProps>(
  (
    {
      steps,
      current,
      onChange,
      orientation = 'horizontal',
      size = 'md',
      className,
      ...props
    },
    ref
  ) => {
    return (
      <nav
        ref={ref}
        aria-label="Progress"
        className={cn(
          'pui-stepper',
          `pui-stepper--${orientation}`,
          `pui-stepper--${size}`,
          className
        )}
        {...props}
      >
        <ol className="pui-stepper__list">
          {steps.map((step, idx) => {
            const isClickable = Boolean(onChange && !step.disabled && idx <= current);
            const status =
              step.status ||
              (idx < current ? 'completed' : idx === current ? 'current' : 'upcoming');
            const isCompleted = idx < current || step.status === 'completed';

            return (
              <React.Fragment key={idx}>
                <li
                  className={cn('pui-stepper__item', `pui-stepper__item--${status}`)}
                  aria-current={status === 'current' ? 'step' : undefined}
                >
                  <button
                    type="button"
                    disabled={!isClickable}
                    className={cn(
                      'pui-stepper__button',
                      isClickable && 'pui-stepper__button--clickable'
                    )}
                    onClick={() => isClickable && onChange?.(idx)}
                  >
                    <span className="pui-stepper__indicator" aria-hidden="true">
                      {status === 'completed' ? (
                        step.icon || <CheckIcon size={14} />
                      ) : (
                        step.icon || <span className="pui-stepper__number">{idx + 1}</span>
                      )}
                    </span>

                    <span className="pui-stepper__content">
                      <span className="pui-stepper__title">{step.title}</span>
                      {step.description && (
                        <span className="pui-stepper__description">{step.description}</span>
                      )}
                    </span>
                  </button>
                </li>

                {idx < steps.length - 1 && (
                  <li
                    className={cn(
                      'pui-stepper__connector-item',
                      isCompleted && 'pui-stepper__connector-item--active'
                    )}
                    aria-hidden="true"
                  >
                    <div className="pui-stepper__connector" />
                  </li>
                )}
              </React.Fragment>
            );
          })}
        </ol>
      </nav>
    );
  }
);

Stepper.displayName = 'Stepper';

'use client';

import {
  createContext,
  useCallback,
  useContext,
  useId,
  useRef,
  type ButtonHTMLAttributes,
  type HTMLAttributes,
  type KeyboardEvent,
  type ReactNode,
} from 'react';
import { cn } from '../utils/cn';
import { useControllableState } from '../hooks/useControllableState';

export interface TabItem {
  value: string;
  label: ReactNode;
  content?: ReactNode;
  disabled?: boolean;
  /** Small trailing pill, e.g. an unread count. */
  count?: number | string;
  icon?: ReactNode;
}

export type TabsVariant = 'line' | 'pills' | 'boxed';
export type TabsSize = 'sm' | 'md' | 'lg';

export interface TabsProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange'> {
  /** Optional array of tab items for config-driven rendering. */
  items?: readonly TabItem[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  orientation?: 'horizontal' | 'vertical';
  variant?: TabsVariant;
  size?: TabsSize;
  fullWidth?: boolean;
  /** Skip rendering inactive panels. Use for expensive or stateful content. */
  lazy?: boolean;
  children?: ReactNode;
}

interface TabsContextValue {
  value: string;
  select: (value: string) => void;
  baseId: string;
  registerRef: (value: string, node: HTMLButtonElement | null) => void;
  registeredValues: string[];
  registerValue: (value: string) => void;
  unregisterValue: (value: string) => void;
  orientation: 'horizontal' | 'vertical';
  variant: TabsVariant;
  size: TabsSize;
  fullWidth: boolean;
  lazy: boolean;
}

const TabsContext = createContext<TabsContextValue | null>(null);

export function useTabsContext() {
  const context = useContext(TabsContext);
  if (!context) throw new Error('Tab components must be used inside <Tabs>.');
  return context;
}

/* ---------------------------------------------------------------- Compound Components */

export interface TabsListProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
}

export function TabsList({ className, children, ...props }: TabsListProps) {
  const { orientation, variant, registeredValues, value, select } = useTabsContext();
  const listRef = useRef<HTMLDivElement>(null);

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (registeredValues.length === 0) return;

    const currentIndex = registeredValues.indexOf(value);
    const nextKey = orientation === 'horizontal' ? 'ArrowRight' : 'ArrowDown';
    const prevKey = orientation === 'horizontal' ? 'ArrowLeft' : 'ArrowUp';

    let target: string | undefined;

    if (event.key === nextKey) {
      target = registeredValues[(currentIndex + 1) % registeredValues.length];
    } else if (event.key === prevKey) {
      target = registeredValues[(currentIndex - 1 + registeredValues.length) % registeredValues.length];
    } else if (event.key === 'Home') {
      target = registeredValues[0];
    } else if (event.key === 'End') {
      target = registeredValues[registeredValues.length - 1];
    }

    if (target) {
      event.preventDefault();
      select(target);
      const targetBtn = listRef.current?.querySelector<HTMLButtonElement>(`[data-tab-value="${target}"]`);
      targetBtn?.focus();
    }
  };

  return (
    <div
      ref={listRef}
      role="tablist"
      aria-orientation={orientation}
      className={cn('pui-tabs__list', `pui-tabs__list--${variant}`, className)}
      onKeyDown={onKeyDown}
      {...props}
    >
      {children}
    </div>
  );
}

export interface TabsTriggerProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  value: string;
  icon?: ReactNode;
  count?: number | string;
  children?: ReactNode;
}

export function TabsTrigger({
  value,
  icon,
  count,
  className,
  disabled,
  children,
  ...props
}: TabsTriggerProps) {
  const { value: selected, select, baseId, registerRef, registerValue, unregisterValue, variant, size, fullWidth } =
    useTabsContext();

  const isActive = selected === value;

  return (
    <button
      ref={(node) => {
        registerRef(value, node);
        if (node) registerValue(value);
        else unregisterValue(value);
      }}
      type="button"
      role="tab"
      id={`${baseId}-tab-${value}`}
      data-tab-value={value}
      aria-selected={isActive}
      aria-controls={`${baseId}-panel-${value}`}
      tabIndex={isActive ? 0 : -1}
      disabled={disabled}
      className={cn(
        'pui-tab',
        `pui-tab--${variant}`,
        `pui-tab--${size}`,
        fullWidth && 'pui-tab--full-width',
        className
      )}
      onClick={() => select(value)}
      {...props}
    >
      {icon && <span className="pui-btn__icon">{icon}</span>}
      {children}
      {count !== undefined && <span className="pui-tab__count">{count}</span>}
    </button>
  );
}

export interface TabsContentProps extends HTMLAttributes<HTMLDivElement> {
  value: string;
  children?: ReactNode;
}

export function TabsContent({ value, className, children, ...props }: TabsContentProps) {
  const { value: selected, baseId, lazy } = useTabsContext();
  const isActive = selected === value;

  if (lazy && !isActive) return null;

  return (
    <div
      role="tabpanel"
      id={`${baseId}-panel-${value}`}
      aria-labelledby={`${baseId}-tab-${value}`}
      hidden={!isActive}
      tabIndex={0}
      className={cn('pui-tabs__panel', className)}
      {...props}
    >
      {children}
    </div>
  );
}

/* ---------------------------------------------------------------- Main Tabs */

export function Tabs({
  items,
  value,
  defaultValue,
  onValueChange,
  orientation = 'horizontal',
  variant = 'line',
  size = 'md',
  fullWidth = false,
  lazy = false,
  className,
  children,
  ...props
}: TabsProps) {
  const initialValue = defaultValue ?? (items && items[0] ? items[0].value : '');
  const [selected, setSelected] = useControllableState<string>({
    value,
    defaultValue: initialValue,
    onChange: onValueChange,
  });

  const baseId = useId();
  const refs = useRef(new Map<string, HTMLButtonElement | null>());
  const registeredValuesRef = useRef<string[]>([]);

  const registerRef = useCallback((tabValue: string, node: HTMLButtonElement | null) => {
    if (node) refs.current.set(tabValue, node);
    else refs.current.delete(tabValue);
  }, []);

  const registerValue = useCallback((tabValue: string) => {
    if (!registeredValuesRef.current.includes(tabValue)) {
      registeredValuesRef.current.push(tabValue);
    }
  }, []);

  const unregisterValue = useCallback((tabValue: string) => {
    registeredValuesRef.current = registeredValuesRef.current.filter((v) => v !== tabValue);
  }, []);

  const select = useCallback(
    (next: string) => {
      if (items?.find((item) => item.value === next)?.disabled) return;
      setSelected(next);
    },
    [items, setSelected]
  );

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (!items) return;
    const enabled = items.filter((item) => !item.disabled);
    if (enabled.length === 0) return;

    const currentIndex = enabled.findIndex((item) => item.value === selected);
    const nextKey = orientation === 'horizontal' ? 'ArrowRight' : 'ArrowDown';
    const prevKey = orientation === 'horizontal' ? 'ArrowLeft' : 'ArrowUp';

    let target: string | undefined;

    if (event.key === nextKey) {
      target = enabled[(currentIndex + 1) % enabled.length]?.value;
    } else if (event.key === prevKey) {
      target = enabled[(currentIndex - 1 + enabled.length) % enabled.length]?.value;
    } else if (event.key === 'Home') {
      target = enabled[0]?.value;
    } else if (event.key === 'End') {
      target = enabled[enabled.length - 1]?.value;
    }

    if (target) {
      event.preventDefault();
      select(target);
      refs.current.get(target)?.focus();
    }
  };

  const contextValue: TabsContextValue = {
    value: selected,
    select,
    baseId,
    registerRef,
    registeredValues: registeredValuesRef.current,
    registerValue,
    unregisterValue,
    orientation,
    variant,
    size,
    fullWidth,
    lazy,
  };

  return (
    <TabsContext.Provider value={contextValue}>
      <div
        className={cn(
          'pui-tabs',
          orientation === 'vertical' && 'pui-tabs--vertical',
          `pui-tabs--${variant}`,
          `pui-tabs--${size}`,
          fullWidth && 'pui-tabs--full-width',
          className
        )}
        {...props}
      >
        {items ? (
          <>
            <div
              role="tablist"
              aria-orientation={orientation}
              className={cn('pui-tabs__list', `pui-tabs__list--${variant}`)}
              onKeyDown={onKeyDown}
            >
              {items.map((item) => {
                const isActive = item.value === selected;
                return (
                  <button
                    key={item.value}
                    ref={(node) => registerRef(item.value, node)}
                    type="button"
                    role="tab"
                    id={`${baseId}-tab-${item.value}`}
                    aria-selected={isActive}
                    aria-controls={`${baseId}-panel-${item.value}`}
                    tabIndex={isActive ? 0 : -1}
                    disabled={item.disabled}
                    className={cn(
                      'pui-tab',
                      `pui-tab--${variant}`,
                      `pui-tab--${size}`,
                      fullWidth && 'pui-tab--full-width'
                    )}
                    onClick={() => select(item.value)}
                  >
                    {item.icon && <span className="pui-btn__icon">{item.icon}</span>}
                    {item.label}
                    {item.count !== undefined && <span className="pui-tab__count">{item.count}</span>}
                  </button>
                );
              })}
            </div>

            {items.map((item) => {
              const isActive = item.value === selected;
              if (lazy && !isActive) return null;
              return (
                <div
                  key={item.value}
                  role="tabpanel"
                  id={`${baseId}-panel-${item.value}`}
                  aria-labelledby={`${baseId}-tab-${item.value}`}
                  hidden={!isActive}
                  tabIndex={0}
                  className="pui-tabs__panel"
                >
                  {item.content}
                </div>
              );
            })}
          </>
        ) : (
          children
        )}
      </div>
    </TabsContext.Provider>
  );
}

