'use client';

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { cn } from '../utils/cn';
import { Portal } from './Portal';
import {
  AlertCircleIcon,
  AlertTriangleIcon,
  CheckCircleIcon,
  InfoIcon,
  XIcon,
} from './icons';

export type ToastTone = 'info' | 'success' | 'warning' | 'danger';

export interface ToastOptions {
  title: ReactNode;
  description?: ReactNode;
  tone?: ToastTone;
  /** Milliseconds before auto-dismiss. Pass 0 to keep it open. */
  duration?: number;
  action?: ReactNode;
}

export type ToastInput = ReactNode | ToastOptions;

export interface ToastPromiseOptions<T> {
  loading: ReactNode | ToastOptions;
  success: ReactNode | ToastOptions | ((data: T) => ReactNode | ToastOptions);
  error: ReactNode | ToastOptions | ((err: unknown) => ReactNode | ToastOptions);
}

export interface ToastFunction {
  (input: ToastInput): number;
  info: (input: ToastInput, description?: ReactNode) => number;
  success: (input: ToastInput, description?: ReactNode) => number;
  warning: (input: ToastInput, description?: ReactNode) => number;
  danger: (input: ToastInput, description?: ReactNode) => number;
  error: (input: ToastInput, description?: ReactNode) => number;
  dismiss: (id: number) => void;
  update: (id: number, options: Partial<ToastOptions>) => void;
  promise: <T>(
    promise: Promise<T> | (() => Promise<T>),
    options: ToastPromiseOptions<T>
  ) => Promise<T>;
}

export interface ToastContextValue {
  toast: ToastFunction;
  dismiss: (id: number) => void;
}

interface ToastRecord extends ToastOptions {
  id: number;
  leaving?: boolean;
}

const ToastContext = createContext<ToastContextValue | null>(null);

const TONE_ICONS: Record<ToastTone, typeof InfoIcon> = {
  info: InfoIcon,
  success: CheckCircleIcon,
  warning: AlertTriangleIcon,
  danger: AlertCircleIcon,
};

export type ToastPlacement = 'bottom-right' | 'top-right' | 'bottom-left' | 'top-center';

export interface ToastProviderProps {
  children: ReactNode;
  placement?: ToastPlacement;
  /** Default lifetime for toasts that do not specify one. */
  duration?: number;
  /** Maximum simultaneous toasts; oldest are dropped first. */
  limit?: number;
}

function isToastOptions(input: unknown): input is ToastOptions {
  return typeof input === 'object' && input !== null && 'title' in input;
}

function normalizeInput(
  input: ToastInput,
  defaultTone: ToastTone = 'info',
  description?: ReactNode
): ToastOptions {
  if (isToastOptions(input)) {
    return {
      tone: defaultTone,
      ...input,
      description: description ?? input.description,
    };
  }
  return {
    title: input as ReactNode,
    description,
    tone: defaultTone,
  };
}

let activeToastFn: ToastFunction | null = null;
let activeDismissFn: ((id: number) => void) | null = null;

/**
 * Imperative standalone toast dispatcher.
 * Can be used anywhere, including outside React components (e.g., API clients, event listeners).
 */
export const toast: ToastFunction = Object.assign(
  (input: ToastInput) => {
    if (activeToastFn) return activeToastFn(input);
    console.warn('[hesh-ui] toast() was called before <ToastProvider> was mounted.');
    return -1;
  },
  {
    info: (input: ToastInput, desc?: ReactNode) =>
      activeToastFn ? activeToastFn.info(input, desc) : -1,
    success: (input: ToastInput, desc?: ReactNode) =>
      activeToastFn ? activeToastFn.success(input, desc) : -1,
    warning: (input: ToastInput, desc?: ReactNode) =>
      activeToastFn ? activeToastFn.warning(input, desc) : -1,
    danger: (input: ToastInput, desc?: ReactNode) =>
      activeToastFn ? activeToastFn.danger(input, desc) : -1,
    error: (input: ToastInput, desc?: ReactNode) =>
      activeToastFn ? activeToastFn.error(input, desc) : -1,
    dismiss: (id: number) => {
      if (activeDismissFn) activeDismissFn(id);
    },
    update: (id: number, options: Partial<ToastOptions>) => {
      if (activeToastFn) activeToastFn.update(id, options);
    },
    promise: <T,>(
      promise: Promise<T> | (() => Promise<T>),
      options: ToastPromiseOptions<T>
    ): Promise<T> => {
      if (activeToastFn) return activeToastFn.promise(promise, options);
      return typeof promise === 'function' ? promise() : promise;
    },
  }
);

/**
 * Toast host. Mount once near the root; call `useToast().toast()` or `toast.success()` anywhere.
 *
 * The live region is `role="status"` / `aria-live="polite"`, so messages are
 * announced without stealing focus. Interruptive tones switch to
 * `aria-live="assertive"` because dropping them silently would be worse.
 */
export function ToastProvider({
  children,
  placement = 'bottom-right',
  duration = 4500,
  limit = 3,
}: ToastProviderProps) {
  const [toasts, setToasts] = useState<ToastRecord[]>([]);
  const nextId = useRef(1);
  const timers = useRef(new Map<number, number>());

  const dismiss = useCallback((id: number) => {
    setToasts((prev) => prev.map((t) => (t.id === id ? { ...t, leaving: true } : t)));
    window.setTimeout(() => setToasts((prev) => prev.filter((t) => t.id !== id)), 180);

    const timer = timers.current.get(id);
    if (timer) {
      window.clearTimeout(timer);
      timers.current.delete(id);
    }
  }, []);

  const update = useCallback(
    (id: number, updates: Partial<ToastOptions>) => {
      setToasts((prev) =>
        prev.map((t) => {
          if (t.id !== id) return t;
          return { ...t, ...updates, leaving: false };
        })
      );

      if (updates.duration !== undefined) {
        const oldTimer = timers.current.get(id);
        if (oldTimer) window.clearTimeout(oldTimer);
        if (updates.duration > 0) {
          timers.current.set(id, window.setTimeout(() => dismiss(id), updates.duration));
        } else {
          timers.current.delete(id);
        }
      }
    },
    [dismiss]
  );

  const triggerToast = useCallback(
    (options: ToastOptions) => {
      const id = nextId.current;
      nextId.current += 1;

      setToasts((prev) => [...prev, { ...options, id }].slice(-limit));

      const lifetime = options.duration ?? duration;
      if (lifetime > 0) {
        timers.current.set(id, window.setTimeout(() => dismiss(id), lifetime));
      }
      return id;
    },
    [duration, dismiss, limit]
  );

  const promiseFn = useCallback(
    <T,>(
      promiseOrFn: Promise<T> | (() => Promise<T>),
      promiseOptions: ToastPromiseOptions<T>
    ): Promise<T> => {
      const loadingOpts = normalizeInput(promiseOptions.loading, 'info');
      const id = triggerToast({ ...loadingOpts, duration: loadingOpts.duration ?? 0 });

      const p = typeof promiseOrFn === 'function' ? promiseOrFn() : promiseOrFn;

      return p
        .then((data) => {
          const rawSuccess =
            typeof promiseOptions.success === 'function'
              ? promiseOptions.success(data)
              : promiseOptions.success;
          const successOpts = normalizeInput(rawSuccess, 'success');
          update(id, {
            ...successOpts,
            duration: successOpts.duration ?? duration,
          });
          return data;
        })
        .catch((err) => {
          const rawError =
            typeof promiseOptions.error === 'function'
              ? promiseOptions.error(err)
              : promiseOptions.error;
          const errorOpts = normalizeInput(rawError, 'danger');
          update(id, {
            ...errorOpts,
            duration: errorOpts.duration ?? duration,
          });
          throw err;
        });
    },
    [triggerToast, update, duration]
  );

  const toastObj = useMemo<ToastFunction>(() => {
    return Object.assign(
      (input: ToastInput) => triggerToast(normalizeInput(input)),
      {
        info: (input: ToastInput, desc?: ReactNode) =>
          triggerToast(normalizeInput(input, 'info', desc)),
        success: (input: ToastInput, desc?: ReactNode) =>
          triggerToast(normalizeInput(input, 'success', desc)),
        warning: (input: ToastInput, desc?: ReactNode) =>
          triggerToast(normalizeInput(input, 'warning', desc)),
        danger: (input: ToastInput, desc?: ReactNode) =>
          triggerToast(normalizeInput(input, 'danger', desc)),
        error: (input: ToastInput, desc?: ReactNode) =>
          triggerToast(normalizeInput(input, 'danger', desc)),
        dismiss,
        update,
        promise: promiseFn,
      }
    );
  }, [triggerToast, dismiss, update, promiseFn]);

  useEffect(() => {
    activeToastFn = toastObj;
    activeDismissFn = dismiss;
    return () => {
      if (activeToastFn === toastObj) {
        activeToastFn = null;
        activeDismissFn = null;
      }
    };
  }, [toastObj, dismiss]);

  const value = useMemo(() => ({ toast: toastObj, dismiss }), [toastObj, dismiss]);

  return (
    <ToastContext.Provider value={value}>
      {children}
      <Portal>
        <div
          className={cn('pui-toaster', `pui-toaster--${placement}`)}
          role="region"
          aria-label="Notifications"
        >
          {toasts.map((record) => {
            const IconComponent = TONE_ICONS[record.tone ?? 'info'];
            const assertive = record.tone === 'danger' || record.tone === 'warning';
            return (
              <div
                key={record.id}
                role={assertive ? 'alert' : 'status'}
                aria-live={assertive ? 'assertive' : 'polite'}
                aria-atomic="true"
                className={cn(
                  'pui-toast',
                  `pui-toast--${record.tone ?? 'info'}`,
                  record.leaving && 'pui-toast--leaving'
                )}
              >
                <span className="pui-toast__icon">
                  <IconComponent />
                </span>
                <div className="pui-toast__body">
                  <div className="pui-toast__title">{record.title}</div>
                  {record.description && (
                    <div className="pui-toast__desc">{record.description}</div>
                  )}
                  {record.action && (
                    <div style={{ marginTop: 'var(--pui-space-2)' }}>{record.action}</div>
                  )}
                </div>
                <button
                  type="button"
                  className="pui-toast__close"
                  aria-label="Dismiss notification"
                  onClick={() => dismiss(record.id)}
                >
                  <XIcon size="1rem" />
                </button>
              </div>
            );
          })}
        </div>
      </Portal>
    </ToastContext.Provider>
  );
}

export function useToast(): ToastContextValue {
  const context = useContext(ToastContext);
  if (!context) {
    throw new Error('useToast() must be used inside <ToastProvider>.');
  }
  return context;
}

import { forwardRef, type ButtonHTMLAttributes, type ReactNode } from 'react';
import { cn } from '../utils/cn';
import { useControllableState } from '../hooks/useControllableState';

export interface ToggleProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'onChange' | 'value'> {
  /** Controlled pressed state. */
  pressed?: boolean;
  /** Default pressed state when uncontrolled. */
  defaultPressed?: boolean;
  /** Callback fired when pressed state toggles. */
  onPressedChange?: (pressed: boolean) => void;
  /** Visual variant. @default 'default' */
  variant?: 'default' | 'outline' | 'subtle';
  /** Size variant. @default 'md' */
  size?: 'sm' | 'md' | 'lg';
  /** Child content or icon. */
  children?: ReactNode;
}

/**
 * Toggle button with 2-state on/off behavior and full ARIA `aria-pressed` compliance.
 */
export const Toggle = forwardRef<HTMLButtonElement, ToggleProps>(function Toggle(
  {
    pressed: controlledPressed,
    defaultPressed = false,
    onPressedChange,
    variant = 'default',
    size = 'md',
    disabled = false,
    className,
    children,
    onClick,
    ...props
  },
  ref
) {
  const [isPressed, setIsPressed] = useControllableState({
    value: controlledPressed,
    defaultValue: defaultPressed,
    onChange: onPressedChange,
  });

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (disabled) return;
    setIsPressed(!isPressed);
    onClick?.(e);
  };

  return (
    <button
      ref={ref}
      type="button"
      aria-pressed={isPressed}
      disabled={disabled}
      data-state={isPressed ? 'on' : 'off'}
      onClick={handleClick}
      className={cn(
        'pui-toggle',
        `pui-toggle--${variant}`,
        `pui-toggle--${size}`,
        isPressed && 'pui-toggle--pressed',
        disabled && 'pui-toggle--disabled',
        className
      )}
      {...props}
    >
      {children}
    </button>
  );
});

Toggle.displayName = 'Toggle';

import {
  createContext,
  forwardRef,
  useContext,
  type ReactNode,
  type KeyboardEvent,
} from 'react';
import { cn } from '../utils/cn';
import { useControllableState } from '../hooks/useControllableState';

interface ToggleGroupContextValue {
  type: 'single' | 'multiple';
  value: string | string[];
  onItemToggle: (itemValue: string) => void;
  variant: 'default' | 'outline' | 'subtle';
  size: 'sm' | 'md' | 'lg';
  disabled?: boolean;
}

const ToggleGroupContext = createContext<ToggleGroupContextValue | null>(null);

export interface ToggleGroupProps {
  /** Selection mode: 'single' (radio-like) or 'multiple' (checkbox-like). @default 'single' */
  type?: 'single' | 'multiple';
  /** Controlled value (string for single, string[] for multiple). */
  value?: string | string[];
  /** Default value when uncontrolled. */
  defaultValue?: string | string[];
  /** Callback fired when selection changes. */
  onChange?: (value: any) => void;
  /** Visual variant. @default 'default' */
  variant?: 'default' | 'outline' | 'subtle';
  /** Size variant. @default 'md' */
  size?: 'sm' | 'md' | 'lg';
  /** Orientation. @default 'horizontal' */
  orientation?: 'horizontal' | 'vertical';
  /** Whether the entire group is disabled. */
  disabled?: boolean;
  /** Accessible label. */
  'aria-label'?: string;
  /** Custom class name. */
  className?: string;
  children?: ReactNode;
}

/**
 * ToggleGroup manages a set of mutually exclusive (single) or non-exclusive (multiple) toggle buttons.
 */
export const ToggleGroup = forwardRef<HTMLDivElement, ToggleGroupProps>(function ToggleGroup(
  {
    type = 'single',
    value: controlledValue,
    defaultValue,
    onChange,
    variant = 'default',
    size = 'md',
    orientation = 'horizontal',
    disabled = false,
    'aria-label': ariaLabel,
    className,
    children,
    ...props
  },
  ref
) {
  const [currentValue, setCurrentValue] = useControllableState<string | string[]>({
    value: controlledValue,
    defaultValue: defaultValue ?? (type === 'multiple' ? [] : ''),
    onChange,
  });

  const onItemToggle = (itemValue: string) => {
    if (disabled) return;
    if (type === 'single') {
      const next = currentValue === itemValue ? '' : itemValue;
      setCurrentValue(next);
    } else {
      const arr = Array.isArray(currentValue) ? currentValue : [];
      const next = arr.includes(itemValue)
        ? arr.filter((v) => v !== itemValue)
        : [...arr, itemValue];
      setCurrentValue(next);
    }
  };

  return (
    <ToggleGroupContext.Provider
      value={{
        type,
        value: currentValue,
        onItemToggle,
        variant,
        size,
        disabled,
      }}
    >
      <div
        ref={ref}
        role="group"
        aria-label={ariaLabel}
        aria-orientation={orientation}
        className={cn(
          'pui-toggle-group',
          `pui-toggle-group--${orientation}`,
          `pui-toggle-group--${variant}`,
          `pui-toggle-group--${size}`,
          disabled && 'pui-toggle-group--disabled',
          className
        )}
        {...props}
      >
        {children}
      </div>
    </ToggleGroupContext.Provider>
  );
});

ToggleGroup.displayName = 'ToggleGroup';

export interface ToggleGroupItemProps {
  /** Unique value representing this option. */
  value: string;
  /** Whether this specific item is disabled. */
  disabled?: boolean;
  /** Accessible label. */
  'aria-label'?: string;
  /** Custom class name. */
  className?: string;
  children?: ReactNode;
}

export const ToggleGroupItem = forwardRef<HTMLButtonElement, ToggleGroupItemProps>(
  function ToggleGroupItem(
    { value, disabled: itemDisabled, className, children, 'aria-label': ariaLabel, ...props },
    ref
  ) {
    const ctx = useContext(ToggleGroupContext);
    if (!ctx) {
      throw new Error('ToggleGroupItem must be used within a ToggleGroup');
    }

    const isSelected =
      ctx.type === 'single'
        ? ctx.value === value
        : Array.isArray(ctx.value) && ctx.value.includes(value);

    const isDisabled = ctx.disabled || itemDisabled;

    return (
      <button
        ref={ref}
        type="button"
        role="radio"
        aria-checked={isSelected}
        aria-pressed={isSelected}
        aria-label={ariaLabel}
        disabled={isDisabled}
        data-state={isSelected ? 'on' : 'off'}
        onClick={() => ctx.onItemToggle(value)}
        className={cn(
          'pui-toggle-group__item',
          isSelected && 'pui-toggle-group__item--selected',
          isDisabled && 'pui-toggle-group__item--disabled',
          className
        )}
        {...props}
      >
        {children}
      </button>
    );
  }
);

ToggleGroupItem.displayName = 'ToggleGroupItem';

import React, {
  cloneElement,
  useId,
  useRef,
  useState,
  type ReactElement,
  type ReactNode,
} from 'react';
import { cn } from '../utils/cn';
import { Portal } from './Portal';
import { useFloating } from '../hooks/useFloating';

export type TooltipTone = 'dark' | 'light' | 'primary' | 'invert';

export interface TooltipProps {
  /** Text or rich content rendered inside the tooltip bubble. */
  content: ReactNode;
  /** Trigger element that spawns the tooltip. */
  children: ReactElement;
  /** Placement direction relative to the trigger element. @default 'top' */
  placement?: 'top' | 'bottom' | 'left' | 'right';
  /** Visual tone styling theme. @default 'dark' */
  tone?: TooltipTone;
  /** Render an anchor arrow pointer. @default false */
  arrow?: boolean;
  /** Optional keyboard shortcut badge displayed alongside content (e.g. '⌘K'). */
  shortcut?: string;
  /** Whether the user can hover into the tooltip itself (e.g. to click links or copy text). @default false */
  interactive?: boolean;
  /** Milliseconds before the tooltip appears on hover. @default 180 */
  delay?: number;
  /** Milliseconds before the tooltip hides after pointer leaves. @default 100 */
  closeDelay?: number;
  /** Pixel distance between trigger and tooltip. @default 8 */
  offset?: number;
  /** Disable the tooltip completely. */
  disabled?: boolean;
  /** Controlled open state. */
  open?: boolean;
  /** Callback fired when open state changes in controlled mode. */
  onOpenChange?: (open: boolean) => void;
  /** Optional custom class name. */
  className?: string;
}

/**
 * Tooltip wired for both input methods:
 *
 * - Hover (pointer) shows after `delay`.
 * - Keyboard focus shows immediately, ensuring full keyboard parity.
 * - Escape hides immediately.
 * - Supports tones ('dark', 'light', 'primary'), arrows, shortcuts, and interactive mode.
 */
export function Tooltip({
  content,
  children,
  placement = 'top',
  tone = 'dark',
  arrow = false,
  shortcut,
  interactive = false,
  delay = 180,
  closeDelay = 100,
  offset = 8,
  disabled = false,
  open: controlledOpen,
  onOpenChange,
  className,
}: TooltipProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(false);
  const isControlled = controlledOpen !== undefined;
  const isOpen = (isControlled ? controlledOpen : uncontrolledOpen) && !disabled;

  const anchorRef = useRef<HTMLElement | null>(null);
  const tooltipRef = useRef<HTMLDivElement | null>(null);
  const timerRef = useRef<number | null>(null);
  const id = `pui-tip-${useId()}`;

  const { setFloating, coords, ready } = useFloating<HTMLDivElement>(
    anchorRef as React.RefObject<HTMLElement>,
    isOpen,
    { placement, align: 'center', offset }
  );

  const clearTimer = () => {
    if (timerRef.current) {
      window.clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  };

  const setOpenState = (next: boolean) => {
    if (!isControlled) setUncontrolledOpen(next);
    onOpenChange?.(next);
  };

  const show = (immediate = false) => {
    if (disabled) return;
    clearTimer();
    if (immediate) {
      setOpenState(true);
    } else {
      timerRef.current = window.setTimeout(() => setOpenState(true), delay);
    }
  };

  const hide = (immediate = false) => {
    clearTimer();
    if (immediate || !interactive) {
      setOpenState(false);
    } else {
      timerRef.current = window.setTimeout(() => setOpenState(false), closeDelay);
    }
  };

  const trigger = cloneElement(children, {
    ref: (node: HTMLElement | null) => {
      anchorRef.current = node;
      const childRef = (children as ReactElement & { ref?: unknown }).ref;
      if (typeof childRef === 'function') childRef(node);
      else if (childRef && typeof childRef === 'object') {
        (childRef as { current: unknown }).current = node;
      }
    },
    'aria-describedby': isOpen ? id : undefined,
    onMouseEnter: (event: React.MouseEvent) => {
      show(false);
      (children.props as { onMouseEnter?: (e: React.MouseEvent) => void }).onMouseEnter?.(event);
    },
    onMouseLeave: (event: React.MouseEvent) => {
      hide(false);
      (children.props as { onMouseLeave?: (e: React.MouseEvent) => void }).onMouseLeave?.(event);
    },
    onFocus: (event: React.FocusEvent) => {
      show(true);
      (children.props as { onFocus?: (e: React.FocusEvent) => void }).onFocus?.(event);
    },
    onBlur: (event: React.FocusEvent) => {
      hide(true);
      (children.props as { onBlur?: (e: React.FocusEvent) => void }).onBlur?.(event);
    },
    onKeyDown: (event: React.KeyboardEvent) => {
      if (event.key === 'Escape') hide(true);
      (children.props as { onKeyDown?: (e: React.KeyboardEvent) => void }).onKeyDown?.(event);
    },
  } as Partial<unknown> as never);

  return (
    <>
      {trigger}
      {isOpen && (
        <Portal>
          <div
            ref={(node) => {
              tooltipRef.current = node;
              setFloating(node);
            }}
            id={id}
            role="tooltip"
            className={cn(
              'pui-tooltip',
              `pui-tooltip--${tone}`,
              `pui-tooltip--${placement}`,
              interactive && 'pui-tooltip--interactive',
              className
            )}
            style={{
              top: coords.y,
              left: coords.x,
              visibility: ready ? 'visible' : 'hidden',
              pointerEvents: interactive ? 'auto' : 'none',
            }}
            onMouseEnter={interactive ? () => clearTimer() : undefined}
            onMouseLeave={interactive ? () => hide(false) : undefined}
          >
            {arrow && <span className="pui-tooltip__arrow" aria-hidden="true" />}
            <span className="pui-tooltip__content">{content}</span>
            {shortcut && (
              <kbd className="pui-tooltip__kbd" aria-hidden="true">
                {shortcut}
              </kbd>
            )}
          </div>
        </Portal>
      )}
    </>
  );
}

import React, {
  useEffect,
  useState,
  useRef,
  useCallback,
  type ReactNode,
  type HTMLAttributes,
} from 'react';
import { Portal } from './Portal';
import { Button } from './Button';
import { XIcon, ChevronRightIcon, ChevronLeftIcon } from './icons';
import { cn } from '../utils/cn';

export interface TourStep {
  /** CSS selector or element query for the spotlight anchor (e.g. '#header-nav', '[data-tour="search"]') */
  target?: string | (() => HTMLElement | null);
  /** Title header for this tour step. */
  title: ReactNode;
  /** Detailed explanatory content or walkthrough guidance. */
  description: ReactNode;
  /** Preferred popover placement relative to target. Defaults to 'bottom'. */
  placement?: 'top' | 'bottom' | 'left' | 'right' | 'center';
  /** Optional custom footer actions replacing default Previous/Next/Finish. */
  actions?: ReactNode;
  /** Optional custom icon or illustration to show at the top of the step card. */
  icon?: ReactNode;
}

export interface TourProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange'> {
  /** The sequential array of walkthrough steps. */
  steps: TourStep[];
  /** Controlled visibility state of the tour modal. */
  open: boolean;
  /** Callback fired when the tour is closed, dismissed, or finished. */
  onClose: () => void;
  /** Controlled active step index (0-indexed). */
  current?: number;
  /** Callback fired when active step changes. */
  onChange?: (current: number) => void;
  /** Whether to render an elevated spotlight backdrop around the target. Defaults to true. */
  mask?: boolean;
  /** Whether clicking the backdrop dismisses the tour. Defaults to false. */
  maskClosable?: boolean;
  /** Custom text for finish button. Defaults to 'Get Started'. */
  finishText?: string;
}

interface TargetRect {
  top: number;
  left: number;
  width: number;
  height: number;
  bottom: number;
  right: number;
}

export function Tour({
  steps,
  open,
  onClose,
  current: controlledCurrent,
  onChange,
  mask = true,
  maskClosable = false,
  finishText = 'Get Started',
  className,
  ...rest
}: TourProps) {
  const [internalCurrent, setInternalCurrent] = useState(0);
  const activeIndex = controlledCurrent !== undefined ? controlledCurrent : internalCurrent;
  const currentStep = steps[activeIndex] || steps[0];

  const [rect, setRect] = useState<TargetRect | null>(null);
  const popoverRef = useRef<HTMLDivElement>(null);

  const setCurrent = useCallback(
    (nextIndex: number) => {
      if (controlledCurrent === undefined) {
        setInternalCurrent(nextIndex);
      }
      onChange?.(nextIndex);
    },
    [controlledCurrent, onChange]
  );

  // Update target rect on step change or resize/scroll
  const updateRect = useCallback(() => {
    if (!open || !currentStep) {
      setRect(null);
      return;
    }

    let el: HTMLElement | null = null;
    if (typeof currentStep.target === 'function') {
      el = currentStep.target();
    } else if (typeof currentStep.target === 'string') {
      el = document.querySelector(currentStep.target);
    }

    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'nearest' });
      const b = el.getBoundingClientRect();
      const padding = 6;
      setRect({
        top: Math.max(0, b.top - padding),
        left: Math.max(0, b.left - padding),
        width: b.width + padding * 2,
        height: b.height + padding * 2,
        bottom: b.bottom + padding,
        right: b.right + padding,
      });
    } else {
      setRect(null);
    }
  }, [open, currentStep]);

  useEffect(() => {
    updateRect();
    window.addEventListener('resize', updateRect);
    window.addEventListener('scroll', updateRect, true);
    return () => {
      window.removeEventListener('resize', updateRect);
      window.removeEventListener('scroll', updateRect, true);
    };
  }, [updateRect]);

  // Keyboard navigation
  useEffect(() => {
    if (!open) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
      } else if (e.key === 'ArrowRight') {
        if (activeIndex < steps.length - 1) setCurrent(activeIndex + 1);
      } else if (e.key === 'ArrowLeft') {
        if (activeIndex > 0) setCurrent(activeIndex - 1);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [open, activeIndex, steps.length, setCurrent, onClose]);

  if (!open || steps.length === 0 || !currentStep) return null;
  const step = currentStep;

  const isFirst = activeIndex === 0;
  const isLast = activeIndex === steps.length - 1;

  // Compute popover position relative to target rect
  const placement = step.placement || (rect ? 'bottom' : 'center');

  let popoverStyle: React.CSSProperties = {
    position: 'fixed',
    zIndex: 10001,
  };

  if (!rect || placement === 'center') {
    popoverStyle = {
      ...popoverStyle,
      top: '50%',
      left: '50%',
      transform: 'translate(-50%, -50%)',
    };
  } else {
    const popoverWidth = 360;
    const margin = 14;

    if (placement === 'bottom') {
      const top = Math.min(window.innerHeight - 260, rect.bottom + margin);
      const left = Math.max(16, Math.min(window.innerWidth - popoverWidth - 16, rect.left + rect.width / 2 - popoverWidth / 2));
      popoverStyle = { ...popoverStyle, top: `${top}px`, left: `${left}px` };
    } else if (placement === 'top') {
      const top = Math.max(16, rect.top - margin - 220);
      const left = Math.max(16, Math.min(window.innerWidth - popoverWidth - 16, rect.left + rect.width / 2 - popoverWidth / 2));
      popoverStyle = { ...popoverStyle, top: `${top}px`, left: `${left}px` };
    } else if (placement === 'left') {
      const top = Math.max(16, Math.min(window.innerHeight - 240, rect.top + rect.height / 2 - 100));
      const left = Math.max(16, rect.left - popoverWidth - margin);
      popoverStyle = { ...popoverStyle, top: `${top}px`, left: `${left}px` };
    } else if (placement === 'right') {
      const top = Math.max(16, Math.min(window.innerHeight - 240, rect.top + rect.height / 2 - 100));
      const left = Math.min(window.innerWidth - popoverWidth - 16, rect.right + margin);
      popoverStyle = { ...popoverStyle, top: `${top}px`, left: `${left}px` };
    }
  }

  return (
    <Portal>
      {/* Mask with SVG cutout spotlight */}
      {mask && (
        <div
          onClick={maskClosable ? onClose : undefined}
          style={{
            position: 'fixed',
            inset: 0,
            zIndex: 10000,
            pointerEvents: maskClosable ? 'auto' : 'none',
          }}
        >
          <svg
            width="100%"
            height="100%"
            style={{
              position: 'fixed',
              inset: 0,
              width: '100vw',
              height: '100vh',
              pointerEvents: 'none',
            }}
          >
            <defs>
              <mask id="pui-tour-mask">
                <rect x="0" y="0" width="100%" height="100%" fill="#fff" />
                {rect && (
                  <rect
                    x={rect.left}
                    y={rect.top}
                    width={rect.width}
                    height={rect.height}
                    rx="8"
                    ry="8"
                    fill="#000"
                  />
                )}
              </mask>
            </defs>
            <rect
              x="0"
              y="0"
              width="100%"
              height="100%"
              fill="rgba(0, 0, 0, 0.65)"
              mask="url(#pui-tour-mask)"
            />
          </svg>

          {/* Glowing ring around spotlight target */}
          {rect && (
            <div
              style={{
                position: 'fixed',
                top: `${rect.top}px`,
                left: `${rect.left}px`,
                width: `${rect.width}px`,
                height: `${rect.height}px`,
                borderRadius: '8px',
                boxShadow: '0 0 0 2px var(--pui-primary, #6366f1), 0 0 20px rgba(99, 102, 241, 0.35)',
                pointerEvents: 'none',
                transition: 'all 0.25s cubic-bezier(0.16, 1, 0.3, 1)',
              }}
            />
          )}
        </div>
      )}

      {/* Popover Step Card */}
      <div
        ref={popoverRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="pui-tour-title"
        className={cn('pui-tour-card', className)}
        style={{
          ...popoverStyle,
          width: '360px',
          maxWidth: 'calc(100vw - 32px)',
          background: 'var(--pui-surface, #ffffff)',
          color: 'var(--pui-fg, #0f172a)',
          border: '1px solid var(--pui-border, #e2e8f0)',
          borderRadius: 'var(--pui-radius-lg, 12px)',
          boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.2), 0 8px 10px -6px rgba(0, 0, 0, 0.1)',
          padding: '1.25rem',
          display: 'flex',
          flexDirection: 'column',
          gap: '0.875rem',
          animation: 'pui-tour-pop 0.2s cubic-bezier(0.16, 1, 0.3, 1)',
        }}
        {...rest}
      >
        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: '0.75rem' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.625rem' }}>
            {step.icon && (
              <span
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  width: '2rem',
                  height: '2rem',
                  borderRadius: 'var(--pui-radius-md, 8px)',
                  background: 'var(--pui-primary-subtle, rgba(99, 102, 241, 0.1))',
                  color: 'var(--pui-primary, #6366f1)',
                  flexShrink: 0,
                }}
              >
                {step.icon}
              </span>
            )}
            <h3
              id="pui-tour-title"
              style={{
                margin: 0,
                fontSize: '1rem',
                fontWeight: 600,
                color: 'var(--pui-fg, #0f172a)',
                lineHeight: 1.3,
              }}
            >
              {step.title}
            </h3>
          </div>

          <button
            type="button"
            onClick={onClose}
            aria-label="Close tour"
            style={{
              background: 'none',
              border: 'none',
              padding: '0.25rem',
              color: 'var(--pui-fg-muted, #64748b)',
              cursor: 'pointer',
              borderRadius: 'var(--pui-radius-sm, 4px)',
              display: 'inline-flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            <XIcon size={16} />
          </button>
        </div>

        {/* Body content */}
        <div
          style={{
            fontSize: '0.875rem',
            color: 'var(--pui-fg-muted, #475569)',
            lineHeight: 1.5,
          }}
        >
          {step.description}
        </div>

        {/* Footer actions */}
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            paddingTop: '0.5rem',
            borderTop: '1px solid var(--pui-border, #f1f5f9)',
            marginTop: '0.25rem',
          }}
        >
          {/* Step dots */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.375rem' }}>
            {steps.map((_, i) => (
              <button
                key={i}
                type="button"
                onClick={() => setCurrent(i)}
                aria-label={`Jump to step ${i + 1}`}
                style={{
                  width: i === activeIndex ? '1.25rem' : '0.375rem',
                  height: '0.375rem',
                  borderRadius: '9999px',
                  background:
                    i === activeIndex
                      ? 'var(--pui-primary, #6366f1)'
                      : 'var(--pui-border-strong, #cbd5e1)',
                  border: 'none',
                  padding: 0,
                  cursor: 'pointer',
                  transition: 'all 0.2s ease',
                }}
              />
            ))}
            <span
              style={{
                marginLeft: '0.375rem',
                fontSize: '0.75rem',
                fontWeight: 500,
                color: 'var(--pui-fg-muted, #94a3b8)',
              }}
            >
              {activeIndex + 1}/{steps.length}
            </span>
          </div>

          {/* Action buttons */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            {!isFirst && (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setCurrent(activeIndex - 1)}
              >
                <ChevronLeftIcon size={14} /> Back
              </Button>
            )}

            {isLast ? (
              <Button
                variant="primary"
                size="sm"
                onClick={onClose}
              >
                {finishText}
              </Button>
            ) : (
              <Button
                variant="primary"
                size="sm"
                onClick={() => setCurrent(activeIndex + 1)}
              >
                Next <ChevronRightIcon size={14} />
              </Button>
            )}
          </div>
        </div>
      </div>
    </Portal>
  );
}

import React, {
  forwardRef,
  useState,
  type ReactNode,
  type KeyboardEvent,
  type HTMLAttributes,
} from 'react';
import { cn } from '../utils/cn';
import { ChevronRightIcon, FolderIcon, FolderOpenIcon, FileIcon } from './icons';

export interface TreeNode {
  id: string;
  label: ReactNode;
  icon?: ReactNode;
  children?: TreeNode[];
  disabled?: boolean;
}

export interface TreeProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onSelect'> {
  /** Root hierarchical tree nodes. */
  data: readonly TreeNode[];
  /** Controlled array of expanded node IDs. */
  expandedIds?: string[];
  /** Default array of expanded node IDs. */
  defaultExpandedIds?: string[];
  /** Callback fired when a node is expanded or collapsed. */
  onToggle?: (nodeId: string, expanded: boolean) => void;
  /** Controlled ID of currently selected node. */
  selectedId?: string;
  /** Callback fired when a node is selected. */
  onSelect?: (nodeId: string, node: TreeNode) => void;
  /** Accessible label. @default 'File Tree' */
  'aria-label'?: string;
}

/**
 * Tree displays hierarchical folder and file directories with keyboard navigation.
 * Highly accessible, with indent guidelines and responsive mobile scaling.
 */
export const Tree = forwardRef<HTMLDivElement, TreeProps>(
  (
    {
      data,
      expandedIds: controlledExpandedIds,
      defaultExpandedIds = [],
      onToggle,
      selectedId,
      onSelect,
      'aria-label': ariaLabel = 'File Tree',
      className,
      ...props
    },
    ref
  ) => {
    const isControlled = controlledExpandedIds !== undefined;
    const [internalExpanded, setInternalExpanded] = useState<string[]>(defaultExpandedIds);
    const expandedList = isControlled ? controlledExpandedIds : internalExpanded;

    const isExpanded = (id: string) => expandedList.includes(id);

    const toggleNode = (id: string) => {
      const willExpand = !isExpanded(id);
      if (!isControlled) {
        setInternalExpanded((prev) =>
          willExpand ? [...prev, id] : prev.filter((i) => i !== id)
        );
      }
      onToggle?.(id, willExpand);
    };

    const renderNode = (node: TreeNode, depth = 0) => {
      const hasChildren = Boolean(node.children && node.children.length > 0);
      const expanded = isExpanded(node.id);
      const isSelected = selectedId === node.id;

      const defaultIcon = hasChildren ? (
        expanded ? <FolderOpenIcon size={16} /> : <FolderIcon size={16} />
      ) : (
        <FileIcon size={16} />
      );

      const handleRowClick = () => {
        if (node.disabled) return;
        if (hasChildren) {
          toggleNode(node.id);
        }
        onSelect?.(node.id, node);
      };

      const handleKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
        if (node.disabled) return;

        if (e.key === 'ArrowRight' && hasChildren && !expanded) {
          e.preventDefault();
          toggleNode(node.id);
        } else if (e.key === 'ArrowLeft' && hasChildren && expanded) {
          e.preventDefault();
          toggleNode(node.id);
        } else if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          handleRowClick();
        }
      };

      return (
        <div key={node.id} className="pui-tree__node" role="treeitem" aria-expanded={hasChildren ? expanded : undefined}>
          <div
            tabIndex={node.disabled ? -1 : 0}
            role="button"
            aria-selected={isSelected}
            className={cn(
              'pui-tree__row',
              isSelected && 'pui-tree__row--selected',
              node.disabled && 'pui-tree__row--disabled'
            )}
            style={{ paddingLeft: `calc(var(--pui-tree-indent, 1.125rem) * ${depth} + 0.5rem)` }}
            onClick={handleRowClick}
            onKeyDown={handleKeyDown}
          >
            {hasChildren ? (
              <span
                className={cn('pui-tree__chevron', expanded && 'pui-tree__chevron--expanded')}
                aria-hidden="true"
              >
                <ChevronRightIcon size={14} />
              </span>
            ) : (
              <span className="pui-tree__spacer" aria-hidden="true" />
            )}

            <span className="pui-tree__icon" aria-hidden="true">
              {node.icon || defaultIcon}
            </span>

            <span className="pui-tree__label">{node.label}</span>
          </div>

          {hasChildren && expanded && (
            <div className="pui-tree__branch" role="group">
              {node.children!.map((child) => renderNode(child, depth + 1))}
            </div>
          )}
        </div>
      );
    };

    return (
      <div
        ref={ref}
        role="tree"
        aria-label={ariaLabel}
        className={cn('pui-tree', className)}
        {...props}
      >
        {data.map((rootNode) => renderNode(rootNode, 0))}
      </div>
    );
  }
);

Tree.displayName = 'Tree';
